# Global storage for analysis status with persistence
analysis_status = {}
cancellation_flags = {}  # Track cancellation requests
analysis_status_lock = RLock()  # Thread safety for analysis_status (re-entrant for save helpers)
cancellation_flags_lock = Lock()  # Thread safety for cancellation_flags


# Round 13 / Phase 11.4: TTL-based eviction for ``analysis_status``.
# Previously this dict only ever grew: a successful run wrote the
# completed status, a crashed run wrote an error status, and the
# only path that ever removed an entry was the explicit
# ``DELETE /admin/analyses/<id>`` admin call.  A long-running
# server therefore accumulated thousands of historical records,
# inflating every ``/api/status/all`` poll, and once the
# pickled ``analysis_status.json`` crossed ~5MB the on-disk
# round-trip itself became a noticeable hot path.  Apply a
# defensive TTL: any *terminal* status (``completed`` or
# ``error``) older than ``ADOPTIQ_STATUS_TTL_HOURS`` (default
# 168 = 7 days) is dropped on the next eviction sweep.  Active
# (``processing`` / ``starting``) entries are *never* evicted by
# TTL -- they survive until they themselves move to a terminal
# state.  Eviction only runs lazily (on next mutation) so a quiet
# process does not pay the sweep cost.
_ANALYSIS_STATUS_TTL_HOURS = max(
    1, int(os.environ.get("ADOPTIQ_STATUS_TTL_HOURS", "168"))
)
_ANALYSIS_STATUS_LAST_SWEEP: List[float] = [0.0]
_ANALYSIS_STATUS_SWEEP_INTERVAL_SECONDS = 600.0  # 10 minutes


def _r13_unique_upload_filename(uuid_module, raw_name: str, file_obj) -> str:
    """Round 13 / Phase 11.7: deterministic-in-test-mode upload prefix.

    Previously every upload prepended ``uuid.uuid4().hex[:8]_`` so
    a test could not assert against the saved filename without
    monkeypatching ``uuid.uuid4``.  Under
    ``ADOPTIQ_TEST_MODE`` (or when running under pytest), derive
    the prefix from a SHA-256 of the file content (first 8 hex
    chars) so two test runs against the same upload produce the
    same filename.  Production behavior is unchanged: a random
    ``uuid4`` prefix is still used so concurrent uploads of the
    same content cannot collide on a real deployment.
    """
    try:
        _r13_test_mode = bool(
            os.environ.get("ADOPTIQ_TEST_MODE")
            or os.environ.get("PYTEST_CURRENT_TEST")
        )
    except Exception:
        _r13_test_mode = False
    if not _r13_test_mode:
        return f"{uuid_module.uuid4().hex[:8]}_{raw_name}"
    # Test mode: hash the file body for determinism.  Reset the
    # stream position so the subsequent ``file.save(filepath)``
    # still writes the full body.
    try:
        import hashlib as _hashlib
        try:
            file_obj.stream.seek(0)
        except Exception:
            try:
                file_obj.seek(0)
            except Exception:
                pass
        try:
            _body = file_obj.stream.read()
        except Exception:
            try:
                _body = file_obj.read()
            except Exception:
                _body = b""
        try:
            file_obj.stream.seek(0)
        except Exception:
            try:
                file_obj.seek(0)
            except Exception:
                pass
        _digest = _hashlib.sha256(_body or b"").hexdigest()[:8]
        return f"{_digest}_{raw_name}"
    except Exception:
        return f"{uuid_module.uuid4().hex[:8]}_{raw_name}"


def _r13_evict_stale_analysis_status() -> int:
    """Drop terminal ``analysis_status`` entries older than the TTL.

    Returns the number of entries evicted.  Caller MUST hold
    ``analysis_status_lock``.  The function self-throttles: it
    runs at most once per ``_ANALYSIS_STATUS_SWEEP_INTERVAL_SECONDS``
    so a tight burst of mutations does not pay the sweep cost on
    every call.
    """
    try:
        _now_mono = time.monotonic()
        if (
            _now_mono - _ANALYSIS_STATUS_LAST_SWEEP[0]
            < _ANALYSIS_STATUS_SWEEP_INTERVAL_SECONDS
        ):
            return 0
        _ANALYSIS_STATUS_LAST_SWEEP[0] = _now_mono

        _ttl_seconds = float(_ANALYSIS_STATUS_TTL_HOURS) * 3600.0
        _now_dt = datetime.now(timezone.utc)
        _evict: List[str] = []
        for _aid, _entry in list(analysis_status.items()):
            try:
                _status = str(_entry.get("status") or "").lower()
                if _status not in ("completed", "error", "cancelled", "failed"):
                    continue
                _ts = (
                    _entry.get("end_time")
                    or _entry.get("completion_time")
                    or _entry.get("start_time")
                )
                if not _ts:
                    continue
                # ``_ts`` may be a datetime (naive UTC by convention)
                # or an ISO string; normalize defensively.
                if isinstance(_ts, datetime):
                    _ts_dt = _ts
                else:
                    try:
                        _ts_dt = datetime.fromisoformat(str(_ts).replace("Z", "+00:00"))
                    except Exception:
                        continue
                if _ts_dt.tzinfo is None:
                    _ts_dt = _ts_dt.replace(tzinfo=timezone.utc)
                _age = (_now_dt - _ts_dt).total_seconds()
                if _age > _ttl_seconds:
                    _evict.append(_aid)
            except Exception:
                continue
        for _aid in _evict:
            try:
                analysis_status.pop(_aid, None)
            except Exception:
                pass
        if _evict:
            try:
                logger.info(
                    "analysis_status TTL sweep evicted %d stale terminal entries (TTL %dh)",
                    len(_evict),
                    _ANALYSIS_STATUS_TTL_HOURS,
                )
            except Exception:
                pass
        return len(_evict)
    except Exception:
        return 0

# File-based status persistence to survive Flask reloads (when frozen, cwd is _APP_SUPPORT so "analysis_status.json" works)
STATUS_FILE = "analysis_status.json"
STATUS_DATETIME_FIELDS = (
    'step_start_time',
    'estimated_completion',
    'completion_time',
    'start_time',
    'end_time',
)
INSIGHT_SUMMARY_MAX_CHARS = 200
BROWSER_LAUNCH_DELAY_SECONDS = 1.5

# Round 5 / Phase 3.10: Ask AI throttling.  The Ask AI endpoints
# (/api/ask-ai-portfolio and /api/ask-intel) are expensive --
# every call fans out to Snowflake, external intel feeds, and an
# LLM round-trip, often costing tens of seconds.  Without a per-IP
# / per-user limit a single bad client (or a refresh loop) can
# saturate the LLM circuit and starve genuine traffic.  Implement a
# minimal in-process sliding-window limiter.  This is *not* a
# replacement for an upstream gateway throttle, but it prevents the
# worst case (single client opening N tabs and DOS'ing the model).
_ASK_AI_RATE_WINDOW_SEC = float(os.environ.get("ADOPTIQ_ASK_AI_RATE_WINDOW", "60"))
_ASK_AI_RATE_MAX_CALLS = int(os.environ.get("ADOPTIQ_ASK_AI_RATE_MAX_CALLS", "10"))
_ask_ai_rate_log: Dict[str, List[float]] = {}
_ask_ai_rate_lock = Lock()


def _ask_ai_throttle_key() -> str:
    """Best-effort caller identity for throttling.

    Prefer the authenticated user ID; fall back to client IP.  If
    behind a proxy, ``X-Forwarded-For`` is honored only when the
    request reached us through the local app's reverse-proxy
    config -- otherwise headers are not trusted (a remote attacker
    can spoof them).  We additionally trim to the first hop.

    Round 7 / Phase 5.9: the throttle bookkeeping
    (``_ask_ai_rate_log``) is an in-process dict guarded by a
    ``threading.Lock``.  That is safe and accurate inside a single
    Python process, but completely ineffective when the app is
    deployed behind a multi-worker WSGI server (Gunicorn ``-w N``,
    uWSGI workers, or any pre-fork setup) because each worker has
    its own copy of the dict.  In that mode the *effective*
    per-caller cap is ``_ASK_AI_RATE_MAX_CALLS * N``, not
    ``_ASK_AI_RATE_MAX_CALLS``, and operators have been bitten by
    this in production.  We emit a one-shot WARNING the first time
    we are called when a multi-worker environment is detected, so
    the limitation appears prominently in the logs even if the
    sysadmin never reads this docstring.  The detection covers the
    common pre-fork servers; we deliberately do not raise so the
    throttle remains best-effort.
    """
    _warn_multi_worker_once()
    try:
        user = getattr(getattr(request, '_user', None), 'id', None)
        if user:
            return f"user:{user}"
    except Exception:
        pass  # noqa: PIE790
    ip = (request.remote_addr or 'unknown').strip()
    return f"ip:{ip}"


_ask_ai_multi_worker_warned = False
_ask_ai_multi_worker_warned_lock = Lock()


def _warn_multi_worker_once() -> None:
    """Round 7 / Phase 5.9: log once if Ask AI throttling is in a
    multi-worker pre-fork environment where the in-process dict
    cannot enforce a global cap.  Detection is heuristic (env vars
    set by Gunicorn / uWSGI / Hypercorn) and should not raise.
    """
    global _ask_ai_multi_worker_warned
    if _ask_ai_multi_worker_warned:
        return
    try:
        with _ask_ai_multi_worker_warned_lock:
            if _ask_ai_multi_worker_warned:
                return
            _gunicorn_workers = os.environ.get("GUNICORN_CMD_ARGS", "")
            _server_software = os.environ.get("SERVER_SOFTWARE", "")
            _is_gunicorn = (
                "gunicorn" in _server_software.lower()
                or "GUNICORN_WORKERS" in os.environ
                or "-w" in _gunicorn_workers
            )
            _is_uwsgi = (
                "uwsgi" in _server_software.lower()
                or os.environ.get("UWSGI_ORIGINAL_PROC_NAME") is not None
            )
            _is_hypercorn = "hypercorn" in _server_software.lower()
            if _is_gunicorn or _is_uwsgi or _is_hypercorn:
                logger.warning(
                    "[[WARNING]] Round 7 / Phase 5.9: Ask AI rate-limit "
                    "bookkeeping is in-process only (server_software=%r). "
                    "Per-caller throttle of %d req / %.0fs is enforced *per "
                    "worker*; the effective cap is multiplied by the worker "
                    "count.  Front the app with a shared store (Redis, "
                    "memcached) or cap workers to 1 to enforce the documented "
                    "rate limit.",
                    _server_software or "<unknown>",
                    _ASK_AI_RATE_MAX_CALLS,
                    _ASK_AI_RATE_WINDOW_SEC,
                )
            _ask_ai_multi_worker_warned = True
    except Exception:
        # Never let the diagnostic break a real request.
        _ask_ai_multi_worker_warned = True


def _check_ask_ai_throttle() -> Optional[Tuple[Dict[str, Any], int]]:
    """Return a (payload, status) tuple to short-circuit, or None.

    Sliding window: at most ``_ASK_AI_RATE_MAX_CALLS`` requests per
    ``_ASK_AI_RATE_WINDOW_SEC`` seconds per caller key.  Trims old
    entries on every call so memory stays bounded for active keys.
    """
    if _ASK_AI_RATE_MAX_CALLS <= 0 or _ASK_AI_RATE_WINDOW_SEC <= 0:
        return None  # disabled
    key = _ask_ai_throttle_key()
    # Round 12 / Phase 10.1: previously the sliding-window log used
    # ``time.time()`` (wall clock).  An NTP step or operator-driven
    # clock adjustment (DST migration, container clock skew on a
    # paused VM that resumes hours later) could shrink or extend
    # the throttle window arbitrarily -- shrinking it lets a burst
    # bypass the cap, extending it permanently locks legitimate
    # callers out because old entries stop expiring.  Use
    # ``time.monotonic()`` so the window is anchored to a clock
    # that only ever moves forward at a constant rate.
    now = time.monotonic()
    cutoff = now - _ASK_AI_RATE_WINDOW_SEC
    with _ask_ai_rate_lock:
        log = _ask_ai_rate_log.setdefault(key, [])
        # Drop entries outside the window in-place.
        while log and log[0] < cutoff:
            log.pop(0)
        if len(log) >= _ASK_AI_RATE_MAX_CALLS:
            retry_after = max(1, int(log[0] + _ASK_AI_RATE_WINDOW_SEC - now))
            return (
                {
                    'ok': False,
                    'error': (
                        f'Rate limit exceeded ({_ASK_AI_RATE_MAX_CALLS} requests '
                        f'per {int(_ASK_AI_RATE_WINDOW_SEC)}s). Please wait '
                        f'{retry_after}s and try again.'
                    ),
                    'retry_after_seconds': retry_after,
                },
                429,
            )
        log.append(now)
    return None


def _submit_with_context(executor, fn, *args, **kwargs):
    """Round 6 / Phase 7.2: submit ``fn`` to ``executor`` with the
    parent thread's ``contextvars.Context`` copied in.

    ``ThreadPoolExecutor`` worker threads inherit nothing from the
    submitting thread by default, so the ``analysis_id`` bound by
    ``structured_logging.bind_analysis_id`` -- and any other
    ``ContextVar`` carrying request-scoped state -- is silently
    dropped on the floor inside calls like ``_connect_with_keeper``.
    Wrapping the submission in ``contextvars.copy_context().run``
    propagates the parent context for the lifetime of the worker
    callable so the structured-logging adapter still emits
    ``analysis_id=<id>`` from inside the worker.
    """
    import contextvars as _cv
    _ctx = _cv.copy_context()
    return executor.submit(_ctx.run, fn, *args, **kwargs)


def _now_utc_iso_z() -> str:
    """Round 6 / Phase 6.17: canonical UTC ISO-Z timestamp helper.

    Every persisted status field (``start_time``, ``step_start_time``,
    ``completion_time``, ``end_time``) MUST go through this helper so
    the on-disk ``analysis_status.json`` and the audit JSONL mirror
    use a single, unambiguous, lexically-sortable representation
    (``YYYY-MM-DDTHH:MM:SS.ffffffZ``).  Mixing naive
    ``_now_utc_iso_z()`` (which renders local time without
    a tzinfo) with the audit table's UTC ISO-Z strings used to drift
    by whatever the host's TZ offset was, breaking ordering and date
    arithmetic in ``get_status`` and the admin KPI queries.
    """
    return datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")


def _build_insights_payload(
    status_obj: Dict[str, Any],
    default_summary: str,
    extra_fields: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    """Build normalized insights payload for audit learning store."""
    summary = (status_obj.get('message') or default_summary)[:INSIGHT_SUMMARY_MAX_CHARS]
    payload: Dict[str, Any] = {'summary_line': summary}
    if extra_fields:
        payload.update(extra_fields)
    return payload


def _sanitize_for_json(obj):
    """Recursively replace NaN/Inf floats with None so json.dumps never emits invalid tokens."""
    if isinstance(obj, dict):
        return {k: _sanitize_for_json(v) for k, v in obj.items()}
    if isinstance(obj, (list, tuple)):
        return [_sanitize_for_json(v) for v in obj]
    if isinstance(obj, float) and (math.isnan(obj) or math.isinf(obj)):
        return None
    return obj


def _json_default(obj):
    """Handle non-standard types during JSON serialization of analysis status."""
    if isinstance(obj, datetime):
        return obj.isoformat()
    if hasattr(obj, 'item'):
        val = obj.item()
        if isinstance(val, float) and (math.isnan(val) or math.isinf(val)):
            return None
        return val
    if isinstance(obj, (set, frozenset)):
        return list(obj)
    return str(obj)


def _hydrate_status_datetimes(raw_status: Any) -> Dict[str, Any]:
    """Normalize persisted status payloads so datetime fields are hydrated in-memory."""
    if not isinstance(raw_status, dict):
        return {}
    status = dict(raw_status)
    for key in STATUS_DATETIME_FIELDS:
        value = status.get(key)
        if isinstance(value, str):
            try:
                status[key] = datetime.fromisoformat(value.replace('Z', '+00:00'))
            except (ValueError, TypeError):
                logger.debug(f"Could not parse datetime for {key}")
                status[key] = None
    return status


def _update_progress(status, progress, message, step, save=True):
    """Update analysis status with progress, message, step tracking, and dynamic ETA.
    
    Automatically manages completed_steps list and computes ETA using a blended
    recent-rate / overall-rate approach for adaptive accuracy.
    Must be called while holding analysis_status_lock.
    """
    prev_step = status.get('current_step')
    completed = status.get('completed_steps', [])
    if prev_step and prev_step != step and prev_step not in completed:
        completed.append(prev_step)
    status['completed_steps'] = completed
    progress = max(0, min(100, int(progress)))
    status['progress'] = progress
    status['message'] = message
    status['current_step'] = step
    status['sub_step'] = message

    # Round 5 / Phase 6.4: previously this used ``datetime.now()`` (local
    # naive time) and parsed ``start_time`` with ``datetime.fromisoformat``
    # which preserves any embedded tz.  When ``start_time`` carried a
    # tz suffix (UTC) and ``now`` was naive, ``(now - t0)`` raised
    # TypeError("can't subtract offset-naive and offset-aware datetimes")
    # and the entire ETA branch was silently swallowed by the
    # ``except`` -- so the UI never showed an ETA after the first
    # tz-aware status was persisted.  Normalize BOTH sides to UTC.
    now = datetime.now(timezone.utc)
    start_time = status.get('start_time')
    if start_time and progress > 0:
        try:
            if isinstance(start_time, str):
                _raw = start_time.strip()
                if _raw.endswith('Z'):
                    _raw = _raw[:-1] + '+00:00'
                t0 = datetime.fromisoformat(_raw)
            else:
                t0 = start_time
            if t0.tzinfo is None:
                t0 = t0.replace(tzinfo=timezone.utc)
            else:
                t0 = t0.astimezone(timezone.utc)
            elapsed = (now - t0).total_seconds()

            history = status.get('_progress_history', [])
            history.append((now.timestamp(), progress))
            if len(history) > 6:
                history = history[-6:]
            status['_progress_history'] = history

            overall_rate = progress / max(elapsed, 0.1)

            recent_rate = None
            if len(history) >= 3:
                old_ts, old_pct = history[-3]
                dt = now.timestamp() - old_ts
                dp = progress - old_pct
                if dt > 0.5 and dp > 0:
                    recent_rate = dp / dt

            if recent_rate and recent_rate > 0:
                effective_rate = 0.7 * recent_rate + 0.3 * overall_rate
            else:
                effective_rate = overall_rate

            remaining = max(0, (100 - progress) / max(effective_rate, 0.001))
            remaining = min(remaining, 1800)
            status['eta_seconds'] = int(remaining)
            status['estimated_completion'] = (now + timedelta(seconds=remaining)).isoformat()
        except Exception as _eta_err:
            logger.debug(f"ETA calculation skipped: {_eta_err}")
    if save:
        save_analysis_status()


def save_analysis_status():
    """Save analysis status to file safely from any caller context."""
    try:
        with analysis_status_lock:
            if len(analysis_status) > 50:
                def _trim_sort_key(k):
                    st = analysis_status[k].get('start_time', '')
                    return st.isoformat() if isinstance(st, datetime) else str(st)
                sorted_ids = sorted(
                    analysis_status.keys(),
                    key=_trim_sort_key,
                    reverse=True
                )
                for old_id in sorted_ids[50:]:
                    if analysis_status[old_id].get('status') not in ('running', 'starting', 'cancelling'):
                        del analysis_status[old_id]
                with cancellation_flags_lock:
                    stale = [k for k in cancellation_flags if k not in analysis_status]
                    for k in stale:
                        del cancellation_flags[k]
            serializable_status = {}
            for analysis_id, status in analysis_status.items():
                serializable_status[analysis_id] = {}
                for key, value in status.items():
                    if key.startswith('_'):
                        continue
                    if isinstance(value, datetime):
                        serializable_status[analysis_id][key] = value.isoformat()
                    else:
                        serializable_status[analysis_id][key] = value
            status_file_path = str(_APP_SUPPORT / STATUS_FILE) if not os.path.isabs(STATUS_FILE) else STATUS_FILE
            serializable_status = _sanitize_for_json(serializable_status)
            temp_file_path = f"{status_file_path}.tmp"
            with open(temp_file_path, 'w', encoding='utf-8') as f:
                json.dump(serializable_status, f, indent=2, default=_json_default)
            os.replace(temp_file_path, status_file_path)
        logger.debug(f"Saved {len(serializable_status)} analysis statuses to {status_file_path}")
    except Exception as e:
        logger.error(f"Error saving analysis status: {e}", exc_info=True)

def load_analysis_status():
    """Load analysis status from file"""
    try:
        status_file_path = str(_APP_SUPPORT / STATUS_FILE) if not os.path.isabs(STATUS_FILE) else STATUS_FILE
        if os.path.exists(status_file_path):
            with open(status_file_path, 'r', encoding='utf-8') as f:
                loaded_status = json.load(f)
                
            cleaned_any = False
            with analysis_status_lock:
                for analysis_id, status in loaded_status.items():
                    analysis_status[analysis_id] = _hydrate_status_datetimes(status)

                # Clean up stuck analyses from previous runs
                for aid, s in analysis_status.items():
                    if s.get('status') in ('running', 'starting'):
                        s['status'] = 'cancelled'
                        s['message'] = 'Analysis interrupted by app restart'
                        s['error'] = 'Analysis was interrupted when the application restarted'
                        cleaned_any = True

                # Evict old entries to prevent unbounded growth (keep most recent 50)
                if len(analysis_status) > 50:
                    sorted_ids = sorted(
                        analysis_status.keys(),
                        key=lambda k: analysis_status[k].get('start_time', ''),
                        reverse=True
                    )
                    for old_id in sorted_ids[50:]:
                        del analysis_status[old_id]

            if cleaned_any:
                save_analysis_status()
            # Round 5 / Phase 6.19: ``len(analysis_status)`` is read
            # *outside* the lock above (in the legacy code) which
            # races with concurrent worker threads that may have
            # started inserting new statuses by the time this log
            # line fires (status file load happens at import / app
            # startup, but uvicorn / pytest hot-reload can re-enter
            # this path while workers exist).  Re-acquire the lock
            # for the snapshot count so the log message is consistent
            # with what was actually loaded.
            with analysis_status_lock:
                _loaded_count = len(analysis_status)
            logger.info(f"Loaded {_loaded_count} analysis statuses from file: {status_file_path}")
        else:
            logger.info(f"Status file not found at: {status_file_path} (this is normal for first run)")
    except Exception as e:
        logger.error(f"Error loading analysis status: {e}", exc_info=True)

# Load existing status on startup
load_analysis_status()

def validate_customer_name_input(customer_name: str) -> tuple[bool, str]:
    """Validate customer name input.

    Round 5 / Phase 2.4: previously this rejected single quotes
    (apostrophes) and double quotes outright as a coarse SQL/XSS guard,
    which broke legitimate business names like ``O'Brien & Co.`` and
    ``Macy's`` -- and the client-side validator had no equivalent rule,
    so the form would submit and only the server would error, leaving
    the user with a generic toast.

    All downstream call sites bind ``customer_name`` as a parameter
    (Snowflake / SQLite parameterized queries, pandas DataFrame
    filters), so a literal apostrophe is not a SQL injection vector by
    itself.  We instead block the *concatenation* patterns that signal
    SQL/JS injection (``;``, ``--``, ``/*``, ``*/``, ``<script>``,
    backticks, NUL bytes) and keep apostrophes and quotes available
    for legitimate names.  This also matches the client-side regex
    used in ``templates/analyze.html``.
    """
    if not customer_name:
        return True, "Valid"  # Customer name is optional

    if not isinstance(customer_name, str):
        return False, "Customer name must be text"

    if len(customer_name) > 200:
        return False, "Customer name too long"

    # Reject NUL bytes outright (control-char injection).
    if "\x00" in customer_name:
        return False, "Invalid characters in customer name"

    # Block concatenation / template-injection fragments while permitting
    # apostrophes and quotes inside the name.  Keep the list tight to
    # the patterns we actually want to block.
    dangerous_substrings = [";", "--", "/*", "*/", "<script", "</script", "`", "\x1b"]
    cn_lower = customer_name.lower()
    if any(frag.lower() in cn_lower for frag in dangerous_substrings):
        return False, "Invalid characters in customer name"

    return True, "Valid"

def validate_file_input(filename: str) -> tuple[bool, str]:
    """Validate file input"""
    if not filename:
        return True, "Valid"  # File is optional
    
    if not isinstance(filename, str):
        return False, "Filename must be text"
    
    # Check file extension
    allowed_extensions = ['.xlsx', '.xls']
    if not any(filename.lower().endswith(ext) for ext in allowed_extensions):
        return False, "Only Excel files (.xlsx, .xls) are allowed"
    
    return True, "Valid"

def validate_file_upload(file) -> tuple[bool, str]:
    """Enhanced file validation with security checks"""
    if not file or not file.filename:
        return False, "No file selected"
    
    filename = file.filename
    if not filename.endswith(('.xlsx', '.xls')):
        return False, "Invalid file extension. Only Excel files (.xlsx, .xls) are allowed."
    
    # File size validation
    file.seek(0, 2)  # Seek to end
    file_size = file.tell()
    file.seek(0)     # Reset to beginning
    
    max_size = int(app.config.get('MAX_CONTENT_LENGTH', 50 * 1024 * 1024))
    if file_size > max_size:
        return False, f"File too large. Maximum size is {max_size // (1024*1024)}MB."
    
    if file_size == 0:
        return False, "Empty file uploaded. Please select a valid Excel file."

    # Validate basic file signature to reduce spoofed-extension uploads.
    signature = file.read(8)
    file.seek(0)
    if filename.lower().endswith('.xlsx') and not signature.startswith(b'PK\x03\x04'):
        return False, "Invalid XLSX file signature."
    if filename.lower().endswith('.xls') and not signature.startswith(b'\xD0\xCF\x11\xE0'):
        return False, "Invalid XLS file signature."
    
    return True, "File is valid"


def _resolve_csone_path_safe(csone_file_path: str) -> Optional[str]:
    """
    Resolve CSOne file path safely, preventing path traversal.
    Returns validated path under uploads or OneDrive folder, or None if invalid.
    """
    if not csone_file_path or not isinstance(csone_file_path, str):
        return None
    csone_file_path = csone_file_path.strip()
    if not csone_file_path:
        return None
    uploads_dir = os.path.normpath(os.path.abspath(app.config['UPLOAD_FOLDER']))
    onedrive = app.config.get('CSONE_ONEDRIVE_FOLDER', '')
    onedrive_dir = os.path.normpath(os.path.abspath(onedrive)) if onedrive and os.path.isdir(onedrive) else ''

    def _is_under(base_dir: str, candidate_path: str) -> bool:
        """Return True when candidate_path is within base_dir (path-boundary safe)."""
        if not base_dir:
            return False
        try:
            return os.path.commonpath([base_dir, candidate_path]) == base_dir
        except Exception:
            return False
    # If path exists as full path, verify it's under allowed directories
    if os.path.exists(csone_file_path):
        resolved = os.path.normpath(os.path.abspath(csone_file_path))
        if _is_under(uploads_dir, resolved) or _is_under(onedrive_dir, resolved):
            return resolved
        return None
    # Try uploads + sanitized filename
    safe_name = secure_filename(os.path.basename(csone_file_path))
    if not safe_name or not safe_name.lower().endswith(('.xlsx', '.xls')):
        return None
    candidate = os.path.join(uploads_dir, safe_name)
    if os.path.exists(candidate):
        return os.path.abspath(candidate)
    return None


def get_latest_csone_from_folder() -> Optional[str]:
    """
    When no CSOne file is uploaded, use the most recent .xlsx from the shared folder.
    Macro places reports here daily. Returns full path or None if folder missing/empty.
    """
    folder = app.config.get('CSONE_ONEDRIVE_FOLDER')
    # Round 8 / Phase 1.8: previously these messages echoed the verbatim
    # OneDrive folder path (e.g. ``C:\Users\jdoe\OneDrive - Cisco\...``)
    # at INFO and the absolute path of the chosen file -- both leak the
    # operator's local username / sync layout to shipped logs.  Log
    # only the basename / a short folder digest at INFO; verbatim
    # paths remain available at DEBUG for support.
    if not folder:
        logger.info("[[ONEDRIVE]] CSOne folder not configured (CSONE_ONEDRIVE_FOLDER)")
        return None
    _folder_digest = _id_digest(folder)
    if not os.path.isdir(folder):
        logger.info("[[ONEDRIVE]] CSOne shared folder unavailable folder_digest=%s", _folder_digest)
        logger.debug("[[ONEDRIVE]] CSOne shared folder unavailable verbatim=%s", folder)
        return None
    try:
        xlsx_files = [
            os.path.join(folder, f) for f in os.listdir(folder)
            if f.lower().endswith(('.xlsx', '.xls')) and not f.startswith('~')
        ]
        if not xlsx_files:
            logger.info("[[ONEDRIVE]] No .xlsx files found in CSOne folder folder_digest=%s", _folder_digest)
            logger.debug("[[ONEDRIVE]] No .xlsx files in folder verbatim=%s", folder)
            return None
        # Sort by modification time, newest first
        latest = max(xlsx_files, key=lambda p: os.path.getmtime(p))
        logger.info(
            "[[ONEDRIVE]] Using latest CSOne report folder_digest=%s basename=%s",
            _folder_digest, os.path.basename(latest),
        )
        logger.debug("[[ONEDRIVE]] Verbatim latest CSOne report path=%s", latest)
        return latest
    except Exception as e:
        logger.warning("[[ONEDRIVE]] Could not read CSOne folder folder_digest=%s err_kind=%s", _folder_digest, type(e).__name__)
        logger.debug("[[ONEDRIVE]] CSOne folder read failure verbatim folder=%s", folder, exc_info=True)
        return None


@app.route('/')
def index():
    """Main analysis page using template"""
    import html as html_module
    
    error_message = request.args.get('error', '')
    # Escape HTML to prevent XSS
    if error_message:
        error_message = html_module.escape(error_message)
    else:
        error_message = ''
    
    form = AnalysisForm()
    # Set manager choices dynamically from team_config.json
    form.manager.choices = [(m, m) for m in MANAGERS]

    # Round 26 / Phase C: server-side seed for the AdoptIQ
    # Intelligence banner.  We render a usable summary even when JS
    # is disabled so users see real state (idle/running/last run)
    # immediately on first paint -- the banner JS then takes over
    # and keeps it live via /api/intel/status.  Failures here must
    # never break the analysis page; fall back to ``None`` so the
    # template's "{% if not intel_status %}" branch wins.
    intel_status_ctx: Optional[Dict[str, Any]] = None
    try:
        intel_status_ctx = _r17_corpus_status_payload()
    except Exception as _intel_err:  # noqa: BLE001 - never break / on render
        logger.debug(
            "Round 26 / Phase C: intel_status seed failed: %s",
            type(_intel_err).__name__,
        )
        intel_status_ctx = None

    # Round 26 / Phase D: feature flag for the user-facing upload
    # control.  Default OFF so the endpoint and the drop-zone are
    # not exposed unless the operator opts in via env var.
    #
    # Round 26 - review (R26-002): route through ``Config.*`` so the
    # template flag and the ``api_intel_upload`` gate (which already
    # reads ``Config.ADOPTIQ_INTEL_UPLOAD_ENABLED``) cannot drift.
    # Previously this read ``os.environ`` directly, which:
    #   - silently bypassed the same casefolding rules
    #     ``Config`` uses on import (e.g. ``yes``/``on`` truthy);
    #   - tests that ``monkeypatch.setattr(Config, ...)`` -- the
    #     pattern used by every ``test_round26_intel_upload_*`` --
    #     could not flip this side of the flag, leaving the
    #     drop-zone hidden in tests that needed it visible.
    intel_upload_enabled = bool(
        getattr(Config, 'ADOPTIQ_INTEL_UPLOAD_ENABLED', False)
    )

    return render_template(
        'analyze.html',
        form=form,
        error_message=error_message,
        intel_status=intel_status_ctx,
        intel_upload_enabled=intel_upload_enabled,
    )

@app.route('/start_analysis', methods=['POST'])
def start_analysis():
    """Start a new analysis with enhanced security validation"""
    try:
        # For AJAX requests, validate CSRF token from header/body.
        is_ajax = request.headers.get('X-Requested-With') == 'XMLHttpRequest'
        
        if is_ajax:
            # Check if JSON data is provided (for renewal reports) or use form data
            json_data = request.get_json(silent=True) or {}
            csrf_token = (
                request.headers.get('X-CSRFToken')
                or request.headers.get('X-CSRF-Token')
                or json_data.get('csrf_token')
                or request.form.get('csrf_token')
            )
            if app.config.get('WTF_CSRF_ENABLED', True):
                try:
                    validate_csrf(csrf_token)
                except Exception:
                    return jsonify({'ok': False, 'success': False, 'error': 'CSRF validation failed'}), 400  # Round 13 / Phase 4.3
            if json_data:
                # JSON data (typically for renewal reports)
                manager = json_data.get('manager', '').strip() if json_data.get('manager') else ''
                tech = json_data.get('technology', '').strip() if json_data.get('technology') else ''
                renewal_type = json_data.get('renewal_type', '').strip() if json_data.get('renewal_type') else ''
                # If renewal_type is provided but report_type is not, infer report_type from renewal_type
                if renewal_type:
                    if renewal_type == 'renewal_portfolio':
                        report_type = 'renewal_portfolio'
                    elif renewal_type in ['renewal', 'renewal_single']:
                        report_type = 'renewal'
                    else:
                        report_type = json_data.get('report_type', 'comprehensive').strip() if json_data.get('report_type') else 'comprehensive'
                else:
                    report_type = json_data.get('report_type', 'comprehensive').strip() if json_data.get('report_type') else 'comprehensive'
                customer_name = json_data.get('customer_name', '').strip() if json_data.get('customer_name') else ''
                days_str = str(json_data.get('days', 90)).strip()
                subscription_id = json_data.get('subscription_id', '').strip() if json_data.get('subscription_id') else ''
            else:
                # Form data (for other report types)
                manager = request.form.get('manager', '').strip()
                tech = request.form.get('technology', '').strip()
                report_type = request.form.get('report_type', 'comprehensive').strip()
                renewal_type = request.form.get('renewal_type', '').strip()
                customer_name = request.form.get('customer_name', '').strip()
                days_str = request.form.get('days', '90').strip()
                subscription_id = request.form.get('subscription_id', '').strip()
            
            # For renewal reports, use renewal_type if provided, otherwise infer from report_type
            if report_type in ['renewal', 'renewal_portfolio']:
                if not renewal_type:
                    renewal_type = 'renewal_single' if report_type == 'renewal' else 'renewal_portfolio'
            
            # Validate inputs - Manager is optional for single customer renewal (renewal_type can be 'renewal' or 'renewal_single' from form)
            is_single_customer = report_type == 'renewal' and renewal_type in ('renewal_single', 'renewal')
            if is_single_customer:
                # Single customer renewal: manager is optional if customer_name or subscription_id is provided
                if manager and manager not in MANAGERS:
                    return jsonify({
                        'success': False,
                        'error': f'Invalid manager. Must be one of: {", ".join(MANAGERS)}'
                    }), 400
                # For single customer renewal, require either customer_name, subscription_id, OR manager
                if not customer_name and not subscription_id and not manager:
                    return jsonify({
                        'success': False,
                        'error': 'Either Customer Name, Subscription ID, or Manager is required for single customer renewal'
                    }), 400
                if customer_name:
                    is_valid, err_msg = validate_customer_name_input(customer_name)
                    if not is_valid:
                        return jsonify({'success': False, 'error': err_msg}), 400
            elif report_type == 'renewal_portfolio':
                # Portfolio renewal: manager is required
                if not manager or manager not in MANAGERS:
                    return jsonify({
                        'success': False,
                        'error': f'Manager is required for portfolio renewal. Must be one of: {", ".join(MANAGERS)}'
                    }), 400
            else:
                # Comprehensive and compact: manager optional when customer/subscription specified (single-customer report)
                if report_type in ['comprehensive', 'compact'] and (customer_name or subscription_id):
                    if manager and manager not in MANAGERS:
                        return jsonify({'success': False, 'error': f'Invalid manager. Must be one of: {", ".join(MANAGERS)}'}), 400
                else:
                    if not manager or manager not in MANAGERS:
                        return jsonify({
                            'success': False,
                            'error': f'Invalid manager. Must be one of: {", ".join(MANAGERS)}'
                        }), 400
            
            if not tech:
                return jsonify({
                    'success': False,
                    'error': 'Technology is required'
                }), 400
            
            if report_type not in ['comprehensive', 'compact', 'renewal', 'renewal_portfolio']:
                return jsonify({
                    'success': False,
                    'error': 'Invalid report type'
                }), 400
            
            try:
                days = int(days_str)
                if days < 1 or days > 365:
                    return jsonify({
                        'success': False,
                        'error': 'Days must be between 1 and 365'
                    }), 400
            except ValueError:
                return jsonify({
                    'success': False,
                    'error': 'Days must be a valid number'
                }), 400
        else:
            # Regular form submission - use WTForms validation
            form = AnalysisForm()
            # Set manager choices dynamically (they might not be set if form was created before)
            form.manager.choices = [(m, m) for m in MANAGERS]
            if not form.validate():
                # Return validation errors as JSON with detailed info
                error_messages = []
                for field, errors in form.errors.items():
                    for error in errors:
                        error_messages.append(f"{field}: {error}")
                return jsonify({
                    'success': False,
                    'error': ' | '.join(error_messages)
                }), 400
            # Get form data
            manager = form.manager.data
            tech = form.technology.data
            report_type = form.report_type.data
            renewal_type = request.form.get('renewal_type', '').strip()
            customer_name = form.customer_name.data
            days = form.days.data
            subscription_id = request.form.get('subscription_id', '')
            # For renewal reports, use renewal_type if provided, otherwise infer from report_type
            if report_type in ['renewal', 'renewal_portfolio']:
                if not renewal_type:
                    renewal_type = 'renewal_single' if report_type == 'renewal' else 'renewal_portfolio'
        
        # File handling (same for both AJAX and regular)
        csone_file = None
        if 'csone_file' in request.files:
            file = request.files['csone_file']
            if file and file.filename:
                is_valid, error_msg = validate_file_upload(file)
                if not is_valid:
                    return jsonify({
                        'success': False,
                        'error': error_msg
                    }), 400
                import uuid as _uuid
                raw_name = secure_filename(file.filename)
                filename = _r13_unique_upload_filename(_uuid, raw_name, file)
                filepath = os.path.join(app.config['UPLOAD_FOLDER'], filename)
                file.save(filepath)
                csone_file = filepath
        # When no file uploaded: use most recent from OneDrive folder (macro places reports daily)
        if not csone_file:
            csone_file = get_latest_csone_from_folder()
        
        # Generate unique analysis ID - handle case where manager might be empty for single customer renewal
        timestamp = int(time.time())
        safe_manager = _sanitize_analysis_id_part(manager)
        safe_tech = _sanitize_analysis_id_part(tech)
        safe_customer = _sanitize_analysis_id_part(customer_name)
        safe_subscription = _sanitize_analysis_id_part(subscription_id)
        if report_type in ['renewal', 'renewal_portfolio']:
            # For renewal reports, use renewal-specific ID format
            if renewal_type == 'renewal_portfolio':
                # Portfolio renewal: use manager
                if safe_manager:
                    analysis_id = f"Renewal_Portfolio_{safe_manager}_{safe_tech}_{days}d_{timestamp}"
                else:
                    analysis_id = f"Renewal_Portfolio_{safe_tech}_{days}d_{timestamp}"
            else:
                # Single customer renewal: use customer name or subscription ID, or manager
                if safe_customer:
                    analysis_id = f"Renewal_{safe_customer}_{safe_tech}_{days}d_{timestamp}"
                elif safe_subscription:
                    analysis_id = f"Renewal_Sub_{safe_subscription}_{safe_tech}_{days}d_{timestamp}"
                elif safe_manager:
                    analysis_id = f"Renewal_{safe_manager}_{safe_tech}_{days}d_{timestamp}"
                else:
                    analysis_id = f"Renewal_{safe_tech}_{days}d_{timestamp}"
        else:
            # Other report types: use manager
            if safe_manager:
                analysis_id = f"{safe_manager}_{safe_tech}_{days}d_{timestamp}"
            else:
                safe_report_type = _sanitize_analysis_id_part(report_type)
                analysis_id = f"{safe_report_type}_{safe_tech}_{days}d_{timestamp}"
        
        # Initialize status with enhanced messaging and timing (thread-safe)
        with analysis_status_lock:
            analysis_status[analysis_id] = {
                'status': 'starting',
                'progress': 0,
                'message': 'Initializing AdoptIQ Ultra Intelligence System...',
                'start_time': _now_utc_iso_z(),
                'current_step': 'System Initialization',
                'completed_steps': [],
                'sub_step': '',
                'total_steps': 12,
                'step_start_time': _now_utc_iso_z(),
                'estimated_completion': None,
                'manager': manager,
                'tech': tech,
                'technology': tech,
                'days': days,
                'report_type': report_type,
                'renewal_type': renewal_type if report_type in ['renewal', 'renewal_portfolio'] else None,
                'customer_name': customer_name,
                'subscription_id': subscription_id,
                'csone_file': csone_file,
                'csone_import_status': 'checking',
                'csone_import_message': 'Checking CSOne data availability...',
                'results': None,
                'error': None
            }
            # Save status immediately to persist across Flask reloads
            save_analysis_status()
        
        # Start appropriate analysis based on report type
        if report_type == 'compact':
            thread = threading.Thread(target=run_compact_analysis, args=(analysis_id,))
        elif report_type in ['renewal', 'renewal_portfolio']:
            thread = threading.Thread(target=run_customer_renewal_analysis, args=(analysis_id,))
        else:  # comprehensive
            thread = threading.Thread(target=run_comprehensive_analysis, args=(analysis_id,))
        
        thread.daemon = True
        thread.start()
        
        # Round 8 / Phase 1.4: previously this logged
        # ``list(analysis_status.keys())`` *outside* ``analysis_status_lock``
        # while worker threads concurrently mutate the dict, which can raise
        # ``RuntimeError: dictionary changed size during iteration`` and at
        # best produces a nonsensical snapshot.  Snapshot under the lock.
        # Round 8 / Phase 1.7: do not log the raw ``analysis_id`` (it
        # embeds customer/manager/technology fragments) or the verbatim
        # status keys at INFO -- digest at INFO, verbatim at DEBUG, and
        # only a count of in-flight analyses at INFO.
        with analysis_status_lock:
            _status_count = len(analysis_status)
            _status_keys_snapshot = list(analysis_status.keys())
        logger.info("[[START]] Started analysis aid_digest=%s in_flight=%d", _id_digest(analysis_id), _status_count)
        logger.debug("[[DEBUG]] Analysis status keys in memory: %s", _status_keys_snapshot)
        
        # Always return JSON - the frontend handles the redirect
        return jsonify({
            'success': True,
            'analysis_id': analysis_id,
            'redirect_url': url_for('progress', analysis_id=analysis_id)
        })
        
    except Exception as e:
        logger.error(f"Error in start_analysis: {e}", exc_info=True)
        return jsonify({
            'success': False,
            'error': 'An internal error occurred while starting the analysis'
        }), 500

def check_cancellation(analysis_id):
    """Check if analysis should be cancelled (thread-safe)"""
    with cancellation_flags_lock:
        return cancellation_flags.get(analysis_id, False)

def update_analysis_status(analysis_id: str, updates: Dict[str, Any], save: bool = True):
    """
    Thread-safe helper to update analysis status
    
    Args:
        analysis_id: The analysis ID to update
        updates: Dictionary of status fields to update
        save: Whether to save status to file after update
    """
    with analysis_status_lock:
        if analysis_id in analysis_status:
            analysis_status[analysis_id].update(updates)
            # Round 13 / Phase 11.4: opportunistic TTL sweep on
            # mutation.  Self-throttles internally so we only pay
            # the sweep cost once per
            # ``_ANALYSIS_STATUS_SWEEP_INTERVAL_SECONDS`` regardless
            # of how busy the worker is.
            try:
                _r13_evict_stale_analysis_status()
            except Exception:
                pass
            if save:
                save_analysis_status()
        else:
            logger.warning(f"Attempted to update status for non-existent analysis_id: {analysis_id}")

def filter_subscriptions_by_criteria(team_subs_df: pd.DataFrame, customer_name: TypingOptional[str] = None, 
                                     subscription_id: TypingOptional[str] = None) -> tuple[pd.DataFrame, TypingOptional[str]]:
    """
    Filter subscriptions by customer name or subscription ID
    
    Args:
        team_subs_df: DataFrame containing team subscriptions
        customer_name: Optional customer name to filter by (case-insensitive partial match)
        subscription_id: Optional subscription ID to filter by (exact match)
    
    Returns:
        Tuple of (filtered_dataframe, error_message)
        error_message is None if successful, otherwise contains error description
    """
    if team_subs_df.empty:
        return team_subs_df, "No subscriptions available to filter"
    
    original_count = len(team_subs_df)
    filtered_df = team_subs_df.copy()
    
    if customer_name and customer_name.strip():
        # Filter by customer name (case-insensitive partial match)
        customer_name_filter = customer_name.strip()
        filtered_df = filtered_df[filtered_df['BU_NAME'].astype(str).str.contains(customer_name_filter, case=False, na=False)]
        # Round 13 / Phase 10.6: previously this logged the raw
        # ``customer_name_filter`` at INFO level, which writes a
        # PII customer name into the structured log stream that
        # ships off-host (audit mirror, syslog).  PII customer
        # names should not appear in logs above DEBUG -- they're
        # already accessible via the analysis envelope where they
        # belong.  Log a redacted token (length only) at INFO and
        # keep the full name at DEBUG for triage.
        _r13_redacted_cust = f"<redacted len={len(customer_name_filter)}>"
        logger.info(
            "[[FILTER]] Filtering to customer: %s - %s/%s subscriptions found",
            _r13_redacted_cust, len(filtered_df), original_count,
        )
        logger.debug(
            "[[FILTER]] (debug) customer name filter: %r", customer_name_filter
        )
        
        if filtered_df.empty:
            return filtered_df, f"No subscriptions found for customer '{customer_name_filter}'"
            
    elif subscription_id and subscription_id.strip():
        # Filter by subscription ID (exact match)
        subscription_id_filter = subscription_id.strip()
        
        # Validate subscription ID format
        if not re.match(r'^[a-zA-Z0-9\-_]+$', subscription_id_filter):
            return pd.DataFrame(), f"Invalid subscription ID format: '{subscription_id_filter}'"
        
        filtered_df = filtered_df[filtered_df['SUBSCRIPTION_ID'] == subscription_id_filter]
        # Round 13 / Phase 10.6: subscription IDs are not PII per se
        # but they are tenant identifiers; surface only a hash-like
        # truncated tail at INFO so the log shows the existence and
        # correlation key without exposing the full ID broadly.
        _r13_sub_tail = (
            subscription_id_filter[-6:]
            if len(subscription_id_filter) >= 6 else 'short'
        )
        logger.info(
            "[[FILTER]] Filtering to subscription: <id ...%s> - %s/%s subscriptions found",
            _r13_sub_tail, len(filtered_df), original_count,
        )
        logger.debug(
            "[[FILTER]] (debug) subscription id filter: %r", subscription_id_filter
        )
        
        if filtered_df.empty:
            return filtered_df, f"No subscriptions found with ID '{subscription_id_filter}'"
    
    return filtered_df, None

def extract_software_defects(csone_df: pd.DataFrame, ab_df: pd.DataFrame = None) -> Dict[str, Any]:
    """
    Extract software defects (BST/CSC IDs) and BEMS escalation IDs from CSOne
    and Adoption Barriers data.
    Checks Transaction ID, bemscsc_refs, Title, and Problem Description.
    
    Args:
        csone_df: DataFrame containing CSOne/TAC case data
        ab_df: Optional DataFrame containing Adoption Barriers data
        
    Returns:
        Dictionary with defect counts, lists, and customer breakdown
    """
    _BEMS_RE = re.compile(r'\bBEMS[- ]?\d+\b', re.IGNORECASE)
    _CSC_RE = re.compile(r'\bCSC[a-zA-Z0-9]{6,10}\b', re.IGNORECASE)

    defects = {
        'csc_ids': set(),
        'bems_ids': set(),
        'bst_defects': [],
        'defect_cases': [],
        'defect_by_customer': {},
        'total_defects': 0,
        'total_cases_with_defects': 0,
        'customers_with_defects': set()
    }
    
    # Extract from CSOne data
    if csone_df is not None and not csone_df.empty:
        for _, row in csone_df.iterrows():
            csc_refs = []
            # Use flexible customer column lookup
            customer = 'Unknown'
            for col in ['Customer Name', 'customer_name', 'BU_NAME', 'Customer']:
                if col in row.index and pd.notna(row.get(col, None)):
                    customer = normalize_customer_name(row[col])
                    break
            
            # Check Transaction ID for CSC/BST references (BEMS handled by canonical helper below)
            if 'Transaction ID' in csone_df.columns and pd.notna(row.get('Transaction ID', None)):
                tx_id = str(row['Transaction ID'])
                csc_refs.extend(_CSC_RE.findall(tx_id))
            
            # Check bemscsc_refs column for CSC references
            if 'bemscsc_refs' in csone_df.columns and pd.notna(row.get('bemscsc_refs', None)):
                refs_str = str(row['bemscsc_refs'])
                csc_refs.extend(_CSC_RE.findall(refs_str))
            
            # Check Title and Problem Description for CSC
            title = str(row.get('Title', '')) if 'Title' in row.index else ''
            description = str(row.get('Problem Description', '')) if 'Problem Description' in row.index else ''
            combined_text = f"{title} {description}"
            csc_refs.extend(_CSC_RE.findall(combined_text))
            # Round 6 / Phase 5.10: route BEMS extraction through the
            # canonical ``extract_bems_ids_from_row`` helper instead of
            # the local ``_BEMS_RE`` so case insensitivity, suffix /
            # punctuation handling, and the deduplication semantics
            # match every other path that consumes BEMS references
            # (compact / EI / leader / canonical_metrics).  Without
            # this, the comprehensive software-defects payload could
            # over- or under-count BEMS for the same row, depending
            # on whether the canonical helper had additional
            # normalization that the local regex missed.
            bems_refs = list(extract_bems_ids_from_row(row))
            
            all_refs = [(rid, 'CSC') for rid in csc_refs] + [(rid, 'BEMS') for rid in bems_refs]
            
            for defect_id, ref_type in all_refs:
                defect_id_norm = re.sub(r'[- ]', '', defect_id).upper()
                if ref_type == 'CSC':
                    defects['csc_ids'].add(defect_id_norm)
                else:
                    defects['bems_ids'].add(defect_id_norm)
                defects['customers_with_defects'].add(customer)
                
                case_num = row.get('SR Number', 'N/A') if 'SR Number' in row.index else (
                    row.get('Case Number', 'N/A') if 'Case Number' in row.index else 'N/A'
                )
                tx_id_str = str(row.get('Transaction ID', '')) if 'Transaction ID' in row.index else ''
                
                defects['defect_cases'].append({
                    'defect_id': defect_id_norm,
                    'customer': customer,
                    'case_number': case_num,
                    'title': title if title else 'N/A',
                    'source': 'CSOne',
                    'transaction_id': tx_id_str,
                    'ref_type': ref_type
                })
                
                if customer not in defects['defect_by_customer']:
                    defects['defect_by_customer'][customer] = []
                defects['defect_by_customer'][customer].append(defect_id_norm)
    
    # Extract from Adoption Barriers data
    if ab_df is not None and not ab_df.empty:
        for _, row in ab_df.iterrows():
            csc_refs = []
            # Use flexible customer column lookup
            customer = 'Unknown'
            for col in ['customer_name', 'Customer Name', 'BU_NAME', 'Customer']:
                if col in row.index and pd.notna(row.get(col, None)):
                    customer = normalize_customer_name(row[col])
                    break
            
            # Check bemscsc_refs column for CSC IDs
            if 'bemscsc_refs' in ab_df.columns and pd.notna(row.get('bemscsc_refs', None)):
                refs_str = str(row['bemscsc_refs'])
                csc_refs.extend(_CSC_RE.findall(refs_str))
            
            # Check title and description for CSC IDs
            title = row.get('title', '') if 'title' in row.index else (
                row.get('SUBJECT_C', '') if 'SUBJECT_C' in row.index else ''
            )
            description = row.get('description', '') if 'description' in row.index else (
                row.get('DESCRIPTION__C', '') if 'DESCRIPTION__C' in row.index else ''
            )
            combined_text = f"{title} {description}"
            csc_refs.extend(_CSC_RE.findall(combined_text))
            # Round 6 / Phase 5.10: BEMS via canonical helper (see
            # CSOne branch above for rationale).
            bems_refs = list(extract_bems_ids_from_row(row))
            
            all_refs = [(rid, 'CSC') for rid in csc_refs] + [(rid, 'BEMS') for rid in bems_refs]
            
            for defect_id, ref_type in all_refs:
                defect_id_norm = re.sub(r'[- ]', '', defect_id).upper()
                if ref_type == 'CSC':
                    defects['csc_ids'].add(defect_id_norm)
                else:
                    defects['bems_ids'].add(defect_id_norm)
                defects['customers_with_defects'].add(customer)
                
                ab_id = row.get('ID', 'N/A') if 'ID' in row.index else 'N/A'
                
                defects['defect_cases'].append({
                    'defect_id': defect_id_norm,
                    'customer': customer,
                    'case_number': f"AB-{ab_id}",
                    'title': str(title) if title else 'N/A',
                    'source': 'AdoptionBarrier',
                    'ref_type': ref_type
                })
                
                if customer not in defects['defect_by_customer']:
                    defects['defect_by_customer'][customer] = []
                defects['defect_by_customer'][customer].append(defect_id_norm)
    
    # Normalize customer keys and guarantee linkage for every extracted ID.
    normalized_linkage: Dict[str, set[str]] = {}
    for customer_name, defect_ids in defects['defect_by_customer'].items():
        customer_key = normalize_customer_name(customer_name)
        bucket = normalized_linkage.setdefault(customer_key, set())
        for defect_id in defect_ids or []:
            token = str(defect_id or "").strip().upper()
            if token:
                bucket.add(token)

    # Calculate totals (CSC + BEMS combined)
    all_ids = defects['csc_ids'] | defects['bems_ids']
    linked_ids = set()
    for values in normalized_linkage.values():
        linked_ids.update(values)
    unlinked_ids = all_ids - linked_ids
    if unlinked_ids:
        unknown_bucket = normalized_linkage.setdefault("Unknown", set())
        unknown_bucket.update(unlinked_ids)

    defects['defect_by_customer'] = {
        customer: sorted(ids)
        for customer, ids in normalized_linkage.items()
    }
    defects['total_defects'] = len(all_ids)
    defects['bst_defects'] = sorted(list(all_ids))
    defects['total_cases_with_defects'] = len(defects['defect_cases'])
    defects['customers_with_defects'] = sorted(list(defects['customers_with_defects']))
    
    logger.info(f"[[DEFECTS]] Found {len(defects['csc_ids'])} CSC IDs and {len(defects['bems_ids'])} BEMS IDs across {defects['total_cases_with_defects']} cases")
    if defects['total_defects'] > 0:
        logger.info(f"[[DEFECTS]] Sample defects: {defects['bst_defects'][:5]}")
    
    return defects

def extract_psirt_vulnerabilities(csone_df: pd.DataFrame, ab_df: pd.DataFrame = None) -> Dict[str, Any]:
    """
    Extract PSIRT vulnerability references (CVE IDs, PSIRT advisory IDs) from data
    
    Args:
        csone_df: DataFrame containing CSOne/TAC case data
        ab_df: Optional DataFrame containing Adoption Barriers data
        
    Returns:
        Dictionary with PSIRT vulnerability counts and lists
    """
    vulnerabilities = {
        'cve_ids': set(),
        'psirt_advisories': set(),
        'vulnerability_cases': [],
        'vulnerability_by_customer': {},
        'total_vulnerabilities': 0,
        'total_cases_with_vulns': 0,
        'customers_with_vulns': set()
    }
    
    # PSIRT patterns
    cve_pattern = r'\bCVE-\d{4}-\d{4,7}\b'
    psirt_pattern = r'\bcisco-sa-\d{8}-[a-z0-9-]+\b'
    
    # Extract from CSOne data
    if csone_df is not None and not csone_df.empty:
        for _, row in csone_df.iterrows():
            vuln_refs = []
            # Use flexible customer column lookup
            customer = 'Unknown'
            for col in ['Customer Name', 'customer_name', 'BU_NAME', 'Customer']:
                if col in row.index and pd.notna(row.get(col, None)):
                    customer = normalize_customer_name(row[col])
                    break
            
            # Check all text fields - use proper column checking
            text_fields = []
            if 'Transaction ID' in csone_df.columns:
                text_fields.append(str(row.get('Transaction ID', '')))
            if 'bemscsc_refs' in csone_df.columns:
                text_fields.append(str(row.get('bemscsc_refs', '')))
            if 'Title' in csone_df.columns:
                text_fields.append(str(row.get('Title', '')))
            if 'Problem Description' in csone_df.columns:
                text_fields.append(str(row.get('Problem Description', '')))
            
            combined_text = ' '.join(text_fields)
            
            # Extract CVE IDs
            cve_matches = re.findall(cve_pattern, combined_text, re.IGNORECASE)
            vuln_refs.extend([cve.upper() for cve in cve_matches])
            
            # Extract PSIRT advisory IDs
            psirt_matches = re.findall(psirt_pattern, combined_text, re.IGNORECASE)
            vuln_refs.extend([psirt.lower() for psirt in psirt_matches])
            
            # Add unique vulnerabilities
            for vuln_id in vuln_refs:
                if vuln_id.startswith('CVE-'):
                    vulnerabilities['cve_ids'].add(vuln_id)
                elif 'cisco-sa-' in vuln_id.lower():
                    vulnerabilities['psirt_advisories'].add(vuln_id)
                
                vulnerabilities['customers_with_vulns'].add(customer)
                
                case_num = row.get('SR Number', 'N/A') if 'SR Number' in row.index else (
                    row.get('Case Number', 'N/A') if 'Case Number' in row.index else 'N/A'
                )
                title = str(row.get('Title', '')) if 'Title' in row.index else ''  # FIXED: No truncation
                
                vulnerabilities['vulnerability_cases'].append({
                    'vulnerability_id': vuln_id,
                    'customer': customer,
                    'case_number': case_num,
                    'title': title,
                    'source': 'CSOne'
                })
                
                if customer not in vulnerabilities['vulnerability_by_customer']:
                    vulnerabilities['vulnerability_by_customer'][customer] = []
                vulnerabilities['vulnerability_by_customer'][customer].append(vuln_id)
    
    # Extract from Adoption Barriers data
    if ab_df is not None and not ab_df.empty:
        for _, row in ab_df.iterrows():
            # Use flexible customer column lookup
            customer = 'Unknown'
            for col in ['customer_name', 'Customer Name', 'BU_NAME', 'Customer']:
                if col in row.index and pd.notna(row.get(col, None)):
                    customer = normalize_customer_name(row[col])
                    break
            
            # Check all text fields - use proper column checking
            text_fields = []
            if 'bemscsc_refs' in ab_df.columns:
                text_fields.append(str(row.get('bemscsc_refs', '')))
            if 'title' in ab_df.columns:
                text_fields.append(str(row.get('title', '')))
            elif 'SUBJECT_C' in ab_df.columns:
                text_fields.append(str(row.get('SUBJECT_C', '')))
            if 'description' in ab_df.columns:
                text_fields.append(str(row.get('description', '')))
            elif 'DESCRIPTION__C' in ab_df.columns:
                text_fields.append(str(row.get('DESCRIPTION__C', '')))
            
            combined_text = ' '.join(text_fields)
            
            cve_matches = re.findall(cve_pattern, combined_text, re.IGNORECASE)
            psirt_matches = re.findall(psirt_pattern, combined_text, re.IGNORECASE)
            
            for cve in cve_matches:
                vulnerabilities['cve_ids'].add(cve.upper())
                vulnerabilities['customers_with_vulns'].add(customer)
                if customer not in vulnerabilities['vulnerability_by_customer']:
                    vulnerabilities['vulnerability_by_customer'][customer] = []
                vulnerabilities['vulnerability_by_customer'][customer].append(cve.upper())
            
            for psirt in psirt_matches:
                vulnerabilities['psirt_advisories'].add(psirt.lower())
                vulnerabilities['customers_with_vulns'].add(customer)
                if customer not in vulnerabilities['vulnerability_by_customer']:
                    vulnerabilities['vulnerability_by_customer'][customer] = []
                vulnerabilities['vulnerability_by_customer'][customer].append(psirt.lower())
    
    # Round 2 / Phase 5.3: a single security issue is often referenced
    # both by its CVE id (e.g. ``CVE-2024-12345``) and by a Cisco
    # PSIRT advisory id (e.g. ``cisco-sa-...``).  Summing the two id
    # spaces double-counts those issues.  Expose the two id-space
    # counts separately AND a deduped "distinct issues" count so
    # downstream renderers can pick the metric that matches their
    # narrative.
    cve_count = len(vulnerabilities['cve_ids'])
    psirt_count = len(vulnerabilities['psirt_advisories'])
    distinct_issue_keys: set = set()
    try:
        for _customer, _ids in (vulnerabilities.get('vulnerability_by_customer') or {}).items():
            for _vid in _ids or []:
                if not _vid:
                    continue
                distinct_issue_keys.add(str(_vid).strip().lower())
    except Exception:
        distinct_issue_keys = set()
    vulnerabilities['cve_count'] = cve_count
    vulnerabilities['psirt_count'] = psirt_count
    vulnerabilities['distinct_issues_count'] = len(distinct_issue_keys)
    vulnerabilities['total_vulnerability_identifiers'] = cve_count + psirt_count
    # Preserve the legacy key for backward compatibility but point it
    # at the deduped count so existing call sites stop double-counting.
    vulnerabilities['total_vulnerabilities'] = vulnerabilities['distinct_issues_count']
    vulnerabilities['total_cases_with_vulns'] = len(vulnerabilities['vulnerability_cases'])
    vulnerabilities['customers_with_vulns'] = sorted(list(vulnerabilities['customers_with_vulns']))

    logger.info(
        "[[PSIRT]] CVE count=%d, PSIRT count=%d, identifiers sum=%d, distinct issues=%d",
        cve_count,
        psirt_count,
        vulnerabilities['total_vulnerability_identifiers'],
        vulnerabilities['distinct_issues_count'],
    )

    return vulnerabilities

def detect_bems_escalations(csone_df: pd.DataFrame) -> Tuple[pd.DataFrame, int]:
    """
    Comprehensive BEMS detection from CSOne data
    Checks Transaction ID (PRIMARY), bemscsc_refs (SECONDARY), and other columns
    
    Args:
        csone_df: DataFrame containing CSOne/TAC case data
        
    Returns:
        Tuple of (bems_cases_dataframe, bems_count)
    """
    if csone_df is None or csone_df.empty:
        return pd.DataFrame(), 0

    normalized_csone = add_case_lifecycle_fields(csone_df)
    bems_mask = detect_bems_mask(normalized_csone)
    bems_cases = normalized_csone[bems_mask].copy() if bems_mask.any() else pd.DataFrame()
    bems_count = len(bems_cases)
    
    if bems_count > 0:
        logger.info(f"[[BEMS]] Found {bems_count} BEMS escalations")
        if 'Transaction ID' in bems_cases.columns:
            sample_bems = bems_cases['Transaction ID'].dropna().head(3).tolist()
            logger.info(f"[[BEMS]] Sample BEMS Transaction IDs: {sample_bems}")
        if 'case_type_class' in bems_cases.columns:
            case_mix = bems_cases['case_type_class'].value_counts(dropna=False).to_dict()
            logger.info(f"[[BEMS]] BEMS case type mix: {case_mix}")
        elif 'bemscsc_refs' in bems_cases.columns:
            sample_bems = bems_cases['bemscsc_refs'].dropna().head(3).tolist()
            logger.info(f"[[BEMS]] Sample BEMS references: {sample_bems}")
    else:
        logger.warning(f"[[BEMS]] No BEMS escalations found in CSOne data")
        if 'Transaction ID' in csone_df.columns:
            logger.info(f"[[BEMS]] Transaction ID column exists - checking sample values...")
            sample_tx_ids = csone_df['Transaction ID'].dropna().head(5).tolist()
            logger.info(f"[[BEMS]] Sample Transaction IDs: {sample_tx_ids}")
    
    return bems_cases, bems_count

def _clean_datetime_columns_for_excel(df):
    """Normalize datetime columns to wall-clock UTC for Excel compatibility.

    Round 5 / Phase 1.16: Excel cells cannot carry tz-aware datetimes, so
    we used to strip the tz with ``tz_convert(None)`` -- but that drops
    the offset *without* converting, which silently shifts the wall-clock
    value (e.g. a 2025-01-01T00:00:00+00:00 row in a frame stored as
    ``-05:00`` would become 2025-01-01T05:00:00 in the workbook).  Convert
    to UTC first, then drop the tz, so the value Excel sees is the
    canonical UTC wall-clock that matches the rest of the report.
    """
    if df is None or df.empty:
        return df if df is not None else pd.DataFrame()
    
    try:
        df_clean = df.copy()
        for col in df_clean.columns:
            if pd.api.types.is_datetime64_any_dtype(df_clean[col]):
                try:
                    if hasattr(df_clean[col].dtype, 'tz') and df_clean[col].dtype.tz is not None:
                        # Convert to UTC, then drop tz so Excel writes the
                        # UTC wall-clock instead of the original offset's
                        # wall-clock.
                        df_clean[col] = df_clean[col].dt.tz_convert('UTC').dt.tz_localize(None)
                except Exception as col_error:
                    logger.warning(f"Could not clean datetime column {col}: {col_error}")
                    # If we can't clean the column, convert to string
                    df_clean[col] = df_clean[col].astype(str)
        return df_clean
    except Exception as e:
        logger.error(f"Error cleaning datetime columns: {e}")
        # Return original dataframe if cleaning fails
        return df


# Round 6 / Phase 1.5: single source of truth for "high-impact"
# external service incidents.  Both the renewal Word document
# ("High-Impact Incidents" row in Customer Health Dashboard) and the
# matplotlib "Service Incidents Timeline" chart (red-bar selection)
# now route through this helper so the same incident set is labeled
# consistently across surfaces.
#
# Round 11 / Phase 2.3: previously the helper recognized only the
# three "active investigation" statuses (investigating / identified /
# monitoring), but two other surfaces ALSO counted high-impact
# incidents and used DIFFERENT definitions:
#   - "Renewal Risk Correlation" prose (~8185) accepted ``active`` and
#     ``major_outage`` plus ``impact_level in {high, critical, major}``
#   - The per-incident bullet list (~8212) only flagged the original
#     three.
# That meant a customer could see "5 high-impact incidents" in the
# correlation paragraph and "2 high-impact incidents" in the
# Customer Health Dashboard table on the SAME page.  Expand the
# helper to recognize the union of all four sites' criteria
# (active investigation statuses ∪ ``active``/``major_outage`` ∪
# ``impact_level`` HIGH/CRITICAL/MAJOR) and route every site
# through it so the count agrees everywhere.  ``resolved`` /
# ``completed`` are explicitly excluded because a resolved
# incident is, by definition, no longer impacting the customer.
_HIGH_IMPACT_INCIDENT_STATUSES = frozenset(
    {
        # Original "active investigation" set (kept for chart parity).
        "investigating",
        "identified",
        "monitoring",
        # Round 11 / Phase 2.3: added so the helper agrees with the
        # renewal-correlation narrative and the per-row bullet list.
        "active",
        "major_outage",
    }
)
_HIGH_IMPACT_INCIDENT_LEVELS = frozenset(
    {"high", "critical", "major"}
)
_RESOLVED_INCIDENT_STATUSES = frozenset(
    {"resolved", "completed", "closed", "postmortem"}
)

# Round 11 / Phase 5.3: single source of truth for the case-priority
# pie palette so every chart renders the same color for the same
# normalized priority.  Previously two pies disagreed on the
# "Unknown" wedge color (``#9e9e9e`` vs ``#9aa0a6``) which made
# them look like they were measuring different things.  Centralize
# here so future tweaks land in exactly one place.
SEVERITY_COLORS = {
    'P1': '#d62728',
    'P2': '#ff7f0e',
    'P3': '#ffd700',
    'P4': '#2ca02c',
    'Unknown': '#9e9e9e',
}
SEVERITY_COLOR_DEFAULT = '#1f77b4'


def _r10_autopct(p):
    """Round 11 / Phase 8.4: shared autopct helper for severity/
    risk pies.  Mirrors the same-named helper in
    ``adoptiq_backend.py`` so a non-zero slice never renders as
    ``0.0%`` and visible percents always sum to ~100.  ``%1.1f%%``
    on its own would print ``0.0%`` for any slice below 0.05% and
    actively mislead readers.
    """
    try:
        p = float(p or 0.0)
    except (TypeError, ValueError):
        return ''
    if p <= 0:
        return ''
    if p < 1.0:
        return '<1%'
    return f'{p:.1f}%'


def _is_high_impact_incident(inc) -> bool:
    """Return True when ``inc`` represents an active, high-impact
    service incident.  Round 11 / Phase 2.3 expanded the criteria so
    every call site (dashboard chart, customer health dashboard, the
    renewal correlation paragraph at ~8185, and the per-row decoration
    at ~8212) shares the same definition.
    """
    if not isinstance(inc, dict):
        return False
    try:
        status = str(inc.get("status", "")).strip().lower()
        impact = str(inc.get("impact_level", "")).strip().lower()
    except Exception:
        return False
    # Resolved incidents are never high-impact regardless of the
    # original ``impact_level`` annotation.
    if status in _RESOLVED_INCIDENT_STATUSES:
        return False
    if status in _HIGH_IMPACT_INCIDENT_STATUSES:
        return True
    if impact in _HIGH_IMPACT_INCIDENT_LEVELS:
        return True
    return False


def _count_high_impact_incidents(incidents) -> int:
    if not incidents:
        return 0
    try:
        return sum(1 for inc in incidents if _is_high_impact_incident(inc))
    except Exception:
        return 0


def _safe_doc_text(value, max_len: int = 200) -> str:
    """Round 6 / Phase 1.4: sanitize a string before docx.add_heading /
    add_run.  Drops XML-illegal control codes, collapses whitespace,
    and caps length so a malformed customer/manager string can't crash
    the docx writer (or produce a Word repair-required document).
    """
    try:
        s = "" if value is None else str(value)
    except Exception:
        return ""
    cleaned = []
    for ch in s:
        cp = ord(ch)
        if cp < 0x20 and ch not in ("\t", "\n", "\r"):
            continue
        if 0xD800 <= cp <= 0xDFFF:
            continue
        cleaned.append(ch)
    s = "".join(cleaned)
    import re as _re_local
    s = _re_local.sub(r"\s+", " ", s).strip()
    if max_len and len(s) > max_len:
        s = s[: max_len - 1] + "…"
    return s


# Round 6 / Phase 1.18: Excel cells have a hard 32767-character limit
# (xlsxwriter raises silently or truncates).  When we clip a cell we
# count it here so the workbook can append a footnote in
# ``Report_Info`` describing how many cells overflowed and what cap
# applied.  The counter is intentionally process-global because the
# Excel writers are sequential per request.
EXCEL_MAX_CELL_CHARS = 32767
_EXCEL_TRUNCATION_COUNTER = {"cells_clipped": 0, "max_seen": 0}


def _excel_safe_cell(value):
    """Round 6 / Phase 1.2 + 1.18: coerce a cell value to something
    xlsxwriter can serialize without rendering ``NaN`` / ``inf`` /
    ``pd.NA`` / ``NaT`` as misleading text, AND clip oversized strings
    to Excel's 32767-character cap with an explicit truncation marker
    so the reader can tell the cell was clipped.

    xlsxwriter writes ``float('nan')`` as a literal "nan" cell, not a
    blank, which downstream consumers (and the auto-filter UI) mis-read
    as a real value.  ``pd.NA`` raises in some xlsxwriter versions, and
    ``inf`` / ``-inf`` blow past Excel's numeric range.  Normalize all
    of these to ``None`` (Excel blank) and pass other values through
    unchanged.
    """
    try:
        if value is None:
            return None
        # pandas missing sentinels (works for pd.NA, NaT, NaN-of-various-dtypes)
        try:
            if pd.isna(value):
                return None
        except Exception:
            pass
        # Reject non-finite floats (NaN already handled above; this catches inf)
        if isinstance(value, float):
            try:
                import math as _math
                if not _math.isfinite(value):
                    return None
            except Exception:
                return None
        # Round 6 / Phase 1.18: clip oversized text and record the
        # truncation so the workbook can add a Report_Info footnote.
        if isinstance(value, str) and len(value) > EXCEL_MAX_CELL_CHARS:
            try:
                _EXCEL_TRUNCATION_COUNTER["cells_clipped"] += 1
                if len(value) > _EXCEL_TRUNCATION_COUNTER["max_seen"]:
                    _EXCEL_TRUNCATION_COUNTER["max_seen"] = len(value)
            except Exception:
                pass
            marker = " ...[TRUNCATED]"
            keep = EXCEL_MAX_CELL_CHARS - len(marker)
            return (value[:keep] if keep > 0 else value[:EXCEL_MAX_CELL_CHARS]) + marker
        return value
    except Exception:
        return value


def _excel_truncation_snapshot_and_reset():
    """Return current truncation counter and reset to zero.

    Round 6 / Phase 1.18: the workbook writer calls this *after* all
    sheets are written so it can append a Report_Info footnote
    describing how many cells were clipped at the 32767-char Excel cap.
    """
    snap = dict(_EXCEL_TRUNCATION_COUNTER)
    _EXCEL_TRUNCATION_COUNTER["cells_clipped"] = 0
    _EXCEL_TRUNCATION_COUNTER["max_seen"] = 0
    return snap


def _validate_excel_output(excel_path) -> bool:
    """Validate a completed Excel workbook after the writer context has closed."""
    if not excel_path or not os.path.exists(excel_path):
        logger.error("[[DATA]] Excel file does not exist after creation!")
        return False

    try:
        file_size = os.path.getsize(excel_path)
        logger.info(f"[[DATA]] Excel file size: {file_size} bytes")
        if file_size <= 0:
            logger.error("[[SEARCH]] DEBUGGING - Excel validation: FAILED - workbook is empty after creation.")
            return False

        test_read = pd.read_excel(excel_path, sheet_name=None, nrows=1, engine='openpyxl')
        logger.info(f"[[SEARCH]] DEBUGGING - Excel validation: SUCCESS - {len(test_read)} sheets")
        for sheet_name in test_read.keys():
            logger.info(f"   - Sheet: {sheet_name}")
        return True
    except Exception as e:
        logger.error(f"[[SEARCH]] DEBUGGING - Excel validation: FAILED - {e}")
        return False

def _get_all_customers_from_all_sources(ab_norm: pd.DataFrame = None, csone_df: pd.DataFrame = None, 
                                        team_subs_df: pd.DataFrame = None,
                                        csconsole_action_plans: pd.DataFrame = None,
                                        csconsole_customer_pulse: pd.DataFrame = None,
                                        csconsole_success_priorities: pd.DataFrame = None,
                                        csconsole_adoption_barriers: pd.DataFrame = None) -> set:
    """
    Get ALL unique customers from ALL available data sources.
    This ensures consistent customer counts across all report types.
    
    Args:
        ab_norm: Adoption barriers DataFrame
        csone_df: CSOne cases DataFrame
        team_subs_df: Team subscriptions DataFrame
        csconsole_action_plans: CSConsole action plans DataFrame
        csconsole_customer_pulse: CSConsole customer pulse DataFrame
        csconsole_success_priorities: CSConsole success priorities DataFrame
        csconsole_adoption_barriers: CSConsole adoption barriers DataFrame
    
    Returns:
        Set of unique customer names from all sources
    """
    # Round 3 hardening: route the entire customer-set computation
    # through ``cm.list_customers`` so EI's dashboard, Compact's
    # at-a-glance, ``build_portfolio_metrics``'s ``total_customers`` and
    # the report-consistency validator all use the SAME definition.
    # ``cm.list_customers`` accepts (a) the same multi-source frames and
    # (b) an ``account_to_customer`` map for the ACCOUNT_ID → BU_NAME
    # backfill the dashboard previously did inline. Behavior is
    # therefore preserved bit-for-bit while eliminating the two-source
    # drift documented in round 3 finding #12.
    customer_lookup = build_customer_lookup(team_subs_df)
    account_to_customer = customer_lookup.get("account_to_customer", {}) or {}

    canonical_names = cm.list_customers(
        ab_df=ab_norm,
        csone_df=csone_df,
        subs_df=team_subs_df,
        action_plans_df=csconsole_action_plans,
        pulse_df=csconsole_customer_pulse,
        extra_frames=[csconsole_success_priorities, csconsole_adoption_barriers],
        account_to_customer=account_to_customer,
    )
    all_customers = set(canonical_names)

    logger.info(
        f"[[CUSTOMER_COUNT]] TOTAL unique customers from all sources (canonical): "
        f"{len(all_customers)}"
    )
    return all_customers


def _has_customer_activity_for_deep_dive(
    cust_ab: pd.DataFrame,
    cust_csone: pd.DataFrame,
    cust_action_plans: pd.DataFrame,
    cust_customer_pulse: pd.DataFrame,
    cust_success_priorities: pd.DataFrame,
    cust_csconsole_adoption_barriers: pd.DataFrame,
) -> bool:
    """Return True when any customer data source has at least one row."""
    for frame in (
        cust_ab,
        cust_csone,
        cust_action_plans,
        cust_customer_pulse,
        cust_success_priorities,
        cust_csconsole_adoption_barriers,
    ):
        if frame is not None and hasattr(frame, "empty") and not frame.empty:
            return True
    return False

def _generate_comprehensive_fallback_insights(
    ab_norm,
    csone_df,
    manager,
    technology,
    *,
    team_subs_df=None,
    csconsole_action_plans=None,
    csconsole_customer_pulse=None,
    csconsole_success_priorities=None,
    csconsole_adoption_barriers=None,
    llm_error=None,
):
    """Generate non-AI fallback insights when the LLM is unavailable.

    Phase 1.6: this code is NOT AI output and must not be labeled as such.
    Callers should render the resulting bundle under a "Non-AI fallback
    summary" heading and surface ``llm_error`` so the reader knows why the
    AI summary is missing.

    Also accepts the same multi-source customer frames the AI path uses so
    the customer count in the fallback narrative agrees with the headline.
    Without ``team_subs_df`` / CSConsole frames the fallback under-counts
    any customer that exists only in subscription / pulse / action-plan
    data (which is exactly the path that's been producing "12 in
    dashboard, 9 in narrative" mismatches).
    """
    insights = []
    ab_norm = ab_norm if ab_norm is not None else pd.DataFrame()
    csone_df = csone_df if csone_df is not None else pd.DataFrame()
    
    # Portfolio overview - Use comprehensive function to get ALL customers from ALL sources
    all_customers_set = _get_all_customers_from_all_sources(
        ab_norm=ab_norm,
        csone_df=csone_df,
        team_subs_df=team_subs_df,
        csconsole_action_plans=csconsole_action_plans,
        csconsole_customer_pulse=csconsole_customer_pulse,
        csconsole_success_priorities=csconsole_success_priorities,
        csconsole_adoption_barriers=csconsole_adoption_barriers,
    )
    total_customers = len(all_customers_set)
    ab_count = len(ab_norm)
    case_count = len(csone_df)
    
    insights.append(f"Portfolio Analysis for {manager} - {technology} Technology Focus")
    insights.append(f"This comprehensive analysis covers {total_customers} customers with {ab_count} adoption barriers and {case_count} support cases identified over the analysis period.")
    
    # Risk assessment (Round 3: route via canonical severity normalization
    # so that "Critical" and "High" counts agree with the leader/EI/compact
    # reports and the Critical Adoption Barriers section).
    if not ab_norm.empty:
        try:
            critical_abs = int(cm.count_critical_barriers(
                ab_norm, mode=cm.CRITICAL_AB_MODE_CRITICAL_ONLY,
            ))
            critical_or_high = int(cm.count_critical_barriers(
                ab_norm, mode=cm.CRITICAL_AB_MODE_CRITICAL_OR_HIGH,
            ))
            high_abs = max(critical_or_high - critical_abs, 0)
        except Exception:
            critical_abs = 0
            high_abs = 0

        if critical_abs > 0:
            insights.append(f"CRITICAL ATTENTION REQUIRED: {critical_abs} critical adoption barriers identified that pose immediate risk to customer success and renewal likelihood.")

        if high_abs > 0:
            insights.append(f"HIGH PRIORITY: {high_abs} high-severity adoption barriers require focused intervention within the next 30 days.")

    # Support case analysis (canonical priority counts)
    if not csone_df.empty:
        p1_cases = cm.count_p1(csone_df)

        # Use canonical P1+P2 priority count as the "escalated" signal
        # (cm.count_escalated). The previous code used
        # ``Status.str.contains('Escalated')`` which silently matched
        # "De-escalated" / "Re-escalated" labels and disagreed with the
        # leader/EI/compact reports. Tying "escalated" to canonical P1+P2
        # gives a single, auditable definition across all reports.
        try:
            escalated_cases = int(cm.count_escalated(csone_df))
        except Exception:
            escalated_cases = 0
        
        if p1_cases > 0:
            insights.append(f"URGENT: {p1_cases} P1 support cases require immediate executive attention and resource allocation.")
        
        if escalated_cases > 0:
            insights.append(f"ESCALATION ALERT: {escalated_cases} cases have been escalated, indicating potential customer satisfaction risks.")
    
    # Data-driven: top at-risk customers and BEMS count
    if not ab_norm.empty and 'customer_name' in ab_norm.columns:
        # Round 13 / Phase 3.11: route customer through
        # ``normalize_customer_name`` before the groupby so cosmetic
        # spelling drift collapses into a single "top at-risk" entry
        # instead of inflating the list with two variants of the same
        # account.
        try:
            from data_normalization import normalize_customer_name as _r13_norm_cust_top
        except Exception:
            _r13_norm_cust_top = lambda v: v  # noqa: E731 - identity fallback
        _ab_top = ab_norm.copy()
        _ab_top['_cust_disp'] = (
            _ab_top['customer_name'].fillna('Unknown').apply(_r13_norm_cust_top)
        )
        # Round 13 / Phase 6.1: previously the at-risk list emitted only
        # the first 5 customers with no disclosure that more existed.
        # Readers therefore could not tell whether 5 was the literal
        # population size or whether 47 other accounts had been
        # silently dropped.  Stamp a deterministic "+N more" footer
        # whenever the population exceeds the cap so the truncation
        # is honest.  Sort secondary on ``_cust_disp`` so accounts
        # with identical barrier counts pick a stable order across
        # runs (otherwise the head(5) cut depends on dict ordering
        # of pandas size aggregation, which can flip on tie).
        by_cust = (
            _ab_top.groupby('_cust_disp')
            .size()
            .reset_index(name='_count')
            .sort_values(
                by=['_count', '_cust_disp'],
                ascending=[False, True],
                kind='mergesort',
            )
            .set_index('_cust_disp')['_count']
        )
        _r13_top_cap = 5
        top_at_risk = by_cust.head(_r13_top_cap).index.tolist()
        if top_at_risk:
            _r13_top_total = int(len(by_cust))
            _r13_top_extra = max(0, _r13_top_total - _r13_top_cap)
            _r13_top_msg = ', '.join(top_at_risk[:_r13_top_cap])
            if _r13_top_extra > 0:
                _r13_top_msg = f"{_r13_top_msg} (+{_r13_top_extra} more)"
            insights.append(f"TOP CUSTOMERS BY ADOPTION BARRIERS: {_r13_top_msg}.")
    bems_total = cm.count_bems(csone_df) if not csone_df.empty else 0
    if bems_total > 0:
        insights.append(
            f"BEMS ENGINEERING ESCALATIONS: {int(bems_total)} cases require specialized engineering support—high renewal risk indicator. "
            f"[Source: CSOne (Transaction ID, bemscsc_refs); Field(s): Transaction ID, bemscsc_refs; Verification: BEMS IDs verifiable in CSOne]"
        )
    
    # Strategic recommendations
    insights.append("STRATEGIC RECOMMENDATIONS:")
    insights.append("1. Implement weekly executive reviews for all critical and high-severity issues")
    insights.append("2. Establish dedicated customer success pods for at-risk accounts")
    insights.append("3. Deploy proactive health monitoring and early warning systems")
    insights.append("4. Create customer-specific success plans with measurable outcomes")
    insights.append("5. Enhance technical enablement programs to reduce adoption barriers")
    
    # Business impact
    insights.append("BUSINESS IMPACT: Addressing these issues proactively will improve customer satisfaction scores, reduce churn risk, and increase renewal rates. Executive engagement is critical for successful outcomes.")

    # Phase 1.6: prefix the bundle with an honesty header so any downstream
    # renderer (compact / EI / leader) cannot pass this off as AI output.
    header_lines = [
        "[Non-AI fallback summary] The LLM did not return a usable response "
        "for this run. The text below is rule-based output computed directly "
        "from the canonical metrics (no model inference)."
    ]
    if llm_error:
        header_lines.append(f"[LLM error] {str(llm_error).strip()}")
    return " ".join(header_lines + [""] + insights)

def _parse_markdown_for_fallback(doc, ai_text: str):
    """Parse AI markdown and add clean content to Word document - CRITICAL FIX

    Round 12 / Phase 9.6: previously every ``doc.add_heading`` /
    ``doc.add_paragraph`` / ``para.add_run`` in this fallback parser
    was fed the raw AI string verbatim.  If the model emitted an
    XML-illegal control byte (e.g. a stray 0x07 BEL or unpaired
    surrogate from a quoted log fragment) the docx serializer would
    raise on save and the entire fallback Word document would be
    lost -- exactly the failure mode Round 8 hardened every other
    AI->docx writer against by routing through ``_safe_doc_text`` /
    ``_safe_add_run``.  Bring the markdown fallback path into Round
    8 parity by sanitizing every text node before it reaches the
    docx surface.  We deliberately re-use the existing helpers here
    rather than calling ``docx`` directly so the same sanitization
    rules (control-code drop, whitespace collapse, length cap)
    apply uniformly.
    """
    import re
    from docx.shared import Pt
    from docx.enum.text import WD_ALIGN_PARAGRAPH

    # Round 12 / Phase 9.6: a missing/None ``ai_text`` previously
    # crashed at ``.replace`` time -- guard the entry point so the
    # fallback never blows up the document save.
    if ai_text is None:
        return
    try:
        ai_text = str(ai_text)
    except Exception:
        return

    # Remove instruction symbols
    ai_text = ai_text.replace('**YOUR MISSION:**', '').replace('**CRITICAL REQUIREMENTS:**', '')
    ai_text = ai_text.replace('**TECHNOLOGY FOCUS:**', '').replace('**DATA SOURCES:**', '')

    def _r12_safe_run(paragraph, text, *, bold=False, max_len=5000):
        """Round 12 / Phase 9.6 inline ``_safe_add_run`` companion.
        Routes ``text`` through ``_safe_doc_text`` so XML-illegal
        control bytes and unpaired surrogates can never reach the
        underlying docx run.
        """
        run = paragraph.add_run(_safe_doc_text(text, max_len=max_len))
        if bold:
            run.bold = True
        return run

    lines = ai_text.split('\n')
    for line in lines:
        line = line.strip()
        if not line or any(x in line for x in ['YOUR MISSION:', 'CRITICAL REQUIREMENTS:']):
            continue

        # Convert headings (remove ##)
        if line.startswith('#'):
            level = len(line) - len(line.lstrip('#'))
            heading_text = line.lstrip('#').replace('**', '').strip()
            if heading_text:
                doc.add_heading(_safe_doc_text(heading_text, max_len=300), min(level, 3))

        # Handle separators
        elif line.startswith('---'):
            sep_para = doc.add_paragraph()
            sep_run = sep_para.add_run('_' * 50)
            sep_run.font.size = Pt(8)
            sep_para.alignment = WD_ALIGN_PARAGRAPH.CENTER

        # Handle bullets
        elif line.startswith(('• ', '* ', '- ')):
            text = line[2:].replace('**', '')
            doc.add_paragraph(_safe_doc_text(text, max_len=5000), style='List Bullet')

        # Handle numbered lists
        elif re.match(r'^\d+[\.\)]\s', line):
            text = re.sub(r'^\d+[\.\)]\s*', '', line).replace('**', '')
            doc.add_paragraph(_safe_doc_text(text, max_len=5000), style='List Number')

        # Regular paragraphs - handle bold text
        elif line:
            if '**' in line:
                para = doc.add_paragraph()
                parts = re.split(r'(\*\*[^*]+\*\*)', line)
                for part in parts:
                    if part.startswith('**') and part.endswith('**'):
                        # Round 14 / Phase 4.2: ``part.strip('**')`` is
                        # misleading -- ``str.strip`` treats the argument
                        # as a *set* of characters, so this strips any
                        # number of ``*`` from both ends rather than the
                        # literal ``**`` prefix/suffix the writer clearly
                        # meant.  In practice the regex above guarantees
                        # exactly two leading and two trailing stars on a
                        # core with no embedded ``*``, so the observed
                        # output is unchanged, but the slice expression
                        # below makes the intent explicit and silences
                        # ruff B005.
                        _r12_safe_run(para, part[2:-2], bold=True)
                    elif part:
                        _r12_safe_run(para, part)
            else:
                doc.add_paragraph(_safe_doc_text(line, max_len=5000))

_R13_LABEL_MAX_LEN = 28


def _r13_truncate_chart_labels(labels, max_len: int = _R13_LABEL_MAX_LEN):
    """Round 13 / Phase 8.6: truncate long axis labels for chart legibility.

    The Word reports embed 12x8 figures at ``Inches(6.5)``.  At that
    rendered width, customer names longer than ~28 characters either
    overflow the y-axis margin (matplotlib clips them silently) or
    force ``tight_layout`` to shrink the plot area to fit, which
    squeezes the data plot into a narrow strip and hides smaller bars.

    Truncate display labels to ``max_len`` characters with an ellipsis
    so the chart is legible, while leaving the original full labels
    available for the alt-text helper (so screen readers and the Word
    docPr description still surface the complete customer name).

    Returns ``(display_labels, full_labels)`` so callers can feed the
    first to ``set_yticklabels`` / ``set_xticklabels`` and the second
    to the alt-text helper.
    """
    display: list[str] = []
    full: list[str] = []
    try:
        cap = int(max_len) if max_len and int(max_len) > 4 else _R13_LABEL_MAX_LEN
    except Exception:
        cap = _R13_LABEL_MAX_LEN
    for raw in labels or []:
        text = '' if raw is None else str(raw)
        full.append(text)
        if len(text) > cap:
            display.append(text[: max(1, cap - 1)].rstrip() + '\u2026')
        else:
            display.append(text)
    return display, full


def _r13_chart_alt_text(title: str, full_labels=None, value_labels=None, max_chars: int = 1024) -> str:
    """Round 13 / Phase 8.6 + 9.10: build alt text for an embedded chart.

    The Word ``add_picture`` calls have no alt text by default, which
    means screen readers announce the chart filename only and do not
    expose the underlying data.  This helper composes a short
    description from the chart title and (optionally) the full,
    untruncated category labels and their values, which we then attach
    to the picture inline shape via ``docPr``.

    Caller supplies:
      * ``title``: chart title ("Top 10 Customers by Support Case Volume")
      * ``full_labels``: original (un-truncated) category labels
      * ``value_labels``: aligned numeric labels (e.g. "12 cases").
        If supplied, must be the same length as ``full_labels``.

    Returns a single string capped at ``max_chars`` so we never write
    a 100k-character description into a Word docPr (the OOXML schema
    technically allows it, but Word truncates and some accessibility
    tools struggle).
    """
    parts: list[str] = []
    if title:
        parts.append(str(title).strip())
    try:
        if full_labels:
            pairs: list[str] = []
            vals = list(value_labels or [])
            for idx, lbl in enumerate(full_labels):
                lbl_text = '' if lbl is None else str(lbl)
                if idx < len(vals) and vals[idx] is not None:
                    pairs.append(f"{lbl_text}: {vals[idx]}")
                else:
                    pairs.append(lbl_text)
            if pairs:
                parts.append("Categories: " + "; ".join(pairs))
    except Exception:
        pass
    out = ". ".join(p for p in parts if p)
    if max_chars and len(out) > max_chars:
        out = out[: max(0, max_chars - 1)].rstrip() + '\u2026'
    return out


def _r13_set_picture_alt_text(picture, alt_text: str) -> None:
    """Round 13 / Phase 8.6 + 9.10: stamp alt text on an embedded picture.

    python-docx exposes the inline shape via ``picture._inline``; the
    accessibility-relevant fields are ``docPr.descr`` (long
    description) and ``docPr.title`` (short title).  Some legacy
    consumers also read ``cNvPr.descr``.  This helper writes both
    where available and silently no-ops on any failure so a missing
    schema attribute never crashes a report build.
    """
    if not alt_text or picture is None:
        return
    try:
        inline = getattr(picture, '_inline', None)
        if inline is None:
            return
        text = str(alt_text)
        try:
            doc_pr = inline.docPr
            doc_pr.set('descr', text)
            if not doc_pr.get('title'):
                doc_pr.set('title', text[:120])
        except Exception:
            pass
        try:
            for cNvPr in inline.iter('{http://schemas.openxmlformats.org/drawingml/2006/main}cNvPr'):
                cNvPr.set('descr', text)
        except Exception:
            pass
    except Exception:
        pass


def _r13_close_fig(fig=None) -> None:
    """Round 13 / Phase 8.5: explicit per-figure teardown helper.

    ``plt.close()`` (no args) closes "the current figure" -- whichever
    figure was last activated by ``plt.figure``/``plt.subplots``
    globally.  In a server process that builds many charts back-to-back
    (and especially across worker threads) the current-figure pointer
    can race with the figure we actually wanted to release, leading to
    slow figure leaks over the lifetime of a long-running daemon.
    Always pass an explicit ``fig`` handle when one is in scope so the
    exact figure we just rendered is freed; if no ``fig`` is provided
    or the close fails (some legacy backends raise on closed figures),
    fall back to the no-arg form so we never crash a chart pipeline
    over a teardown bookkeeping issue.
    """
    try:
        import matplotlib.pyplot as _r13_plt
    except Exception:
        return
    try:
        if fig is not None:
            _r13_plt.close(fig)
        else:
            _r13_plt.close()
    except Exception:
        try:
            _r13_plt.close()
        except Exception:
            pass


def create_executive_charts(
    ab_norm: pd.DataFrame,
    arr_data: pd.DataFrame,
    arr_impact: Dict,
    csone_df: pd.DataFrame = None,
    feature_requests: Dict = None,
) -> List[str]:
    """Create executive-ready non-financial charts and save as images."""
    chart_paths: List[str] = []
    feature_requests = feature_requests or {'total_requests': 0, 'top_features': [], 'customer_examples': []}

    try:
        import matplotlib
        matplotlib.use('Agg')
        import matplotlib.pyplot as plt

        try:
            plt.style.use('seaborn-v0_8-whitegrid')
        except Exception:
            logger.debug("matplotlib seaborn style unavailable, using default")

        csone_df = csone_df if isinstance(csone_df, pd.DataFrame) else pd.DataFrame()
        cust_col = next(
            (c for c in ['customer_name', 'Customer Name', 'BU_NAME', 'Customer'] if c in csone_df.columns),
            None,
        )

        # Chart 1: Support Case Trends
        if not csone_df.empty and 'Date/Time Opened' in csone_df.columns:
            fig, ax = plt.subplots(figsize=(10, 6))
            # Round 13 / Phase 2.9: parse with utc=True so rows that
            # carry explicit offsets land in the same UTC month bucket
            # as the rest of the UTC-anchored case-volume analysis.
            date_series = pd.to_datetime(
                csone_df['Date/Time Opened'], errors='coerce', utc=True
            )
            monthly_cases = csone_df.groupby(date_series.dt.to_period('M')).size()
            if len(monthly_cases) > 0:
                months = [str(period) for period in monthly_cases.index]
                bars = ax.bar(months, monthly_cases.values, color='#1f77b4')
                # Round 4: title explicitly reflects that this groups the
                # full ``csone_df`` it received (no internal date filter).
                # The number of months shown equals ``len(months)`` —
                # surface that in the title so readers can immediately
                # see whether they are looking at 3 months or 24 months.
                ax.set_title(
                    f'Support Cases by Month ({len(months)} months in source data)',
                    fontsize=14,
                    fontweight='bold',
                )
                ax.set_ylabel('Number of Cases', fontsize=12)
                ax.set_xlabel('Month', fontsize=12)
                for bar, value in zip(bars, monthly_cases.values):
                    ax.text(
                        bar.get_x() + bar.get_width() / 2.0,
                        bar.get_height() + 0.1,
                        f'{int(value)}',
                        ha='center',
                        va='bottom',
                        fontweight='bold',
                    )
                plt.xticks(rotation=45, ha='right')
                plt.tight_layout()
                # Round 12 / Phase 10.6: previously every chart filename in
                # this module suffixed ``datetime.now().strftime('%Y%m%d_%H%M%S')``
                # (HOST-LOCAL clock, no timezone marker), so two operators
                # generating the same logical report on machines in
                # different timezones would write artifacts under different
                # filenames -- breaking cross-machine reproducibility for
                # the audit trail.  Anchor on UTC and append a ``Z`` so the
                # chart filename embeds an unambiguous timezone marker.
                chart_path = f"outputs/support_cases_trend_{datetime.now(timezone.utc).strftime('%Y%m%d_%H%M%SZ')}.png"
                plt.savefig(chart_path, dpi=300, bbox_inches='tight')
                _r13_close_fig(fig)
                chart_paths.append(chart_path)

        # Chart 2: Case Severity Distribution (canonical normalized priority).
        # Building the pie from case_priority_norm collapses synonyms ("P1",
        # "1", "Critical") into a single P1 wedge and includes an explicit
        # "Unknown" wedge for missing values, so the pie's total equals the
        # headline "Total: N cases" and matches cm.count_p1/p2/p3/p4 elsewhere.
        if not csone_df.empty:
            try:
                _csone_norm_for_pie = add_case_lifecycle_fields(csone_df)
            except Exception:
                _csone_norm_for_pie = csone_df
            if 'case_priority_norm' in _csone_norm_for_pie.columns:
                severity_series = _csone_norm_for_pie['case_priority_norm'].fillna('Unknown').astype(str)
                # Preserve a stable ordering for legend / colors regardless
                # of which categories happen to be present in the data.
                _ordered_keys = ['P1', 'P2', 'P3', 'P4', 'Unknown']
                raw_counts = severity_series.value_counts()
                severity_counts = pd.Series(
                    [int(raw_counts.get(k, 0)) for k in _ordered_keys],
                    index=_ordered_keys,
                )
                # Drop empty buckets so the chart isn't cluttered with 0-slices,
                # but always keep at least P1/P2/Unknown if any of them exist.
                severity_counts = severity_counts[severity_counts > 0]
                if not severity_counts.empty:
                    fig, ax = plt.subplots(figsize=(10, 8))
                    # Round 11 / Phase 5.3: use the shared
                    # ``SEVERITY_COLORS`` constant so this pie and
                    # the renewal-health severity pie below cannot
                    # disagree on the "Unknown" wedge hex.
                    color_map = SEVERITY_COLORS
                    colors = [color_map.get(str(sev), SEVERITY_COLOR_DEFAULT) for sev in severity_counts.index]
                    # Round 11 / Phase 8.4: use shared _r10_autopct
                    # so non-zero slices below 0.05% never render as "0.0%".
                    ax.pie(
                        severity_counts.values,
                        labels=[f'{sev} ({count})' for sev, count in zip(severity_counts.index, severity_counts.values)],
                        autopct=_r10_autopct,
                        colors=colors,
                        startangle=90,
                        textprops={'fontsize': 11, 'weight': 'bold'},
                    )
                    # Round 13 / Phase 8.1: enforce 1:1 aspect on
                    # every pie chart so wedge area is proportional
                    # to value, regardless of the surrounding figure
                    # ratio (matplotlib's default lets a non-square
                    # subplot squash the pie into an oval which
                    # subtly distorts the apparent share of each
                    # slice).
                    try:
                        ax.set_aspect('equal')
                    except Exception:
                        pass
                    ax.set_title('Case Severity Distribution (normalized P1-P4)', fontsize=14, fontweight='bold', pad=20)
                    plt.tight_layout()
                    chart_path = f"outputs/severity_distribution_{datetime.now(timezone.utc).strftime('%Y%m%d_%H%M%SZ')}.png"
                    plt.savefig(chart_path, dpi=300, bbox_inches='tight')
                    _r13_close_fig(fig)
                    chart_paths.append(chart_path)

        # Chart 3: Top Customers by Case Volume
        if not csone_df.empty and cust_col:
            fig, ax = plt.subplots(figsize=(12, 8))
            # Round 10 / Phase 8.3: ``value_counts()`` does not specify
            # tie-breaker order, so two customers with the same case
            # count can swap positions between runs (and between
            # Word/Excel renders that re-execute this block).  Sort
            # the full count series with an explicit
            # ``(-count, name.lower())`` key so the top-10 is
            # deterministic on ties.
            _cust_counts_full = csone_df[cust_col].value_counts()
            try:
                _cust_counts_sorted = pd.Series(
                    {
                        _name: int(_count)
                        for _name, _count in sorted(
                            _cust_counts_full.items(),
                            key=lambda kv: (-int(kv[1] or 0), str(kv[0]).lower()),
                        )
                    }
                )
                customer_cases = _cust_counts_sorted.head(10)
            except Exception:
                customer_cases = _cust_counts_full.head(10)
            # Round 11 / Phase 8.7: previous code mapped case volume
            # to red/orange/green via fixed thresholds, which read as
            # "risk" semantics (customer X is critical, customer Y is
            # healthy) when the chart is just a count.  Use a neutral
            # mono-hue colormap so volume bars stay agnostic about
            # risk band membership.
            try:
                _vmin = float(min(customer_cases.values)) if len(customer_cases) else 0.0
                _vmax = float(max(customer_cases.values)) if len(customer_cases) else 1.0
                if _vmax <= _vmin:
                    _vmax = _vmin + 1.0
                _cmap = plt.get_cmap('Blues')
                colors = [_cmap(0.35 + 0.55 * ((float(_v) - _vmin) / (_vmax - _vmin))) for _v in customer_cases.values]
            except Exception:
                colors = ['#1f77b4'] * len(customer_cases)
            bars = ax.barh(range(len(customer_cases)), customer_cases.values, color=colors)
            ax.set_title('Top 10 Customers by Support Case Volume', fontsize=14, fontweight='bold', pad=15)
            ax.set_xlabel('Number of Cases', fontsize=12, fontweight='bold')
            ax.set_ylabel('Customer', fontsize=12, fontweight='bold')
            for bar, value in zip(bars, customer_cases.values):
                ax.text(
                    bar.get_width() + 0.5,
                    bar.get_y() + bar.get_height() / 2.0,
                    f'{int(value)} cases',
                    ha='left',
                    va='center',
                    fontweight='bold',
                    fontsize=10,
                )
            ax.set_yticks(range(len(customer_cases)))
            # Round 13 / Phase 8.6: previously the raw customer_cases
            # index was passed straight to set_yticklabels, so a name
            # like "Acme International Solutions Group, Inc.,
            # Cybersecurity Division" overflowed the 12x8 fig embedded
            # at Inches(6.5) and either got clipped silently or forced
            # tight_layout to shrink the plot area.  Truncate the
            # *display* label and stash the full name on the axes for
            # the alt-text helper that runs at doc.add_picture() time.
            _r13_disp, _r13_full = _r13_truncate_chart_labels(list(customer_cases.index))
            ax.set_yticklabels(_r13_disp, fontsize=10)
            try:
                ax._r13_full_labels = _r13_full
                ax._r13_value_labels = [f'{int(v)} cases' for v in customer_cases.values]
            except Exception:
                pass
            ax.invert_yaxis()
            ax.grid(axis='x', alpha=0.3)
            plt.tight_layout()
            chart_path = f"outputs/top_customers_analysis_{datetime.now(timezone.utc).strftime('%Y%m%d_%H%M%SZ')}.png"
            plt.savefig(chart_path, dpi=300, bbox_inches='tight')
            _r13_close_fig(fig)
            chart_paths.append(chart_path)

        # Chart 4: BEMS Escalations by Customer
        bems_cases, _ = detect_bems_escalations(csone_df)
        bems_cust_col = next((c for c in ['customer_name', 'Customer Name', 'BU_NAME', 'Customer'] if c in bems_cases.columns), None) if not bems_cases.empty else None
        if not bems_cases.empty and bems_cust_col:
            fig, ax = plt.subplots(figsize=(12, 8))
            # Round 11 / Phase 8.2: ``value_counts().head(10)`` does not
            # guarantee an order on ties, so two customers with the
            # same BEMS count can swap between runs.  Sort with an
            # explicit ``(-count, name.lower())`` tie-breaker so the
            # rendered bars are reproducible.  Round 11 / Phase 8.3:
            # disclose truncation in the title when more than 10
            # customers were eligible.
            _bems_full = bems_cases[bems_cust_col].value_counts()
            try:
                _bems_sorted = pd.Series(
                    {
                        _name: int(_count)
                        for _name, _count in sorted(
                            _bems_full.items(),
                            key=lambda kv: (-int(kv[1] or 0), str(kv[0]).lower()),
                        )
                    }
                )
                bems_by_customer = _bems_sorted.head(10)
            except Exception:
                bems_by_customer = _bems_full.head(10)
            _bems_total_customers = int(_bems_full.shape[0]) if hasattr(_bems_full, 'shape') else len(_bems_full)
            # Round 13 / Phase 8.3: previously every BEMS-by-customer
            # bar was rendered in ``#d62728`` (the canonical
            # ``CRITICAL`` red).  That was incorrect signalling: the
            # bar's *height* already encodes "more BEMS == more
            # escalations", so colouring every bar critical-red made
            # a customer with 1 BEMS look as alarming as a customer
            # with 12 BEMS.  Use a neutral data-viz blue
            # (``#1f77b4``, the matplotlib default category-0 colour)
            # so colour does not pre-judge severity and the chart
            # legend stays consistent with the rest of the
            # canonical-palette work in Phase 5.
            bars = ax.barh(range(len(bems_by_customer)), bems_by_customer.values, color='#1f77b4')
            if _bems_total_customers > len(bems_by_customer):
                _bems_more = _bems_total_customers - len(bems_by_customer)
                ax.set_title(
                    f'BEMS Escalations by Customer (Top {len(bems_by_customer)} of {_bems_total_customers}; +{_bems_more} more)',
                    fontsize=14, fontweight='bold', pad=15,
                )
            else:
                ax.set_title(
                    f'BEMS Escalations by Customer (Top {len(bems_by_customer)})',
                    fontsize=14, fontweight='bold', pad=15,
                )
            ax.set_xlabel('Number of BEMS Cases', fontsize=12, fontweight='bold')
            ax.set_ylabel('Customer', fontsize=12, fontweight='bold')
            for bar, value in zip(bars, bems_by_customer.values):
                ax.text(
                    bar.get_width() + 0.1,
                    bar.get_y() + bar.get_height() / 2.0,
                    f'{int(value)} BEMS',
                    ha='left',
                    va='center',
                    fontweight='bold',
                    fontsize=10,
                )
            ax.set_yticks(range(len(bems_by_customer)))
            # Round 13 / Phase 8.6: see top_customers_analysis above
            # for the rationale -- truncate the y-axis display label
            # and keep the full customer name available for the
            # add_picture alt-text helper.
            _r13_disp, _r13_full = _r13_truncate_chart_labels(list(bems_by_customer.index))
            ax.set_yticklabels(_r13_disp, fontsize=10)
            try:
                ax._r13_full_labels = _r13_full
                ax._r13_value_labels = [f'{int(v)} BEMS' for v in bems_by_customer.values]
            except Exception:
                pass
            ax.invert_yaxis()
            ax.grid(axis='x', alpha=0.3)
            plt.tight_layout()
            chart_path = f"outputs/bems_escalations_{datetime.now(timezone.utc).strftime('%Y%m%d_%H%M%SZ')}.png"
            plt.savefig(chart_path, dpi=300, bbox_inches='tight')
            _r13_close_fig(fig)
            chart_paths.append(chart_path)

        # Chart 5: Feature Request Volume by Customer
        if feature_requests.get('customer_examples'):
            fig, ax = plt.subplots(figsize=(12, 8))
            # Round 10 / Phase 8.2: add a stable secondary sort on
            # ``customer_name`` (case-insensitive) so two customers with
            # the same ``request_count`` always render in the same
            # order across rebuilds.  The previous sort dropped to
            # arbitrary input order on ties, which produced spurious
            # "the bar chart changed" diffs between consecutive runs
            # on the same dataset.
            # Round 11 / Phase 8.3: count the eligible customers
            # before truncating to the top 10 so the title can
            # disclose how many bars were dropped.
            _fr_eligible = [c for c in feature_requests['customer_examples'] if c.get('request_count', 0) > 0]
            _fr_total_customers = len(_fr_eligible)
            examples = sorted(
                _fr_eligible,
                key=lambda row: (
                    -int(row.get('request_count', 0) or 0),
                    str(row.get('customer_name', '')).lower(),
                ),
            )[:10]
            if examples:
                customer_names = [c['customer_name'] for c in examples]
                request_counts = [c.get('request_count', 0) for c in examples]
                bars = ax.barh(range(len(customer_names)), request_counts, color='#1f77b4')
                if _fr_total_customers > len(examples):
                    _fr_more = _fr_total_customers - len(examples)
                    ax.set_title(
                        f'Feature Requests by Customer (Top {len(examples)} of {_fr_total_customers}; +{_fr_more} more)',
                        fontsize=14, fontweight='bold', pad=15,
                    )
                else:
                    ax.set_title(
                        f'Feature Requests by Customer (Top {len(examples)})',
                        fontsize=14, fontweight='bold', pad=15,
                    )
                ax.set_xlabel('Number of Requests', fontsize=12, fontweight='bold')
                ax.set_ylabel('Customer', fontsize=12, fontweight='bold')
                for bar, req_count in zip(bars, request_counts):
                    ax.text(
                        bar.get_width() + 0.1,
                        bar.get_y() + bar.get_height() / 2.0,
                        f'{int(req_count)}',
                        ha='left',
                        va='center',
                        fontweight='bold',
                        fontsize=9,
                    )
                ax.set_yticks(range(len(customer_names)))
                # Round 13 / Phase 8.6: truncate the display labels so
                # the chart embedded at Inches(6.5) in Word does not
                # clip 30+ character customer names; full names are
                # cached on the axes so the alt-text helper can surface
                # them later.
                _r13_disp, _r13_full = _r13_truncate_chart_labels(customer_names)
                ax.set_yticklabels(_r13_disp, fontsize=10)
                try:
                    ax._r13_full_labels = _r13_full
                    ax._r13_value_labels = [f'{int(v)} requests' for v in request_counts]
                except Exception:
                    pass
                ax.invert_yaxis()
                ax.grid(axis='x', alpha=0.3)
                plt.tight_layout()
                chart_path = f"outputs/feature_request_volume_{datetime.now(timezone.utc).strftime('%Y%m%d_%H%M%SZ')}.png"
                plt.savefig(chart_path, dpi=300, bbox_inches='tight')
                _r13_close_fig(fig)
                chart_paths.append(chart_path)

    except ImportError:
        logger.warning("[[WARNING]] Matplotlib not available - charts will be skipped")
    except Exception as e:
        logger.warning("[[WARNING]] Chart generation skipped: %s", e)

    return chart_paths


def create_renewal_charts(customer_ab: pd.DataFrame, customer_csone: pd.DataFrame, 
                          renewal_analysis: Dict, ext_incidents: List[Dict] = None,
                          days: int = 90) -> List[str]:
    """Create renewal-specific charts and visualizations"""
    chart_paths = []
    
    try:
        import matplotlib
        matplotlib.use('Agg')  # Use non-interactive backend for server
        import matplotlib.pyplot as plt
        import numpy as np
        from datetime import datetime, timedelta
        
        # Set style for executive reports
        try:
            plt.style.use('seaborn-v0_8-whitegrid')
        except Exception:
            try:
                plt.style.use('seaborn-whitegrid')
            except Exception as _e:
                logger.debug("matplotlib seaborn style unavailable, using default: %s", _e)
        
        plt.rcParams['figure.facecolor'] = 'white'
        plt.rcParams['axes.facecolor'] = 'white'
        plt.rcParams['font.size'] = 10
        plt.rcParams['axes.titlesize'] = 12
        plt.rcParams['axes.labelsize'] = 10
        
        # Chart 1: Renewal Risk Score Visualization (Gauge/Donut Chart)
        risk_score = renewal_analysis.get('renewal_risk_score', 0)
        risk_category = renewal_analysis.get('renewal_risk_category', 'UNKNOWN')
        
        fig, ax = plt.subplots(figsize=(10, 8))
        
        # Create donut chart for risk score.
        # Wedge color uses the canonical thresholds from
        # ``risk_scoring.RISK_BAND_THRESHOLDS`` so the color and the
        # textual band ("CRITICAL"/"HIGH"/"MEDIUM"/"LOW"/"HEALTHY") can
        # never disagree (the previous inline 70/50/30 cutoffs did).
        from risk_scoring import RISK_BAND_THRESHOLDS as _RBT
        # Round 12 / Phase 5.1: previously the LOW band wedge was
        # hard-coded to ``#fff176`` (a light-yellow) while the
        # downstream renewal panels (#2 risk distribution, #4 risk
        # heatmap) and the canonical ``RISK_BAND_COLORS["LOW"]``
        # constant in ``canonical_metrics`` already render LOW as
        # ``#2ca02c`` (green).  The same band therefore appeared as
        # two different colors inside the same Word document, which
        # both broke the visual legend and made the donut suggest a
        # higher risk than the panels showed.  Resolve every wedge
        # color from the canonical palette so all four panels agree.
        try:
            from canonical_metrics import (
                RISK_BAND_COLORS as _R12_RBC,
                RISK_BAND_COLOR_DEFAULT as _R12_RBC_DEFAULT,
            )
        except Exception:
            _R12_RBC = {
                "CRITICAL": "#d62728",
                "HIGH": "#ff7f0e",
                "MEDIUM": "#ffd700",
                "LOW": "#2ca02c",
                "HEALTHY": "#28B463",
            }
            _R12_RBC_DEFAULT = "#1f77b4"
        sizes = [risk_score, 100 - risk_score]
        if risk_score >= _RBT["CRITICAL"]:
            _wedge_color = _R12_RBC.get("CRITICAL", _R12_RBC_DEFAULT)
        elif risk_score >= _RBT["HIGH"]:
            _wedge_color = _R12_RBC.get("HIGH", _R12_RBC_DEFAULT)
        elif risk_score >= _RBT["MEDIUM"]:
            _wedge_color = _R12_RBC.get("MEDIUM", _R12_RBC_DEFAULT)
        elif risk_score >= _RBT["LOW"]:
            _wedge_color = _R12_RBC.get("LOW", _R12_RBC_DEFAULT)
        else:
            _wedge_color = _R12_RBC.get("HEALTHY", _R12_RBC_DEFAULT)
        colors = [_wedge_color, '#f0f0f0']
        
        wedges, texts, autotexts = ax.pie(sizes, labels=['Risk Score', 'Remaining'], 
                                          autopct='', colors=colors, startangle=90,
                                          pctdistance=0.85, labeldistance=1.1)
        # Round 13 / Phase 8.1: enforce 1:1 aspect on the renewal-risk
        # gauge pie so the wedge area is proportional to value.
        try:
            ax.set_aspect('equal')
        except Exception:
            pass
        
        # Round 10 / Phase 1.5: render the renewal-risk score with 1 decimal
        # to match the DOCX renewal section which uses
        # ``round(float(risk_score_raw), 1)``. ``int()`` previously truncated
        # 73.7 to "73", so the gauge and the textual "Renewal Risk Score:
        # 73.7/100" disagreed for the same customer.
        ax.text(0, 0, f'{float(risk_score):.1f}/100\n{risk_category}',
                ha='center', va='center', fontsize=24, fontweight='bold',
                color=colors[0])
        
        ax.set_title('Renewal Risk Score\n(Visual Indicator)', fontsize=16, fontweight='bold', pad=20)
        plt.tight_layout()
        chart_path = f"outputs/renewal_risk_score_{datetime.now(timezone.utc).strftime('%Y%m%d_%H%M%SZ')}.png"
        plt.savefig(chart_path, dpi=300, bbox_inches='tight')
        _r13_close_fig(fig)
        chart_paths.append(chart_path)
        
        # Chart 2: Support Cases Trend Over Time (if CSOne data available)
        if not customer_csone.empty and 'Date/Time Opened' in customer_csone.columns:
            fig, ax = plt.subplots(figsize=(12, 6))
            
            # Round 3 / Phase 1.2: do all parsing/filtering on a local
            # ``work`` copy so we never mutate the caller's
            # customer_csone. Previously the ``pd.to_datetime`` write
            # below rewrote the caller's column dtype in place, then
            # the ``dropna`` rebound only the local name -- so the
            # caller kept rows with NaT dates against a converted
            # dtype, which was easy to misread as the chart's
            # filtered series in any later code path.
            #
            # Round 6 / Phase 1.1: previously the trend chart also did
            # ``customer_csone = work`` here, which rebound the *function-
            # local* name to the date-trimmed subset.  Subsequent panels
            # (severity pie, multi-panel dashboard) then built off the
            # trimmed series while the headline ``support_cases_count``
            # in ``_calculate_simple_renewal_risk`` was computed on the
            # full frame, so the dashboard could disagree with the top
            # tile.  Keep ``customer_csone`` pointing at the original
            # frame and use the local ``work`` only for this chart.
            work = customer_csone.copy()
            _total_before_dt_filter = len(work)
            work['Date/Time Opened'] = pd.to_datetime(
                work['Date/Time Opened'], errors='coerce'
            )
            work = work.dropna(subset=['Date/Time Opened'])
            _dropped_no_date = _total_before_dt_filter - len(work)

            if len(work) > 0:
                # Group by week (use local ``work`` so caller's frame is
                # untouched and downstream panels still see all rows).
                work['Week'] = work['Date/Time Opened'].dt.to_period('W')
                weekly_cases = work.groupby('Week').size()
                
                if len(weekly_cases) > 0:
                    weeks = [str(period) for period in weekly_cases.index]
                    case_counts = weekly_cases.values
                    
                    # Round 13 / Phase 8.4: previously this weekly bar
                    # chart applied an arbitrary
                    # ``> 5 -> red, > 2 -> orange, else green``
                    # threshold and re-used the canonical RISK band
                    # palette to colour the bars.  That misleads the
                    # reader: the canonical risk palette is reserved
                    # for risk-band data (CRITICAL/HIGH/MEDIUM/LOW),
                    # and "5 cases in a week" is not a canonical
                    # risk threshold.  The bar's *height* already
                    # encodes weekly volume, so use a single neutral
                    # data-viz blue (matplotlib category-0 ``#1f77b4``)
                    # to remove the false risk encoding.  Future
                    # callers that genuinely need a risk overlay can
                    # add a separate axis or annotation.
                    colors = ['#1f77b4'] * len(case_counts)
                    
                    bars = ax.bar(weeks, case_counts, color=colors)
                    _disclosure = (
                        f' • {_dropped_no_date} case(s) without a valid open date are excluded'
                        if _dropped_no_date > 0 else ''
                    )
                    ax.set_title(
                        'Support Cases Trend Over Time\n(Last {} Days{})'.format(days, _disclosure),
                        fontsize=14, fontweight='bold'
                    )
                    ax.set_ylabel('Number of Cases', fontsize=12, fontweight='bold')
                    ax.set_xlabel('Week', fontsize=12, fontweight='bold')
                    
                    # Add value labels
                    for bar, value in zip(bars, case_counts):
                        height = bar.get_height()
                        ax.text(bar.get_x() + bar.get_width()/2., height + height*0.01,
                                f'{int(value)}', ha='center', va='bottom', fontweight='bold', fontsize=9)
                    
                    plt.xticks(rotation=45, ha='right')
                    plt.tight_layout()
                    chart_path = f"outputs/renewal_support_trend_{datetime.now(timezone.utc).strftime('%Y%m%d_%H%M%SZ')}.png"
                    plt.savefig(chart_path, dpi=300, bbox_inches='tight')
                    _r13_close_fig(fig)
                    chart_paths.append(chart_path)
        
        # Chart 3: Service Incidents Timeline (if incidents available)
        if ext_incidents and len(ext_incidents) > 0:
            fig, ax = plt.subplots(figsize=(12, 6))
            
            # Parse incident dates
            incident_dates = []
            incident_statuses = []
            for inc in ext_incidents:
                if inc.get('published'):
                    try:
                        # Round 11 / Phase 8.8: parse with utc=True so
                        # mixed-timezone "published" strings are
                        # normalized to a single timezone *before* we
                        # bucket into weekly periods.  Without this the
                        # same UTC instant could land in different
                        # ISO weeks depending on the source TZ offset
                        # and shift incident counts between buckets.
                        date = pd.to_datetime(inc.get('published', ''), errors='coerce', utc=True)
                        if pd.notna(date):
                            incident_dates.append(date)
                            status = inc.get('status', 'Unknown').lower()
                            incident_statuses.append(status)
                    except Exception as _e:
                        logger.debug("incident date parse skipped: %s", _e)
            
            if incident_dates:
                # Group by week
                incident_df = pd.DataFrame({'date': incident_dates, 'status': incident_statuses})
                # Round 11 / Phase 8.8: drop tz before to_period because
                # PeriodIndex does not retain tz info; we already
                # normalized to UTC above so the calendar week is
                # computed against a single anchor.
                try:
                    _wseries = incident_df['date'].dt.tz_convert('UTC').dt.tz_localize(None)
                except Exception:
                    _wseries = incident_df['date']
                incident_df['week'] = _wseries.dt.to_period('W')
                weekly_incidents = incident_df.groupby('week').size()
                
                if len(weekly_incidents) > 0:
                    weeks = [str(period) for period in weekly_incidents.index]
                    incident_counts = weekly_incidents.values
                    
                    # Color based on high-impact incidents.
                    # Round 6 / Phase 1.5: route the per-week count
                    # through the shared definition (active investigation
                    # only) so this chart and the renewal Word table
                    # agree on what "high-impact" means.
                    # Round 11 / Phase 2.3: build per-row dicts so the
                    # shared ``_is_high_impact_incident`` helper sees
                    # both ``status`` and ``impact_level`` (the chart
                    # used to look only at status, which understated
                    # high-impact weeks relative to the helper).
                    _impact_col = 'impact_level' if 'impact_level' in incident_df.columns else None
                    colors = []
                    for week in weekly_incidents.index:
                        week_incidents = incident_df[incident_df['week'] == week]
                        try:
                            _records = []
                            for _, _row in week_incidents.iterrows():
                                _records.append({
                                    'status': _row.get('status', ''),
                                    'impact_level': (
                                        _row.get(_impact_col, '') if _impact_col else ''
                                    ),
                                })
                            high_impact = _count_high_impact_incidents(_records)
                        except Exception:
                            high_impact = 0
                        colors.append('#d62728' if high_impact > 0 else '#ff7f0e' if len(week_incidents) > 2 else '#2ca02c')
                    
                    bars = ax.bar(weeks, incident_counts, color=colors)
                    # Round 3: title now describes status-based coloring
                    # honestly. The previous "High Impact" label was
                    # misleading because the red bars are picked when
                    # at least one incident is in an *active investigation*
                    # status (investigating / identified / monitoring),
                    # not from any actual impact field.
                    ax.set_title(
                        'Service Incidents Timeline (status.webex.com)\n'
                        '(Red = ≥1 active investigation, Orange = >2 incidents/week, Green = quiet week)',
                        fontsize=14, fontweight='bold'
                    )
                    ax.set_ylabel('Number of Incidents', fontsize=12, fontweight='bold')
                    ax.set_xlabel('Week', fontsize=12, fontweight='bold')
                    
                    # Add value labels
                    for bar, value in zip(bars, incident_counts):
                        height = bar.get_height()
                        ax.text(bar.get_x() + bar.get_width()/2., height + height*0.01,
                                f'{int(value)}', ha='center', va='bottom', fontweight='bold', fontsize=9)
                    
                    plt.xticks(rotation=45, ha='right')
                    plt.tight_layout()
                    chart_path = f"outputs/renewal_incidents_timeline_{datetime.now(timezone.utc).strftime('%Y%m%d_%H%M%SZ')}.png"
                    plt.savefig(chart_path, dpi=300, bbox_inches='tight')
                    _r13_close_fig(fig)
                    chart_paths.append(chart_path)
        
        # Chart 4: Renewal Health Dashboard (Multi-panel)
        fig, ((ax1, ax2), (ax3, ax4)) = plt.subplots(2, 2, figsize=(16, 12))
        fig.suptitle('Renewal Health Dashboard - Comprehensive View', 
                     fontsize=16, fontweight='bold', y=0.995)
        
        # Panel 1: Key Metrics Summary.
        # Round 10 / Phase 8.1: drive the "Support Cases" and "Service
        # Incidents" headline counts from the *same* series the
        # accompanying time-series panels plot (``work`` after dropna
        # on ``Date/Time Opened`` for cases, ``incident_dates`` after
        # parseable-date filter for incidents).  Otherwise the same
        # figure can show "Service Incidents: 47" next to a bar chart
        # that visibly sums to 32 because rows without parseable
        # ``published`` dates are silently excluded from the bars but
        # not from the headline ``len(ext_incidents)`` / raw
        # ``support_cases_count``.
        try:
            # Round 11 / Phase 4.3: fall back to ``support_cases_count``
            # whenever ``work`` is missing OR has zero rows after the
            # date-based dropna.  Without this fallback the headline
            # number went to 0 even when the renewal analysis carried
            # a non-zero raw case count (e.g. all rows had blank
            # ``Date/Time Opened``), which made the dashboard look
            # like there were "no support cases" when there really
            # were just no dated ones.
            _scc_total = int(renewal_analysis.get('support_cases_count', 0) or 0)
            if 'work' in locals() and work is not None:
                _work_len = int(len(work))
                _panel1_cases = _work_len if _work_len > 0 else _scc_total
            else:
                _panel1_cases = _scc_total
        except Exception:
            _panel1_cases = int(renewal_analysis.get('support_cases_count', 0) or 0)
        try:
            _panel1_incidents = (
                int(len(incident_dates)) if 'incident_dates' in locals() and incident_dates is not None
                else (int(len(ext_incidents)) if ext_incidents else 0)
            )
        except Exception:
            _panel1_incidents = int(len(ext_incidents)) if ext_incidents else 0
        metrics = {
            'Support Cases': _panel1_cases,
            'Adoption Barriers': renewal_analysis.get('adoption_barriers_count', 0),
            'BEMS Escalations': renewal_analysis.get('bems_escalations_count', 0),
            'Service Incidents': _panel1_incidents,
        }
        
        # Round 12 / Phase 8.3: previously these four bars (Support
        # Cases, Adoption Barriers, BEMS Escalations, Service
        # Incidents) were colored with the canonical risk ramp
        # ``['#d62728', '#ff7f0e', '#ffd700', '#2ca02c']`` -- exactly
        # the CRITICAL/HIGH/MEDIUM/LOW palette every other risk
        # chart in the report uses.  Because the four counts are
        # mutually incomparable units (a barrier is not "less risky
        # than" a TAC case), the ordinal red->green ramp implied a
        # risk story that simply does not exist; readers parsed
        # "Support Cases: red" as "Support Cases are critical
        # risk".  Switch to a single-hue Cisco-blue magnitude
        # ramp (darker = larger value visually) that cannot be
        # mistaken for the risk-band palette.
        ax1.barh(list(metrics.keys()), list(metrics.values()),
                 color=['#0B3D67', '#1B6BA0', '#3899D1', '#7CC2EA'])
        ax1.set_title('Key Metrics Summary', fontweight='bold')
        ax1.set_xlabel('Count', fontweight='bold')
        for i, (key, value) in enumerate(metrics.items()):
            ax1.text(value + 0.5, i, f'{int(value)}', va='center', fontweight='bold')
        
        # Panel 2: Risk Score Gauge (out of 100)
        # Round 4: this pie historically rendered ``[risk_score, 100 - risk_score]``
        # under a "Risk Category" title which suggested a categorical
        # breakdown.  Retitle as a score gauge so the visual matches
        # the underlying numbers (band label is shown as the slice
        # caption, score is the headline).
        risk_cat = risk_category
        # Round 11 / Phase 5.1: import the shared palette so the
        # dashboard, Word, and matplotlib outputs all paint the
        # same color for the same band.  Falls back gracefully if
        # canonical_metrics is missing the constant for any reason
        # so we don't break older builds.
        try:
            from canonical_metrics import RISK_BAND_COLORS as _R11_RISK_BAND_COLORS, RISK_BAND_COLOR_DEFAULT as _R11_RISK_DEFAULT
            risk_colors = dict(_R11_RISK_BAND_COLORS)
            _risk_default_color = _R11_RISK_DEFAULT
        except Exception:
            risk_colors = {'CRITICAL': '#d62728', 'HIGH': '#ff7f0e', 'MEDIUM': '#ffd700', 'LOW': '#2ca02c', 'HEALTHY': '#28B463', 'UNKNOWN': '#7f7f7f'}
            _risk_default_color = '#1f77b4'
        # Round 11 / Phase 8.1: panels 1 and 4 render the risk score
        # to one decimal place ("82.5/100") while panel 2 truncated
        # to ``int`` and lost the same precision.  Format consistently.
        # Round 11 / Phase 8.4: shared autopct.
        ax2.pie([risk_score, 100-risk_score],
                labels=[f'{risk_cat} ({float(risk_score):.1f}/100)', 'Remaining'],
                autopct=_r10_autopct,
                colors=[risk_colors.get(risk_cat, _risk_default_color), '#f0f0f0'],
                startangle=90)
        # Round 13 / Phase 8.1: enforce 1:1 aspect on the renewal-risk
        # gauge pie (panel 2 of the 2x2 portfolio chart) so the wedge
        # area is proportional to value and does not look distorted
        # when the surrounding ``plt.subplot(2, 2, 2)`` cell is not
        # square.
        try:
            ax2.set_aspect('equal')
        except Exception:
            pass
        ax2.set_title('Renewal Risk Score (out of 100)', fontweight='bold')
        
        # Panel 3: Case Severity Distribution (if CSOne data available).
        # Round 3 hardening: collapse all P1/1/Critical-style synonyms via
        # ``case_priority_norm`` so the pie matches the executive severity
        # pie and ``cm.count_p1/p2/p3/p4`` to the row.
        _renewal_pie_built = False
        if not customer_csone.empty:
            try:
                _renewal_csone_norm = add_case_lifecycle_fields(customer_csone)
            except Exception:
                _renewal_csone_norm = customer_csone
            if 'case_priority_norm' in _renewal_csone_norm.columns:
                _sev_series = (
                    _renewal_csone_norm['case_priority_norm'].fillna('Unknown').astype(str)
                )
                _ordered = ['P1', 'P2', 'P3', 'P4', 'Unknown']
                _raw = _sev_series.value_counts()
                _slices = [(k, int(_raw.get(k, 0))) for k in _ordered if int(_raw.get(k, 0)) > 0]
                if _slices:
                    # Round 11 / Phase 5.3: same shared palette as
                    # the executive severity pie above so the two
                    # cannot drift -- the previous "#9aa0a6" gray
                    # for Unknown disagreed by one digit with
                    # "#9e9e9e" elsewhere.
                    color_map = SEVERITY_COLORS
                    labels = [f'{k} ({v})' for k, v in _slices]
                    sizes = [v for _, v in _slices]
                    colors = [color_map.get(k, SEVERITY_COLOR_DEFAULT) for k, _ in _slices]
                    # Round 11 / Phase 8.4: shared _r10_autopct for parity.
                    ax3.pie(sizes, labels=labels, autopct=_r10_autopct, colors=colors, startangle=90)
                    # Round 13 / Phase 8.1: 1:1 aspect on panel 3
                    # (case-severity pie) so wedge area is
                    # proportional to value.
                    try:
                        ax3.set_aspect('equal')
                    except Exception:
                        pass
                    ax3.set_title('Case Severity Distribution', fontweight='bold')
                    _renewal_pie_built = True
        if not _renewal_pie_built:
            ax3.text(0.5, 0.5, 'No Case Data Available', ha='center', va='center',
                     transform=ax3.transAxes, fontsize=12)
            ax3.set_title('Case Severity Distribution', fontweight='bold')
        
        # Panel 4: Renewal Risk Score Gauge
        ax4.text(0.5, 0.7, 'RENEWAL RISK SCORE', ha='center', va='center',
                 transform=ax4.transAxes, fontsize=14, fontweight='bold')
        # Round 10 / Phase 1.5: 1 decimal to match DOCX (see gauge above).
        ax4.text(0.5, 0.5, f'{float(risk_score):.1f}/100', ha='center', va='center',
                 transform=ax4.transAxes, fontsize=36, fontweight='bold',
                 color=risk_colors.get(risk_cat, _risk_default_color))
        ax4.text(0.5, 0.3, risk_cat, ha='center', va='center',
                 transform=ax4.transAxes, fontsize=16, fontweight='bold',
                 color=risk_colors.get(risk_cat, _risk_default_color))
        ax4.axis('off')
        
        plt.tight_layout()
        chart_path = f"outputs/renewal_health_dashboard_{datetime.now(timezone.utc).strftime('%Y%m%d_%H%M%SZ')}.png"
        plt.savefig(chart_path, dpi=300, bbox_inches='tight')
        _r13_close_fig(fig)
        chart_paths.append(chart_path)
        
        logger.info(f"[[RENEWAL_CHARTS]] Generated {len(chart_paths)} renewal charts")
        return chart_paths
    
    except ImportError:
        logger.warning("[[WARNING]] Matplotlib not available - renewal charts will be skipped")
    except Exception as e:
        logger.error(f"[[ERROR]] Renewal chart generation failed: {e}")
        import traceback
        logger.error(f"[[ERROR]] Traceback: {traceback.format_exc()}")
    
    return chart_paths


def enrich_csone_with_arr(csone_df: pd.DataFrame, arr_data: pd.DataFrame) -> pd.DataFrame:
    """
    Enrich CSOne data with ARR information from Snowflake, or add placeholder ARR estimates
    """
    if csone_df is None or csone_df.empty:
        return csone_df if csone_df is not None else pd.DataFrame()
    
    # Create a copy to avoid modifying original
    enriched_df = csone_df.copy()
    
    try:
        # If we have real ARR data from Snowflake, merge it
        if arr_data is not None and not arr_data.empty:
            # Try to match on customer name (BU_NAME in ARR data; CSOne may have Customer Name or customer_name)
            cust_col = next((c for c in ['Customer Name', 'customer_name', 'BU_NAME', 'Customer'] if c in enriched_df.columns), None)
            if 'BU_NAME' in arr_data.columns and cust_col:
                # Create ARR lookup dictionary
                arr_lookup = {}
                for _, row in arr_data.iterrows():
                    customer = row.get('BU_NAME', '')
                    arr_value = row.get('ANNUAL_CONTRACT_VALUE', 0)
                    if customer and arr_value:
                        # Sum ARR if customer appears multiple times
                        arr_lookup[customer] = arr_lookup.get(customer, 0) + arr_value
                
                # Add ARR column to CSOne data.
                # Round 6 / Phase 1.6: every Customer_ARR-bearing
                # column MUST be accompanied by a per-row
                # ``ARR_Estimated`` boolean so downstream Excel/Word
                # exports can disclose synthetic vs real ARR.  A row
                # whose customer was not in the Snowflake ARR table is
                # filled to ``0`` here -- still a fabricated value, so
                # mark it ``True``.
                enriched_df['Customer_ARR'] = enriched_df[cust_col].map(arr_lookup).fillna(0)
                enriched_df['ARR_Estimated'] = ~enriched_df[cust_col].isin(arr_lookup.keys())
                # Round 12 / Phase 1.5: when the row was matched
                # against real Snowflake ARR, label its currency from
                # the source ``CURRENCY_CODE`` (per BU_NAME); otherwise
                # the row was filled to 0 with no real currency basis.
                try:
                    if 'CURRENCY_CODE' in arr_data.columns:
                        _ccy_lookup = (
                            arr_data[['BU_NAME', 'CURRENCY_CODE']]
                            .dropna(subset=['BU_NAME'])
                            .drop_duplicates(subset=['BU_NAME'])
                            .set_index('BU_NAME')['CURRENCY_CODE']
                            .to_dict()
                        )
                        enriched_df['ARR_Estimated_Currency'] = (
                            enriched_df[cust_col]
                            .map(_ccy_lookup)
                            .fillna('UNKNOWN')
                        )
                    else:
                        # No CURRENCY_CODE in source -> mark UNKNOWN
                        # rather than asserting USD.
                        enriched_df['ARR_Estimated_Currency'] = 'UNKNOWN'
                except Exception:
                    enriched_df['ARR_Estimated_Currency'] = 'UNKNOWN'
                logger.info(f"[[OK]] Enriched {len(enriched_df)} CSOne records with ARR data")
            else:
                # No match possible, add placeholder.
                # Round 6 / Phase 1.6: this is wholly synthetic.
                enriched_df['Customer_ARR'] = 0
                enriched_df['ARR_Estimated'] = True
                # Round 12 / Phase 1.5: stamp UNKNOWN here -- the
                # placeholder ARR (0) has no real currency basis so
                # we should not claim USD.
                enriched_df['ARR_Estimated_Currency'] = 'UNKNOWN'
                logger.warning(f"[[WARNING]] Could not match ARR data to customers - using placeholders")
        else:
            # No ARR data available - create estimated ARR based on case severity/volume
            # This is a rough estimate: More P1/P2 cases = larger customer
            logger.info(f"[[INFO]] No ARR data available - creating estimated ARR based on support activity")
            
            # Create estimated ARR tiers based on case characteristics.
            # Use canonical normalized priority so "1" / "Critical" / "P1" all
            # count toward the P1 tier consistently with dashboards.
            def estimate_arr(customer_name, customer_cases):
                case_count = len(customer_cases)
                # Round 3: route P1/P2 counts through canonical_metrics so
                # this estimator agrees byte-for-byte with the dashboards
                # / report-consistency validator. Avoids the in-line
                # ``(sev_series == 'P1').sum()`` drifting when the
                # normalization rules change.
                try:
                    p1_count = int(cm.count_p1(customer_cases))
                    p2_count = int(cm.count_p2(customer_cases))
                except Exception:
                    # Round 4: enrich the slice via add_case_lifecycle_fields
                    # FIRST so the fallback can still classify priorities
                    # when the raw column name drifted (e.g. SEVERITY,
                    # PRIORITY, P1_INDICATOR).  Without this the fallback
                    # silently went to zero P1/P2 counts, which made
                    # estimate_arr default everyone to $50K.
                    try:
                        _enriched_slice = add_case_lifecycle_fields(customer_cases)
                    except Exception:
                        _enriched_slice = customer_cases
                    if 'case_priority_norm' in _enriched_slice.columns:
                        sev_series = _enriched_slice['case_priority_norm'].astype(str)
                        p1_count = int((sev_series == 'P1').sum())
                        p2_count = int((sev_series == 'P2').sum())
                    else:
                        p1_count = 0
                        p2_count = 0

                # Rough estimation logic:
                # High case volume + high severity = enterprise customer (high ARR)
                if p1_count >= 2 or (p2_count >= 3 and case_count >= 5):
                    return 5000000  # $5M estimate
                elif p1_count >= 1 or (p2_count >= 2 and case_count >= 3):
                    return 1000000  # $1M estimate
                elif case_count >= 5:
                    return 500000   # $500K estimate
                elif case_count >= 2:
                    return 100000   # $100K estimate
                else:
                    return 50000    # $50K estimate

            # Enrich once so case_priority_norm is available before per-customer slicing.
            try:
                enriched_norm = add_case_lifecycle_fields(enriched_df)
            except Exception:
                enriched_norm = enriched_df

            # Calculate estimated ARR for each customer
            cust_col = next((c for c in ['Customer Name', 'customer_name', 'BU_NAME', 'Customer'] if c in enriched_norm.columns), None)
            if cust_col:
                arr_estimates = {}
                for customer in enriched_norm[cust_col].dropna().unique():
                    customer_cases = enriched_norm[enriched_norm[cust_col] == customer]
                    arr_estimates[customer] = estimate_arr(customer, customer_cases)
                
                enriched_df['Customer_ARR'] = enriched_df[cust_col].map(arr_estimates).fillna(50000)
                enriched_df['ARR_Estimated'] = True  # Flag that this is estimated
                # Round 12 / Phase 1.5: the estimator above produces
                # USD-shaped tier amounts (50K / 100K / 500K / 1M / 5M)
                # but the caller had no way to know whether to label
                # them as USD or as some other currency.  Stamp an
                # explicit ``ARR_Estimated_Currency='ASSUMED_USD'`` so
                # downstream renderers can either suppress the
                # ``$`` prefix or surface a "(estimated, USD-shaped)"
                # caveat next to the number.
                enriched_df['ARR_Estimated_Currency'] = 'ASSUMED_USD'
                logger.info(f"[[INFO]] Created estimated ARR for {len(arr_estimates)} customers")
            else:
                enriched_df['Customer_ARR'] = 50000  # Default estimate
                enriched_df['ARR_Estimated'] = True
                # Round 12 / Phase 1.5: same rationale as the
                # per-customer branch above.
                enriched_df['ARR_Estimated_Currency'] = 'ASSUMED_USD'
    
    except Exception as e:
        logger.error(f"[[ERROR]] Failed to enrich CSOne with ARR: {e}")
        enriched_df['Customer_ARR'] = 0
        enriched_df['ARR_Estimated'] = False
        # Round 12 / Phase 1.5: include the currency column on the
        # error path too so downstream code can rely on the schema.
        enriched_df['ARR_Estimated_Currency'] = 'UNKNOWN'
    
    return enriched_df

def analyze_feature_requests(csone_df: pd.DataFrame, arr_data: pd.DataFrame = None) -> Dict[str, Any]:
    """Analyze feature requests from CSOne data and link to customer ARR"""
    # Round 12 / Phase 1.1: detect multi-currency ARR up-front and
    # gate ``total_arr_impact`` so the headline summary is honest.
    # ``total_arr_impact`` summed ``ANNUAL_CONTRACT_VALUE`` across
    # customers without checking the underlying currency mix.  When
    # the portfolio contains a mix of (e.g.) USD/EUR/JPY rows that
    # produces a meaningless number that downstream renderers would
    # display with a ``$`` prefix.  Mirror the gate already used in
    # ``adoptiq_backend.py`` (lines 3173, 4050) by stamping
    # ``arr_impact_currencies`` / ``arr_impact_comparable`` on the
    # returned dict so the renderer can hide / annotate the figure.
    _is_multi_currency = False
    _currencies_present: List[str] = []
    try:
        if arr_data is not None and hasattr(arr_data, 'attrs'):
            _is_multi_currency = bool(arr_data.attrs.get('is_multi_currency'))
            _ccys = arr_data.attrs.get('currencies_present') or []
            _currencies_present = [str(c) for c in _ccys if c]
    except Exception:
        _is_multi_currency = False
        _currencies_present = []

    feature_requests = {
        'total_requests': 0,
        'top_features': [],
        'customer_examples': [],
        'total_arr_impact': 0,
        'arr_impact_comparable': not _is_multi_currency,
        'arr_impact_currencies': _currencies_present,
    }
    
    if csone_df is None or csone_df.empty:
        return feature_requests
    
    try:
        # Keywords that indicate feature requests
        feature_keywords = ['enhancement', 'feature request', 'rfr', 'new feature', 'add feature', 
                            'request for', 'would like', 'need feature', 'missing feature',
                            'enhancement request', 'feature enhancement', 'roadmap', 'future enhancement']
        
        # Find cases that are likely feature requests (use flexible column names for CSOne exports)
        from adoptiq_backend import LIKELY_TITLE_COLS, LIKELY_DESC_COLS
        title_col = next((c for c in LIKELY_TITLE_COLS if c in csone_df.columns), None)
        desc_col = next((c for c in LIKELY_DESC_COLS if c in csone_df.columns), None)
        csone_df['Title_Lower'] = (csone_df[title_col].astype(str).str.lower() if title_col
                                   else pd.Series([''] * len(csone_df), index=csone_df.index))
        csone_df['Desc_Lower'] = (csone_df[desc_col].astype(str).str.lower() if desc_col
                                  else pd.Series([''] * len(csone_df), index=csone_df.index))
        
        # Create boolean mask for feature requests
        is_feature_request = pd.Series([False] * len(csone_df), index=csone_df.index)
        for keyword in feature_keywords:
            is_feature_request |= csone_df['Title_Lower'].str.contains(keyword, na=False)
            is_feature_request |= csone_df['Desc_Lower'].str.contains(keyword, na=False)
        
        feature_request_cases = csone_df[is_feature_request].copy()
        feature_requests['total_requests'] = len(feature_request_cases)
        
        if len(feature_request_cases) > 0:
            # Group by customer to find which customers are requesting features
            feat_cust_col = next((c for c in ['Customer Name', 'customer_name', 'BU_NAME', 'Customer'] if c in feature_request_cases.columns), None)
            if feat_cust_col:
                customer_requests = feature_request_cases.groupby(feat_cust_col).size().sort_values(ascending=False)
                
                # FIXED: Get ALL requesting customers with ARR if available
                for customer, count in customer_requests.items():
                    customer_info = {
                        'customer_name': customer,
                        'request_count': int(count),
                        'arr': 0,
                        'sample_requests': []
                    }
                    
                    # Get ARR for this customer if available
                    if arr_data is not None and not arr_data.empty and 'BU_NAME' in arr_data.columns:
                        customer_arr = arr_data[arr_data['BU_NAME'] == customer]
                        if not customer_arr.empty and 'ANNUAL_CONTRACT_VALUE' in customer_arr.columns:
                            # Round 13 / Phase 1.4: dedupe ARR rows per
                            # account before summing.  Without this we
                            # multiplied ARR by the number of subscription
                            # lines on the account (one row per
                            # SUBSCRIPTION_ID), producing customer ARR
                            # totals that were 2x-10x reality.  Prefer
                            # ACCOUNT_ID_C; fall back to BU_NAME if the
                            # column is missing.
                            _arr_for_customer = customer_arr
                            try:
                                if 'ACCOUNT_ID_C' in customer_arr.columns:
                                    _arr_for_customer = customer_arr.drop_duplicates(
                                        subset=['ACCOUNT_ID_C']
                                    )
                                else:
                                    _arr_for_customer = customer_arr.drop_duplicates(
                                        subset=['BU_NAME']
                                    )
                            except Exception:
                                _arr_for_customer = customer_arr
                            customer_info['arr'] = float(
                                _arr_for_customer['ANNUAL_CONTRACT_VALUE'].sum()
                            )
                            # Round 12 / Phase 1.1: only accumulate the
                            # portfolio-wide ``total_arr_impact`` when ARR
                            # is single-currency.  When mixed, leave the
                            # headline at 0 and let renderers consult
                            # ``arr_impact_comparable`` to display "n/a".
                            if not _is_multi_currency:
                                feature_requests['total_arr_impact'] += customer_info['arr']
                    
                    # FIXED: Get ALL requests from this customer
                    customer_cases = feature_request_cases[feature_request_cases[feat_cust_col] == customer]
                    if 'Title' in customer_cases.columns:
                        sample_titles = customer_cases['Title'].dropna().tolist()
                        customer_info['sample_requests'] = sample_titles
                    
                    feature_requests['customer_examples'].append(customer_info)
            
            # Analyze most common feature themes (simple keyword frequency)
            all_text = ' '.join(feature_request_cases['Title_Lower'].fillna('') + ' ' + 
                                feature_request_cases['Desc_Lower'].fillna(''))
            
            # Common feature themes to look for
            feature_themes = {
                'integration': ['integration', 'integrate', 'api', 'sso', 'ldap', 'saml', 'oauth'],
                'reporting': ['report', 'reporting', 'analytics', 'dashboard', 'export', 'metrics'],
                'mobile': ['mobile', 'ios', 'android', 'app', 'tablet'],
                'security': ['security', 'encryption', 'compliance', 'audit', 'privacy'],
                'automation': ['automation', 'automate', 'automatic', 'workflow', 'provisioning'],
                'notifications': ['notification', 'alert', 'email', 'notify', 'reminder'],
                'customization': ['custom', 'customize', 'configuration', 'settings', 'branding'],
                'collaboration': ['share', 'sharing', 'collaborate', 'team', 'group']
            }
            
            theme_counts = {}
            for theme, keywords in feature_themes.items():
                count = sum(all_text.count(keyword) for keyword in keywords)
                if count > 0:
                    theme_counts[theme] = count
            
            # FIXED: Show ALL themes sorted by frequency
            sorted_themes = sorted(theme_counts.items(), key=lambda x: x[1], reverse=True)
            feature_requests['top_features'] = [(theme, count) for theme, count in sorted_themes]
        
    except Exception as e:
        logger.error(f"[[ERROR]] Feature request analysis failed: {e}")
        import traceback
        logger.error(f"[[ERROR]] Traceback: {traceback.format_exc()}")
    
    return feature_requests

def calculate_arr_impact_for_issues(ab_norm: pd.DataFrame, arr_data: pd.DataFrame) -> Dict[str, Any]:
    """Calculate combined ARR for customers experiencing specific issues"""
    # Round 12 / Phase 1.2: align this function's output contract with
    # ``adoptiq_backend._get_financial_metrics`` (and Round 11 /
    # Phase 1.x gates) so consumers know whether the headline
    # ``total_arr`` / per-category ``arr`` numbers are safe to render.
    # When the ARR frame spans multiple distinct currencies, we
    # zero out the unsafe headline and surface
    # ``is_multi_currency`` + ``totals_by_currency`` so callers can
    # render a "n/a (mixed currencies: USD, EUR, ...)" affordance
    # instead of a meaningless cross-currency sum.
    _empty_payload: Dict[str, Any] = {
        "total_arr": 0,
        "total_mrr": 0,
        "total_tcv": 0,
        "issue_breakdown": {},
        "top_issues": [],
        "customer_count": 0,
        "total_issues": 0,
        "is_multi_currency": False,
        "currencies_present": [],
        "totals_by_currency": {},
    }
    if ab_norm is None or arr_data is None:
        return dict(_empty_payload)
    if ab_norm.empty or arr_data.empty:
        return dict(_empty_payload)

    # Round 12 / Phase 1.2: detect multi-currency ARR up-front using
    # the attrs stamped by Snowflake normalization.
    _is_multi_currency = False
    _currencies_present: List[str] = []
    try:
        if hasattr(arr_data, 'attrs'):
            _is_multi_currency = bool(arr_data.attrs.get('is_multi_currency'))
            _ccys = arr_data.attrs.get('currencies_present') or []
            _currencies_present = [str(c) for c in _ccys if c]
    except Exception:
        _is_multi_currency = False
        _currencies_present = []
    
    try:
        # Check which ARR columns actually exist in the data
        arr_cols_to_merge = ['ACCOUNT_ID_C']
        if 'ANNUAL_CONTRACT_VALUE' in arr_data.columns:
            arr_cols_to_merge.append('ANNUAL_CONTRACT_VALUE')
        if 'MRR' in arr_data.columns:
            arr_cols_to_merge.append('MRR')
        if 'TCV' in arr_data.columns:
            arr_cols_to_merge.append('TCV')
        if 'BU_NAME' in arr_data.columns:
            arr_cols_to_merge.append('BU_NAME')
        
        # Round 6 / Phase 5.11: pre-deduplicate the ARR view on
        # ACCOUNT_ID_C and use ``validate='m:1'`` so the AB-level
        # metrics computed below cannot be silently inflated by
        # duplicate ARR rows for the same account (which would
        # double-count adoption-barrier rows in ARR by-issue
        # breakdowns).  Fall back to a plain merge with a logged
        # warning if validation fails so we don't crash a previously
        # working report just because upstream ARR has duplicates.
        #
        # Round 11 / Phase 1.2: ``drop_duplicates(subset=['ACCOUNT_ID_C'])``
        # silently keeps the FIRST row per account and discards every
        # additional subscription line item.  For accounts with
        # multiple subscriptions (the common case for Cisco enterprise
        # customers) that throws away real ARR.  Roll up
        # numeric monetary columns (ANNUAL_CONTRACT_VALUE / MRR / TCV)
        # with ``groupby(...).sum()`` so a customer with two
        # $50k subscriptions correctly contributes $100k of ARR; keep
        # ``BU_NAME`` as a label using ``first()``.
        try:
            _money_cols = [
                c for c in ('ANNUAL_CONTRACT_VALUE', 'MRR', 'TCV')
                if c in arr_cols_to_merge
            ]
            _label_cols = [
                c for c in ('BU_NAME',)
                if c in arr_cols_to_merge
            ]
            _arr_src = (
                arr_data[arr_cols_to_merge]
                .dropna(subset=['ACCOUNT_ID_C'])
            )
            if _money_cols or _label_cols:
                _agg_spec: Dict[str, str] = {}
                for _c in _money_cols:
                    _agg_spec[_c] = 'sum'
                for _c in _label_cols:
                    _agg_spec[_c] = 'first'
                _arr_view = (
                    _arr_src.groupby('ACCOUNT_ID_C', as_index=False, sort=False)
                    .agg(_agg_spec)
                )
            else:
                # Defensive: if neither money nor label columns are
                # present, fall back to the legacy dedupe so the
                # merge still validates.
                _arr_view = _arr_src.drop_duplicates(subset=['ACCOUNT_ID_C'])
            merged_data = ab_norm.merge(
                _arr_view,
                on='ACCOUNT_ID_C',
                how='left',
                validate='m:1',
            )
        except Exception as _ab_arr_merge_err:
            logger.warning(
                "AB+ARR m:1 merge validation failed (%s); falling back to "
                "plain left-merge but ARR-by-issue counts may be inflated.",
                _ab_arr_merge_err,
            )
            merged_data = ab_norm.merge(
                arr_data[arr_cols_to_merge],
                on='ACCOUNT_ID_C',
                how='left',
            )
    except Exception as e:
        logger.error(f"[[ERROR]] Error merging ARR data: {e}")
        return {"total_arr": 0, "issue_breakdown": {}, "top_issues": [], "customer_count": 0, "total_issues": 0}
    
    # Fill missing ARR values with 0 (only if columns exist)
    if 'ANNUAL_CONTRACT_VALUE' in merged_data.columns:
        merged_data['ANNUAL_CONTRACT_VALUE'] = merged_data['ANNUAL_CONTRACT_VALUE'].fillna(0)
    else:
        merged_data['ANNUAL_CONTRACT_VALUE'] = 0
    
    if 'MRR' in merged_data.columns:
        merged_data['MRR'] = merged_data['MRR'].fillna(0)
    else:
        merged_data['MRR'] = 0
    
    if 'TCV' in merged_data.columns:
        merged_data['TCV'] = merged_data['TCV'].fillna(0)
    else:
        merged_data['TCV'] = 0

    # Round 11 / Phase 1.1: ``merged_data`` is the AB-level frame
    # left-merged with one ARR row per account.  Summing
    # ``ANNUAL_CONTRACT_VALUE`` over EVERY barrier row therefore
    # double-counts an account's ARR once per barrier (an account
    # with $100k ARR and 5 open barriers contributed $500k).  Round 6
    # / Phase 5.11 made the merge ``m:1`` validated to prevent ARR
    # duplicates from inflating the count, but did NOT prevent the
    # AB row-multiplication itself.  Dedupe on ``ACCOUNT_ID_C``
    # before summing so ``total_arr`` / ``total_mrr`` / ``total_tcv``
    # really mean "ARR of customers experiencing >=1 issue."
    try:
        _per_account = merged_data.drop_duplicates(subset=['ACCOUNT_ID_C'])
        total_arr = float(_per_account['ANNUAL_CONTRACT_VALUE'].sum())
        total_mrr = float(_per_account['MRR'].sum())
        total_tcv = float(_per_account['TCV'].sum())
    except Exception as _per_acct_err:
        logger.warning(
            "Per-account ARR dedupe failed (%s); falling back to "
            "barrier-row sums which may be inflated.",
            _per_acct_err,
        )
        total_arr = float(merged_data['ANNUAL_CONTRACT_VALUE'].sum())
        total_mrr = float(merged_data['MRR'].sum())
        total_tcv = float(merged_data['TCV'].sum())

    # Group by issue type/category.
    # Round 11 / Phase 1.1: same dedupe rule applies inside each
    # category so per-category ARR is "ARR of distinct customers
    # who have at least one barrier in this category" rather than
    # "ARR x number of barriers in this category."
    issue_breakdown = {}
    if 'AB_CATEGORY_C' in merged_data.columns:
        for category in merged_data['AB_CATEGORY_C'].dropna().unique():
            category_data = merged_data[merged_data['AB_CATEGORY_C'] == category]
            try:
                _cat_per_account = category_data.drop_duplicates(subset=['ACCOUNT_ID_C'])
            except Exception:
                _cat_per_account = category_data
            issue_breakdown[category] = {
                'arr': float(_cat_per_account['ANNUAL_CONTRACT_VALUE'].sum()),
                'mrr': float(_cat_per_account['MRR'].sum()),
                'tcv': float(_cat_per_account['TCV'].sum()),
                'customer_count': int(category_data['ACCOUNT_ID_C'].nunique()),
                'issue_count': int(len(category_data)),
            }
    
    # FIXED: ALL issues by ARR impact
    top_issues = []
    if issue_breakdown:
        sorted_issues = sorted(issue_breakdown.items(), key=lambda x: x[1]['arr'], reverse=True)
        top_issues = sorted_issues  # All issues by ARR impact
    
    # Round 12 / Phase 1.2: build per-currency rollup so consumers can
    # render a comparable breakdown even when the unsafe single
    # headline is suppressed.  We re-merge ``CURRENCY_CODE`` from the
    # raw ``arr_data`` per ACCOUNT_ID_C to avoid double-counting the
    # AB row-multiplication.
    totals_by_currency: Dict[str, Dict[str, float]] = {}
    try:
        if 'CURRENCY_CODE' in arr_data.columns:
            _ccy_view = (
                arr_data[['ACCOUNT_ID_C', 'CURRENCY_CODE']]
                .dropna(subset=['ACCOUNT_ID_C'])
                .drop_duplicates(subset=['ACCOUNT_ID_C'])
            )
            _per_acct_with_ccy = (
                _per_account.merge(_ccy_view, on='ACCOUNT_ID_C', how='left')
            )
            for _ccy, _grp in _per_acct_with_ccy.groupby(
                _per_acct_with_ccy['CURRENCY_CODE'].fillna('UNKNOWN'),
                sort=True,
            ):
                totals_by_currency[str(_ccy)] = {
                    'total_arr': float(_grp['ANNUAL_CONTRACT_VALUE'].sum()),
                    'total_mrr': float(_grp['MRR'].sum()),
                    'total_tcv': float(_grp['TCV'].sum()),
                    'customer_count': int(_grp['ACCOUNT_ID_C'].nunique()),
                }
    except Exception as _ccy_err:
        logger.warning(
            "Per-currency ARR rollup failed (%s); leaving totals_by_currency empty.",
            _ccy_err,
        )

    # Round 12 / Phase 1.2: when ARR spans multiple currencies, the
    # naive cross-currency sums above are not comparable.  Zero the
    # headline so renderers do not display a misleading "$X" figure
    # and rely on ``totals_by_currency`` for the per-currency view.
    if _is_multi_currency:
        _safe_total_arr = 0.0
        _safe_total_mrr = 0.0
        _safe_total_tcv = 0.0
        _safe_breakdown: Dict[str, Any] = {}
        for _name, _row in issue_breakdown.items():
            _row_safe = dict(_row)
            _row_safe['arr'] = 0.0
            _row_safe['mrr'] = 0.0
            _row_safe['tcv'] = 0.0
            _safe_breakdown[_name] = _row_safe
        _safe_top_issues = [(n, _safe_breakdown[n]) for n, _ in top_issues if n in _safe_breakdown]
    else:
        _safe_total_arr = total_arr
        _safe_total_mrr = total_mrr
        _safe_total_tcv = total_tcv
        _safe_breakdown = issue_breakdown
        _safe_top_issues = top_issues

    return {
        "total_arr": _safe_total_arr,
        "total_mrr": _safe_total_mrr,
        "total_tcv": _safe_total_tcv,
        "issue_breakdown": _safe_breakdown,
        "top_issues": _safe_top_issues,
        "customer_count": merged_data['ACCOUNT_ID_C'].nunique(),
        "total_issues": len(merged_data),
        "is_multi_currency": _is_multi_currency,
        "currencies_present": _currencies_present,
        "totals_by_currency": totals_by_currency,
    }

def _create_enhanced_compact_report(base_path: str, manager: str, technology: str, days: int, 
                                    ai_insights: Dict, csone_df: pd.DataFrame, ab_norm: pd.DataFrame,
                                    arr_data: pd.DataFrame, arr_impact: Dict, 
                                    chart_paths: List[str], feature_requests: Dict,
                                    team_subs_df: pd.DataFrame = None,
                                    csconsole_action_plans: pd.DataFrame = None,
                                    csconsole_customer_pulse: pd.DataFrame = None,
                                    csconsole_success_priorities: pd.DataFrame = None,
                                    csconsole_adoption_barriers: pd.DataFrame = None) -> str:
    """Create an enhanced compact report with real data, tables, and charts using ALL data sources"""
    from docx import Document
    from docx.shared import Inches, Pt, RGBColor
    from docx.enum.text import WD_ALIGN_PARAGRAPH
    from datetime import datetime
    import os
    
    doc = Document()
    
    # Title
    # Round 6 / Phase 1.4: route through _safe_doc_text so a malformed
    # ``manager`` string can't produce illegal XML in the heading.
    title = doc.add_heading(_safe_doc_text(f'AdoptIQ Portfolio Analysis - {manager}'), 0)
    title.alignment = WD_ALIGN_PARAGRAPH.CENTER
    
    subtitle = doc.add_paragraph(f'{technology} - {days} Day Analysis')
    subtitle.alignment = WD_ALIGN_PARAGRAPH.CENTER
    if subtitle.runs:
        subtitle.runs[0].bold = True
    
    doc.add_paragraph()  # Spacing
    
    # Initialize variables outside if block to avoid scope issues
    total_customers = 0
    total_cases = 0
    p1_count = 0
    p2_count = 0
    bems_count = 0
    defect_count = 0
    vuln_count = 0
    customer_col = None
    severity_col = None
    bems_cases = pd.DataFrame()
    software_defects = {'total_defects': 0, 'total_cases_with_defects': 0, 'defect_by_customer': {}}
    psirt_vulns = {'total_vulnerabilities': 0, 'cve_ids': set(), 'psirt_advisories': set(), 'vulnerability_by_customer': {}}
    
    # CRITICAL FIX: Calculate customer count FIRST (before conditional check)
    # This ensures we show customer count even if CSOne is empty but we have customers from other sources
    # CRITICAL FIX: Use comprehensive function to get ALL customers from ALL available data sources
    # team_subs_df is PRIMARY source (unfiltered, contains all customers assigned to manager)
    # This ensures consistent customer counts across all report types
    all_customers_set = _get_all_customers_from_all_sources(
        ab_norm=ab_norm,
        csone_df=csone_df,
        team_subs_df=team_subs_df if team_subs_df is not None else pd.DataFrame(),
        csconsole_action_plans=csconsole_action_plans if csconsole_action_plans is not None else pd.DataFrame(),
        csconsole_customer_pulse=csconsole_customer_pulse if csconsole_customer_pulse is not None else pd.DataFrame(),
        csconsole_success_priorities=csconsole_success_priorities if csconsole_success_priorities is not None else pd.DataFrame(),
        csconsole_adoption_barriers=csconsole_adoption_barriers if csconsole_adoption_barriers is not None else pd.DataFrame()
    )
    total_customers = len(all_customers_set)
    logger.info(f"[[CUSTOMER_COUNT]] Total unique customers from all data sources: {total_customers}")
    logger.info(f"[[CUSTOMER_COUNT]] Team subscriptions (PRIMARY): {len(team_subs_df['BU_NAME'].unique()) if not team_subs_df.empty and 'BU_NAME' in team_subs_df.columns else 0} customers")
    
    # Extract software defects (BST/CSC IDs) and PSIRT vulnerabilities (do this even if CSOne is empty)
    software_defects = extract_software_defects(csone_df, ab_norm)
    psirt_vulns = extract_psirt_vulnerabilities(csone_df, ab_norm)
    defect_count = software_defects.get('total_defects', 0)
    vuln_count = psirt_vulns.get('total_vulnerabilities', 0)
    
    # Add Executive Dashboard with Key Metrics (inspired by McKinsey/BCG reports)
    # FIXED: Show dashboard if we have ANY customers (not just if CSOne is not empty)
    # This ensures customer count is always displayed even if there are no cases
    if total_customers > 0 or not csone_df.empty or not ab_norm.empty:
        doc.add_heading('At-a-Glance Dashboard', level=1)
        
        # Create metrics table (7 columns for comprehensive metrics including defects)
        metrics_table = doc.add_table(rows=2, cols=7)
        metrics_table.style = 'Light Grid Accent 1'
        
        # Calculate metrics - Debug CSOne columns first
        if not csone_df.empty:
            logger.info(f"[[DEBUG]] CSOne DataFrame columns: {list(csone_df.columns)}")
            logger.info(f"[[DEBUG]] CSOne DataFrame shape: {csone_df.shape}")
            logger.info(f"[[DEBUG]] CSOne DataFrame sample (first 3 rows): {csone_df.head(3).to_dict('records') if not csone_df.empty else 'EMPTY'}")
        total_cases = len(csone_df) if not csone_df.empty else 0
        
        # Try to detect a customer column for downstream BEMS-customer counting.
        # Round 3 hardening: do NOT gate P1/P2 counts on raw-severity-column
        # presence — ``cm.count_p1/p2`` already normalizes any of the known
        # raw columns (Severity / Priority / Case_Priority / case_priority_norm)
        # and returns 0 cleanly when none exist. The previous gate caused
        # silent zeros when the input was already normalized to
        # ``case_priority_norm`` but lacked the raw legacy columns.
        customer_col = None
        if not csone_df.empty:
            for col in ['Customer Name', 'customer_name', 'Customer', 'BU_NAME', 'Account Name']:
                if col in csone_df.columns:
                    customer_col = col
                    break

        if not csone_df.empty:
            p1_count = cm.count_p1(csone_df)
            p2_count = cm.count_p2(csone_df)
            logger.info(f"[[DEBUG]] Found {p1_count} P1 cases and {p2_count} P2 cases via canonical priority normalization")
        else:
            p1_count = 0
            p2_count = 0

        if not csone_df.empty:
            bems_cases, _legacy_bems_count = detect_bems_escalations(csone_df)
            bems_count = cm.count_bems(csone_df)
        else:
            bems_count = 0
            bems_cases = pd.DataFrame()
        
        # Header row - expanded to include software defects
        headers = ['Total Customers', 'Support Cases', 'Critical (P1)', 'High (P2)', 'BEMS Escalations', 'Software Defects', 'Security Vulnerabilities']
        for i, header in enumerate(headers):
            cell = metrics_table.rows[0].cells[i]
            cell.text = header
            for paragraph in cell.paragraphs:
                for run in paragraph.runs:
                    run.bold = True
                    run.font.size = Pt(11)
                paragraph.alignment = WD_ALIGN_PARAGRAPH.CENTER
        
        # Values row - expanded to include software defects and vulnerabilities
        values = [str(total_customers), str(total_cases), str(p1_count), str(p2_count), str(bems_count), str(defect_count), str(vuln_count)]
        colors = [
            None, 
            None, 
            RGBColor(192, 0, 0) if p1_count > 0 else None, 
            RGBColor(255, 140, 0) if p2_count > 0 else None, 
            RGBColor(139, 0, 0) if bems_count > 0 else None,
            RGBColor(200, 100, 0) if defect_count > 0 else None,
            RGBColor(255, 0, 0) if vuln_count > 0 else None
        ]
        
        for i, (value, color) in enumerate(zip(values, colors)):
            cell = metrics_table.rows[1].cells[i]
            cell.text = value
            for paragraph in cell.paragraphs:
                for run in paragraph.runs:
                    run.font.size = Pt(18)
                    run.bold = True
                    if color:
                        run.font.color.rgb = color
                paragraph.alignment = WD_ALIGN_PARAGRAPH.CENTER
        
        doc.add_paragraph()  # Spacing
    else:
        # Edge case: No customers and no data - show empty dashboard
        logger.warning(f"[[WARNING]] No customers found in any data source - dashboard will be minimal")
    
    doc.add_heading('Executive Summary', level=1)
    
    # Add Data-Driven Executive Overview (before AI narrative)
    # FIXED: Show overview if we have ANY data (customers, cases, or barriers)
    # Use the customer count already calculated above (don't recalculate) - ensures consistency
    if total_customers > 0 or not csone_df.empty or (ab_norm is not None and not ab_norm.empty):
        overview_para = doc.add_paragraph()
        overview_para.add_run('Portfolio Overview\n').bold = True
        if overview_para.runs:
            overview_para.runs[0].font.size = Pt(13)
        
        # Use the total_customers already calculated from unified function above (line 1846)
        # No need to recalculate - ensures consistency with dashboard
        total_cases = len(csone_df) if not csone_df.empty else 0
        
        overview_para.add_run(f'• Total Customers: {total_customers}\n')
        overview_para.add_run(f'• Total Support Cases: {total_cases}\n')

        # Round 3: derive P1/P2 directly from canonical helpers without
        # gating on raw column names; cm.count_p1/p2 already normalizes
        # whichever priority column is present.
        if not csone_df.empty:
            p1_count = cm.count_p1(csone_df)
            p2_count = cm.count_p2(csone_df)
            overview_para.add_run(f'• Critical Cases (P1): {p1_count}\n')
            overview_para.add_run(f'• High Priority Cases (P2): {p2_count}\n')

        bems_cases, _legacy_bems_count = detect_bems_escalations(csone_df)
        bems_count = cm.count_bems(csone_df)
        if bems_count > 0:
            bems_customers = bems_cases[customer_col].nunique() if customer_col and customer_col in bems_cases.columns else 0
            run = overview_para.add_run(f'• BEMS Escalations: {bems_count} cases across {bems_customers} customers\n')
            run.font.color.rgb = RGBColor(192, 0, 0)
            run.bold = True
        doc.add_paragraph()  # Spacing
    
    # Financial ARR sections were intentionally disabled and the dead block
    # was removed in the data-accuracy round 2 hardening to prevent silent
    # re-activation of severity-string matching that bypassed canonical
    # priority normalization.

    
    # Add AI-generated summary
    # Round 3 / Phase 2.4: also accept the nested
    # ``ai_insights["portfolio_summary"]["executive_summary"]`` shape
    # used by the portfolio Word path. Previously only the top-level
    # ``ai_insights["executive_summary"]`` key was honored, so a
    # successful portfolio LLM call shaped under ``portfolio_summary``
    # silently dropped the AI narrative from the comprehensive Word
    # report (tables/charts shipped fine, but no AI prose).
    summary_text = None
    if isinstance(ai_insights, dict):
        if isinstance(ai_insights.get('executive_summary'), str) and ai_insights['executive_summary'].strip():
            summary_text = ai_insights['executive_summary']
        else:
            _ps = ai_insights.get('portfolio_summary')
            if isinstance(_ps, dict) and isinstance(_ps.get('executive_summary'), str) and _ps['executive_summary'].strip():
                summary_text = _ps['executive_summary']
            elif isinstance(ai_insights.get('raw_response'), str) and ai_insights['raw_response'].strip():
                summary_text = ai_insights['raw_response']
    if summary_text:
        _parse_markdown_for_fallback(doc, summary_text)
    
    # Add Key Insights & Recommendations Section (Professional Executive Format)
    if not csone_df.empty:
        doc.add_heading('Key Insights & Strategic Recommendations', level=1)
        
        # Create insights based on actual data
        insights_para = doc.add_paragraph()
        insights_para.add_run('Critical Findings:\n').bold = True
        if insights_para.runs:
            insights_para.runs[0].font.size = Pt(13)
        
        # Calculate risk indicators.  Round 4: rename the support-load
        # denominator to ``csone_distinct_customers`` so it cannot
        # silently shadow the canonical ``total_customers`` defined
        # above (which spans ALL data sources, not just CSOne).  The
        # narrative now explicitly labels what the denominator means.
        if customer_col:
            csone_distinct_customers = csone_df[customer_col].nunique()
            avg_cases_per_customer = (
                total_cases / csone_distinct_customers if csone_distinct_customers > 0 else 0
            )

            if avg_cases_per_customer > 3:
                insights_para.add_run(
                    f'• HIGH SUPPORT LOAD: Average {avg_cases_per_customer:.1f} cases per customer with TAC cases '
                    f'(n={csone_distinct_customers}) indicates potential adoption challenges\n'
                )
            elif avg_cases_per_customer > 1.5:
                insights_para.add_run(
                    f'• MODERATE SUPPORT LOAD: Average {avg_cases_per_customer:.1f} cases per customer with TAC cases '
                    f'(n={csone_distinct_customers}) requires monitoring\n'
                )
            else:
                insights_para.add_run(
                    f'• NORMAL SUPPORT LOAD: Average {avg_cases_per_customer:.1f} cases per customer with TAC cases '
                    f'(n={csone_distinct_customers}) indicates healthy adoption\n'
                )
        
        # Round 3: drop the raw-column gate; p1_count/p2_count are
        # already derived canonically and are safe to render regardless
        # of which raw severity column happens to be present.
        if total_cases > 0:
            p1_pct = (p1_count / total_cases * 100) if total_cases > 0 else 0
            p2_pct = (p2_count / total_cases * 100) if total_cases > 0 else 0
            
            if p1_pct > 5:
                insights_para.add_run(f'• CRITICAL RISK: {p1_pct:.1f}% of cases are P1 - immediate attention required\n')
            elif p1_pct > 2:
                insights_para.add_run(f'• ELEVATED RISK: {p1_pct:.1f}% of cases are P1 - proactive intervention needed\n')
            
            if p2_pct > 20:
                insights_para.add_run(f'• HIGH PRIORITY VOLUME: {p2_pct:.1f}% of cases are P2 - resource allocation review needed\n')
        
        if bems_count > 0:
            bems_pct = (bems_count / total_cases * 100) if total_cases > 0 else 0
            insights_para.add_run(f'• ENGINEERING ESCALATIONS: {bems_pct:.1f}% of cases require engineering intervention - product stability concerns\n')
        
        if defect_count > 0:
            cases_with_defects = software_defects.get("total_cases_with_defects", 0)
            insights_para.add_run(f'• SOFTWARE DEFECTS: {defect_count} unique BST/CSC defects identified across {cases_with_defects} cases - product quality impact\n')
        
        if vuln_count > 0:
            insights_para.add_run(f'• SECURITY VULNERABILITIES: {vuln_count} security vulnerabilities (CVEs/PSIRT) identified - security risk assessment needed\n')
        
        doc.add_paragraph()
        
        # Strategic Recommendations
        recommendations_para = doc.add_paragraph()
        recommendations_para.add_run('Strategic Recommendations:\n').bold = True
        if recommendations_para.runs:
            recommendations_para.runs[0].font.size = Pt(13)
        
        if bems_count > 0:
            recommendations_para.add_run('• IMMEDIATE: Address engineering escalations to prevent customer churn\n')
        if defect_count > 0:
            recommendations_para.add_run('• CRITICAL: Track and resolve software defects (BST/CSC) affecting customer experience\n')
        if vuln_count > 0:
            recommendations_para.add_run('• SECURITY: Address security vulnerabilities (CVEs/PSIRT) to protect customer environments\n')
        if p1_count > 0:
            recommendations_para.add_run('• URGENT: Implement P1 case response protocol and root cause analysis\n')
        if customer_col and total_customers > 0:
            high_volume_customers = csone_df[customer_col].value_counts()
            if len(high_volume_customers[high_volume_customers > 5]) > 0:
                recommendations_para.add_run('• STRATEGIC: Deploy dedicated success managers for high-volume customers\n')
        
        recommendations_para.add_run('• PROACTIVE: Implement predictive analytics to identify at-risk customers early\n')
        recommendations_para.add_run('• SYSTEMATIC: Establish regular executive reviews of customer health metrics\n')
        
        doc.add_paragraph()
    
    doc.add_page_break()
    
    # === REAL DATA TABLES ===
    doc.add_heading('Portfolio Data & Analysis', level=1)
    
    # FIXED: Show ALL customers by case volume
    if not csone_df.empty and customer_col:
        doc.add_heading('All Customers by Support Cases', level=2)
        
        customer_cases = csone_df[customer_col].value_counts()  # Show ALL customers
        # Round 6 / Phase 1.21: drive ``has_arr`` from data presence
        # instead of hardcoding ``False`` (which permanently disabled
        # the Estimated ARR column even when ``Customer_ARR`` was
        # available).  ``ARR_Estimated`` flag (Phase 1.6) tells us
        # whether the value is synthetic; we surface that in the column
        # header so the reader knows.
        has_arr = 'Customer_ARR' in csone_df.columns
        _arr_is_estimated = bool(
            'ARR_Estimated' in csone_df.columns
            and csone_df['ARR_Estimated'].fillna(False).astype(bool).any()
        )

        # Create table
        table = doc.add_table(rows=len(customer_cases) + 1, cols=4 if has_arr else 3)
        table.style = 'Light Grid Accent 1'
        
        # Headers
        hdr_cells = table.rows[0].cells
        hdr_cells[0].text = 'Customer Name'
        hdr_cells[1].text = 'Total Cases'
        hdr_cells[2].text = 'BEMS References'
        if has_arr:
            hdr_cells[3].text = (
                'Estimated ARR (synthetic)' if _arr_is_estimated else 'Customer ARR'
            )
        
        for cell in hdr_cells:
            for paragraph in cell.paragraphs:
                for run in paragraph.runs:
                    run.font.bold = True
        
        # Data rows
        # Round 13 / Phase 9.1: previously customer / case_count / ARR
        # cells were assigned via raw f-strings (``row_cells[0].text =
        # customer`` / ``f"${avg_arr:,.0f}"``).  Two problems:
        #   1. ``customer`` could carry XML-illegal control codes from
        #      Snowflake (zero-width spaces, tab characters, mojibake)
        #      which python-docx happily wrote to the document and Word
        #      then rejected as "needing repair" on open.
        #   2. ``f"${avg_arr:,.0f}"`` hardcoded the dollar sign even
        #      when the underlying contract was EUR / GBP / JPY, and
        #      reinvented number formatting locally instead of using
        #      the shared ``format_number`` helper that the rest of
        #      the report routes through.
        # Route customer through ``_safe_doc_text`` (XML-safe + length
        # cap) and ARR through the shared ``format_number`` helper for
        # parity with the executive briefing tables.
        try:
            from report_utils import format_number as _r13_format_number
        except Exception:
            _r13_format_number = lambda v, d=0, p=False: (  # type: ignore
                f"{v:,.{d}f}" if d else f"{int(v):,}"
            ) if v is not None else "N/A"
        for i, (customer, case_count) in enumerate(customer_cases.items(), 1):
            row_cells = table.rows[i].cells
            row_cells[0].text = _safe_doc_text(customer, max_len=200)
            row_cells[1].text = _safe_doc_text(case_count, max_len=20)
            
            # Count BEMS references for this customer - use comprehensive detection
            customer_data = csone_df[csone_df[customer_col] == customer]
            customer_bems_cases, customer_bems_count = detect_bems_escalations(customer_data)
            
            if customer_bems_count > 0:
                bems_refs_list = []
                for _, row in customer_bems_cases.iterrows():
                    bems_refs_list.extend(extract_bems_ids_from_row(row))
                
                if bems_refs_list:
                    # Round 13 / Phase 11.2: previously this used
                    # ``', '.join(set(bems_refs_list))`` which dedupes
                    # but renders BEMS refs in *unordered* set
                    # iteration order -- so two reports run against
                    # the same data on the same machine could (and
                    # did, after a Python 3.12 hash-randomization
                    # change) produce a different reference string
                    # for the same customer, which broke
                    # word-vs-excel parity tests and made it look
                    # like data had drifted.  Sort the deduped set
                    # so the output is deterministic across runs.
                    all_refs = ', '.join(sorted(set(bems_refs_list)))
                    # FIXED: Show all BEMS references without truncation
                    row_cells[2].text = _safe_doc_text(all_refs, max_len=2000)
                else:
                    row_cells[2].text = '-'
            else:
                row_cells[2].text = '-'
            
            # Add ARR
            if has_arr:
                avg_arr = customer_data['Customer_ARR'].mean()
                # Round 13 / Phase 9.1: use the shared ``format_number``
                # helper so the table reconciles row-for-row with the
                # executive briefing's Customer ARR formatting (which
                # also handles ``None`` / ``NaN`` defensively and emits
                # ``"N/A"`` instead of ``"$nan"``).  The leading ``$``
                # remains here because this table is rendered only on
                # the single-currency path; the multi-currency path
                # routes through enhanced_snowflake_insights /
                # advanced_renewal_analyzer where Phase 9.4 / 9.5 emit
                # the proper currency prefix.
                if avg_arr is None or (isinstance(avg_arr, float) and avg_arr != avg_arr):
                    row_cells[3].text = _safe_doc_text("N/A", max_len=20)
                else:
                    row_cells[3].text = _safe_doc_text(
                        f"${_r13_format_number(float(avg_arr), 0)}",
                        max_len=40,
                    )
        
        doc.add_paragraph()
    
    # Table 2: Case Severity Breakdown
    # Round 3 hardening: build the table from canonical
    # ``case_priority_norm`` so that it reconciles row-for-row with the
    # severity pie chart and the executive headline counts (P1/P2 etc.).
    # Previously this used the raw ``Severity`` column which produced
    # separate "P1" / "1" / "Critical" rows, dropped null severities, and
    # disagreed with cm.count_p1/cm.count_p2 used elsewhere.
    if not csone_df.empty:
        try:
            _csone_norm_for_sev_table = add_case_lifecycle_fields(csone_df)
        except Exception:
            _csone_norm_for_sev_table = csone_df
        if 'case_priority_norm' in _csone_norm_for_sev_table.columns:
            doc.add_heading('Case Severity Distribution', level=2)

            sev_series = (
                _csone_norm_for_sev_table['case_priority_norm']
                .fillna('Unknown')
                .astype(str)
            )
            ordered = ['P1', 'P2', 'P3', 'P4', 'Unknown']
            raw_counts = sev_series.value_counts()
            severity_counts = [
                (k, int(raw_counts.get(k, 0))) for k in ordered if int(raw_counts.get(k, 0)) > 0
            ]

            table = doc.add_table(rows=len(severity_counts) + 1, cols=2)
            table.style = 'Light Grid Accent 1'

            hdr_cells = table.rows[0].cells
            hdr_cells[0].text = 'Severity'
            hdr_cells[1].text = 'Count'
            for cell in hdr_cells:
                for paragraph in cell.paragraphs:
                    for run in paragraph.runs:
                        run.font.bold = True

            for i, (severity, count) in enumerate(severity_counts, 1):
                row_cells = table.rows[i].cells
                row_cells[0].text = str(severity)
                row_cells[1].text = str(count)

            doc.add_paragraph()
    
    # === BEMS ESCALATIONS TABLE ===
    # Use comprehensive BEMS detection that checks Transaction ID column
    bems_cases, bems_count = detect_bems_escalations(csone_df)
    if not bems_cases.empty and bems_count > 0:
        doc.add_heading('BEMS Escalations & Engineering Issues', level=2)
        # Group by customer using canonical BEMS ID extraction
        def extract_bems_refs(row):
            refs = extract_bems_ids_from_row(row)
            return ', '.join(refs)
        
        bems_cases['bems_extracted'] = bems_cases.apply(extract_bems_refs, axis=1)
        
        # Find customer column name
        customer_col_bems = None
        for col in ['Customer Name', 'customer_name', 'Customer', 'BU_NAME', 'Account Name']:
            if col in bems_cases.columns:
                customer_col_bems = col
                break
        
        if customer_col_bems:
            # Find case number column
            case_col = None
            for col in ['SR Number', 'Case Number', 'SR_Number', 'Case_Number']:
                if col in bems_cases.columns:
                    case_col = col
                    break
            
            # Round 4 / Phase 3.6: dedupe BEMS/CSC reference IDs
            # across rows for the same customer.  Previously the
            # aggregator joined per-row strings without splitting,
            # so ``BEMS-1234`` could appear N times when N rows
            # mentioned it — making the table imply more distinct
            # escalations than actually existed.
            def _dedupe_bems_refs(values):
                tokens = set()
                for v in values:
                    if not v:
                        continue
                    for tok in str(v).split(','):
                        t = tok.strip()
                        if t:
                            tokens.add(t)
                return ', '.join(sorted(tokens))

            if case_col:
                bems_by_customer = bems_cases.groupby(customer_col_bems).agg({
                    'bems_extracted': _dedupe_bems_refs,
                    case_col: 'count'
                }).reset_index()
                bems_by_customer.columns = [customer_col_bems, 'BEMS/CSC References', 'Case Count']
            else:
                # Fallback if no case number column - count rows per customer instead
                bems_by_customer = bems_cases.groupby(customer_col_bems).agg({
                    'bems_extracted': _dedupe_bems_refs,
                    customer_col_bems: 'count'  # Count actual rows per customer
                }).reset_index()
                bems_by_customer.columns = [customer_col_bems, 'BEMS/CSC References', 'Case Count']
        else:
            # Fallback if no customer column
            bems_by_customer = pd.DataFrame(columns=['Customer Name', 'BEMS/CSC References', 'Case Count'])
        if not bems_by_customer.empty:
            # FIXED: Show ALL customers with BEMS escalations
            bems_by_customer = bems_by_customer.sort_values('Case Count', ascending=False)
            
            table = doc.add_table(rows=len(bems_by_customer) + 1, cols=3)
            table.style = 'Light Grid Accent 1'
            
            hdr_cells = table.rows[0].cells
            hdr_cells[0].text = 'Customer Name'
            hdr_cells[1].text = 'BEMS/CSC References'
            hdr_cells[2].text = 'Cases with Escalations'
            
            for cell in hdr_cells:
                for paragraph in cell.paragraphs:
                    for run in paragraph.runs:
                        run.font.bold = True
            
            # Use iterrows() for safer column name access (avoids positional issues)
            for i, (idx, row) in enumerate(bems_by_customer.iterrows(), 1):
                row_cells = table.rows[i].cells
                # Access by column name - safe even if column order changes
                customer_name = row.get(customer_col_bems, 'Unknown') if customer_col_bems else 'Unknown'
                bems_refs = row.get('BEMS/CSC References', '')
                case_count = row.get('Case Count', 0)
                
                row_cells[0].text = str(customer_name)
                # FIXED: Show all BEMS references without truncation
                row_cells[1].text = str(bems_refs)
                row_cells[2].text = str(case_count)
        else:
            doc.add_paragraph("No BEMS data available for grouping.")
            doc.add_paragraph()
    else:
        doc.add_paragraph("No BEMS escalations identified in current data.")
    doc.add_paragraph()
    
    # === SOFTWARE DEFECTS TABLE ===
    if defect_count > 0:
        doc.add_heading('Software Defects (BST/CSC IDs)', level=2)
        cases_with_defects = software_defects.get("total_cases_with_defects", 0)
        doc.add_paragraph(f'Total unique software defects identified: {defect_count} across {cases_with_defects} cases')
        
        # Create defects by customer table
        defect_by_customer = software_defects.get('defect_by_customer', {})
        if defect_by_customer:
            defect_customer_data = []
            for customer, defects in defect_by_customer.items():
                unique_defects = sorted(set(defects))
                defect_customer_data.append({
                    'customer': customer,
                    'defect_count': len(unique_defects),
                    'defects': ', '.join([f'[{d}]' for d in unique_defects])  # FIXED: Show all defects with brackets
                })
            
            # FIXED: Show ALL customers with defects
            defect_customer_df = pd.DataFrame(defect_customer_data).sort_values('defect_count', ascending=False)
            
            if not defect_customer_df.empty:
                table = doc.add_table(rows=len(defect_customer_df) + 1, cols=3)
                table.style = 'Light Grid Accent 1'
                
                hdr_cells = table.rows[0].cells
                hdr_cells[0].text = 'Customer Name'
                hdr_cells[1].text = 'Defect Count'
                hdr_cells[2].text = 'All Defect IDs'
                
                for cell in hdr_cells:
                    for paragraph in cell.paragraphs:
                        for run in paragraph.runs:
                            run.font.bold = True
                
                # Use iterrows() for safer column name access
                for i, (idx, row) in enumerate(defect_customer_df.iterrows(), 1):
                    row_cells = table.rows[i].cells
                    row_cells[0].text = str(row.get('customer', 'Unknown'))
                    row_cells[1].text = str(row.get('defect_count', 0))
                    row_cells[2].text = str(row.get('defects', ''))  # FIXED: No truncation - show all defects
            else:
                doc.add_paragraph("No defect data available for grouping.")
            
            doc.add_paragraph()
    
    # === PSIRT VULNERABILITIES TABLE ===
    if vuln_count > 0:
        doc.add_heading('Security Vulnerabilities (CVEs & PSIRT Advisories)', level=2)
        cve_count = len(psirt_vulns.get("cve_ids", set()))
        psirt_count = len(psirt_vulns.get("psirt_advisories", set()))
        doc.add_paragraph(f'Total vulnerabilities identified: {vuln_count} ({cve_count} CVEs, {psirt_count} PSIRT advisories)')
        
        # Create vulnerabilities by customer table
        vulnerability_by_customer = psirt_vulns.get('vulnerability_by_customer', {})
        if vulnerability_by_customer:
            vuln_customer_data = []
            for customer, vulns in vulnerability_by_customer.items():
                unique_vulns = sorted(set(vulns))
                vuln_customer_data.append({
                    'customer': customer,
                    'vuln_count': len(unique_vulns),
                    'vulns': ', '.join([f'[{v}]' for v in unique_vulns])  # FIXED: Show all vulns with brackets
                })
            
            # FIXED: Show ALL customers with vulnerabilities
            vuln_customer_df = pd.DataFrame(vuln_customer_data).sort_values('vuln_count', ascending=False)
            
            if not vuln_customer_df.empty:
                table = doc.add_table(rows=len(vuln_customer_df) + 1, cols=3)
                table.style = 'Light Grid Accent 1'
                
                hdr_cells = table.rows[0].cells
                hdr_cells[0].text = 'Customer Name'
                hdr_cells[1].text = 'Vulnerability Count'
                hdr_cells[2].text = 'All Vulnerability IDs'
                
                for cell in hdr_cells:
                    for paragraph in cell.paragraphs:
                        for run in paragraph.runs:
                            run.font.bold = True
                
                # Use iterrows() for safer column name access
                for i, (idx, row) in enumerate(vuln_customer_df.iterrows(), 1):
                    row_cells = table.rows[i].cells
                    row_cells[0].text = str(row.get('customer', 'Unknown'))
                    row_cells[1].text = str(row.get('vuln_count', 0))
                    row_cells[2].text = str(row.get('vulns', ''))  # FIXED: No truncation - show all vulns
            else:
                doc.add_paragraph("No vulnerability data available for grouping.")
            
            doc.add_paragraph()
    
    doc.add_page_break()
    
    # === CHARTS ===
    if chart_paths and len(chart_paths) > 0:
        doc.add_heading('Visual Analysis & Trends', level=1)
        
        logger.info(f"[[CHART]] Adding {len(chart_paths)} charts to report")
        charts_added = 0
        for chart_path in chart_paths:
            logger.info(f"[[CHART]] Checking chart: {chart_path}, exists: {os.path.exists(chart_path)}")
            if os.path.exists(chart_path):
                try:
                    # Add chart title based on filename
                    # Round 13 / Phase 8.6 + 9.10: previously only the
                    # heading conveyed what the chart was; the embedded
                    # PNG had no docPr alt text, so screen readers and
                    # accessibility tools announced only the filename
                    # ("severity_distribution_20251025_120000Z.png").
                    # Capture the heading we just emitted so we can
                    # also stamp it as the picture's alt-text once
                    # add_picture returns.
                    _r13_chart_title = ''
                    if 'support_cases_trend' in chart_path:
                        _r13_chart_title = 'Support Cases Over Time'
                    elif 'severity_distribution' in chart_path:
                        _r13_chart_title = 'Case Severity Distribution'
                    elif 'top_customers' in chart_path:
                        _r13_chart_title = 'Top Customers by Case Volume'
                    elif 'bems_escalations' in chart_path:
                        _r13_chart_title = 'BEMS Escalations by Customer'
                    elif 'feature_request_volume' in chart_path:
                        _r13_chart_title = 'Feature Requests by Customer'
                    if _r13_chart_title:
                        doc.add_heading(_r13_chart_title, level=2)
                    _r13_picture = doc.add_picture(chart_path, width=Inches(6.5))
                    try:
                        _r13_set_picture_alt_text(
                            _r13_picture,
                            _r13_chart_alt_text(_r13_chart_title or os.path.basename(chart_path)),
                        )
                    except Exception:
                        pass
                    doc.add_paragraph()  # Spacing
                    charts_added += 1
                    logger.info(f"[[OK]] Chart added: {chart_path}")
                except Exception as e:
                    logger.error(f"[[ERROR]] Failed to add chart {chart_path}: {e}")
        
        logger.info(f"[[OK]] Total charts added to report: {charts_added}")
        
        if charts_added == 0:
            doc.add_paragraph("Charts are being generated but not available yet.")
    else:
        logger.warning(f"[[WARNING]] No charts available to add. chart_paths: {chart_paths}")
    
    doc.add_page_break()
    
    # === FEATURE REQUESTS ===
    if feature_requests and feature_requests.get('total_requests', 0) > 0:
        doc.add_heading('Feature Requests from Customers', level=1)
        
        para = doc.add_paragraph()
        para.add_run(f"Total Feature Requests: ").bold = True
        para.add_run(f"{feature_requests['total_requests']}")
        
        if False and feature_requests.get('total_arr_impact', 0) > 0:
            arr_para = doc.add_paragraph()
            arr_para.add_run(f"Combined ARR Impact: ").bold = True
            arr_para.add_run(f"${feature_requests['total_arr_impact']:,.0f}")
        
        if feature_requests.get('top_features'):
            doc.add_heading('Most Requested Features', level=2)
            for theme, count in feature_requests['top_features']:
                doc.add_paragraph(f"{theme.title()}: {count} mentions", style='List Bullet')
        
        # FIXED: Show ALL requesting customers
        if feature_requests.get('customer_examples'):
            doc.add_heading('All Requesting Customers', level=2)
            for customer_info in feature_requests['customer_examples']:
                para = doc.add_paragraph()
                # Round 13 / Phase 9.2: previously the raw
                # ``customer_info['customer_name']`` was written via
                # ``add_run`` directly, so a customer name carrying an
                # XML-illegal control character (zero-width space, tab,
                # mojibake from a Snowflake export) sailed through into
                # the .docx and Word then refused to open without
                # "repair".  The sibling table row at Phase 9.1 already
                # routes the same field through ``_safe_doc_text``, so
                # the feature-request roster was the only remaining
                # raw-write site for ``customer_name`` in this report.
                # ``request_count`` is also normalized so a hostile or
                # bogus int (e.g. NaN from pandas) cannot inject
                # surrogate code points either.
                _r13_cust = _safe_doc_text(customer_info.get('customer_name', ''), max_len=200)
                para.add_run(_r13_cust).bold = True
                _r13_req_count = _safe_doc_text(
                    customer_info.get('request_count', 0), max_len=20
                )
                para.add_run(f" - {_r13_req_count} requests")
                if False and customer_info.get('arr', 0) > 0:
                    para.add_run(f" (ARR: ${customer_info['arr']:,.0f})")
    
    # Footer
    doc.add_paragraph()
    # Round 12 / Phase 10.6: anchor the Word footer "Report generated on"
    # line on UTC and tag the timezone so the footer is reproducible
    # across operators in different host timezones.
    footer = doc.add_paragraph(
        f"Report generated on: {datetime.now(timezone.utc).strftime('%Y-%m-%d %H:%M:%S')} UTC"
    )
    footer.alignment = WD_ALIGN_PARAGRAPH.CENTER
    if footer.runs:
        footer.runs[0].italic = True

    # Phase 1.1: Run validate_report_consistency on the same frames the
    # _create_enhanced_compact_report fallback rendered with, so this path
    # surfaces drift the same way the EI / Compact formatters already do.
    try:
        _enh_extra_frames = [
            f for f in (
                team_subs_df,
                csconsole_action_plans,
                csconsole_customer_pulse,
                csconsole_success_priorities,
                csconsole_adoption_barriers,
            )
            if isinstance(f, pd.DataFrame) and not f.empty
        ]
        _enh_portfolio_metrics = cm.build_portfolio_metrics(
            ab_df=ab_norm if isinstance(ab_norm, pd.DataFrame) else pd.DataFrame(),
            csone_df=csone_df if isinstance(csone_df, pd.DataFrame) else pd.DataFrame(),
            risk_profiles={},
            risk_scale=cm.RISK_SCALE_0_TO_10,
            extra_customer_frames=_enh_extra_frames or None,
        )
        # Round 6 / Phase 5.8: thread ``strict_mode`` and any
        # factual_claims (LLM-derived narrative bullets) through the
        # enhanced compact fallback so this path matches the comprehensive
        # path's enforcement model -- the legacy code silently fell back
        # to non-strict and never checked claims, so cross-source drift
        # could pass here while failing downstream.
        _enh_strict = (
            str(os.getenv("ADOPTIQ_NONSTRICT_CONSISTENCY", "0")).strip().lower()
            not in {"1", "true", "yes", "on"}
        )
        _enh_factual_claims = locals().get("factual_claims") or []
        # Round 22 / R22-001: thread _enh_extra_frames through the validator
        # so its total_customers matches _enh_portfolio_metrics["total_customers"]
        # exactly.  The PM was built with extra_customer_frames=_enh_extra_frames
        # at L5636, but the validator without extras would compute AB+CSOne only
        # and raise "Portfolio metric mismatch".  No account_to_customer in
        # scope on this path; pass None.
        _enh_consistency = validate_report_consistency(
            ab_norm if isinstance(ab_norm, pd.DataFrame) else pd.DataFrame(),
            csone_df if isinstance(csone_df, pd.DataFrame) else pd.DataFrame(),
            portfolio_metrics=_enh_portfolio_metrics,
            customer_pulse_df=csconsole_customer_pulse,
            strict_mode=_enh_strict,
            factual_claims=_enh_factual_claims if isinstance(_enh_factual_claims, list) else None,
            extra_frames=_enh_extra_frames or None,
        )
        if not _enh_consistency.get('is_valid', True):
            logger.error(
                f"[[CONSISTENCY]] Enhanced compact fallback errors: {_enh_consistency.get('errors')}"
            )
        if _enh_consistency.get('warnings'):
            logger.warning(
                f"[[CONSISTENCY]] Enhanced compact fallback warnings: {_enh_consistency.get('warnings')}"
            )
    except Exception as _ecerr:
        logger.warning(f"[[CONSISTENCY]] Enhanced compact consistency check skipped: {_ecerr}")

    # Save
    output_path = f"{base_path}_enhanced.docx"
    doc.save(output_path)
    logger.info(f"[[OK]] Enhanced compact report created: {output_path}")
    return output_path

def _create_simple_fallback_report(base_path: str, manager: str, technology: str, days: int, ai_insights: Dict) -> str:
    """Create a simple fallback report when the main report generation fails"""
    try:
        from docx import Document
        from docx.shared import Inches
        
        logger.info(f"[[WRITE]] Creating simple fallback report with markdown parsing...")
        
        doc = Document()
        
        # Title
        # Round 6 / Phase 1.4: sanitize manager string before heading.
        title = doc.add_heading(_safe_doc_text(f'AdoptIQ Portfolio Analysis - {manager}'), 0)
        title.alignment = 1  # Center alignment
        
        # Subtitle
        subtitle = doc.add_heading(f'{technology} - {days} Day Analysis', level=1)
        subtitle.alignment = 1
        
        # Executive Summary - PARSE MARKDOWN!
        doc.add_heading('Executive Summary', level=1)
        summary_text = ai_insights.get('executive_summary', 'Analysis completed with AI-generated insights.')
        _parse_markdown_for_fallback(doc, summary_text)
        
        # Key Findings
        doc.add_heading('Key Findings', level=1)
        doc.add_paragraph("• Portfolio analysis completed successfully")
        doc.add_paragraph("• AI insights generated for strategic recommendations")
        doc.add_paragraph("• Report generated with fallback formatting due to timeout")
        
        # Recommendations
        doc.add_heading('Recommendations', level=1)
        doc.add_paragraph("• Review AI-generated insights for strategic guidance")
        doc.add_paragraph("• Schedule follow-up analysis if detailed formatting is required")
        doc.add_paragraph("• Consider running analysis during off-peak hours for full formatting")
        
        # Footer
        doc.add_paragraph("\n" + "="*50)
        # Round 12 / Phase 10.6: anchor on UTC for cross-host reproducibility.
        doc.add_paragraph(
            f"Report generated on: {datetime.now(timezone.utc).strftime('%Y-%m-%d %H:%M:%S')} UTC"
        )
        doc.add_paragraph("AdoptIQ Portfolio Analysis System")
        
        # Save the document
        output_path = f"{base_path}_fallback.docx"
        doc.save(output_path)
        
        logger.info(f"[[OK]] Fallback report created: {output_path}")
        return output_path
        
    except Exception as e:
        logger.error(f"[[ERROR]] Failed to create fallback report: {e}")
        # Return a simple text file as last resort
        output_path = f"{base_path}_fallback.txt"
        try:
            with open(output_path, 'w', encoding='utf-8') as f:
                f.write(f"AdoptIQ Portfolio Analysis - {manager}\n")
                f.write(f"{technology} - {days} Day Analysis\n\n")
                f.write("Executive Summary:\n")
                f.write(ai_insights.get('executive_summary', 'Analysis completed successfully.\n'))
                # Round 12 / Phase 10.6: anchor on UTC for cross-host reproducibility.
                f.write(
                    f"\nReport generated on: {datetime.now(timezone.utc).strftime('%Y-%m-%d %H:%M:%S')} UTC\n"
                )
                f.write("AdoptIQ Portfolio Analysis System\n")
            logger.info(f"[[OK]] Text fallback report created: {output_path}")
            return output_path
        except Exception as e2:
            logger.error(f"[[ERROR]] Failed to create even text fallback: {e2}")
            return None

def _get_customer_specific_technology(customer: str, data: Dict) -> str:
    """Determine the specific technology for a customer based on their subscription data"""
    try:
        subscriptions = data.get('subscriptions', pd.DataFrame())
        if subscriptions.empty or 'PRODUCT_NAME' not in subscriptions.columns:
            return None
        
        # Get subscriptions for this customer
        customer_subscriptions = subscriptions[
            subscriptions.get('BU_NAME', pd.Series()) == customer
        ]
        
        if customer_subscriptions.empty:
            return None
        
        # Find the most specific contact center technology
        technologies_found = set()
        for _, sub in customer_subscriptions.iterrows():
            product_name = sub.get('PRODUCT_NAME', '')
            if pd.notna(product_name):
                tech = _categorize_technology(str(product_name))
                if tech in ['Webex Contact Center', 'Webex Contact Center Enterprise', 'Cisco UCCE', 'Cisco UCCX']:
                    technologies_found.add(tech)
        
        # Return the most specific technology found
        if 'Webex Contact Center Enterprise' in technologies_found:
            return 'Webex Contact Center Enterprise'
        elif 'Webex Contact Center' in technologies_found:
            return 'Webex Contact Center'
        elif 'Cisco UCCE' in technologies_found:
            return 'Cisco UCCE'
        elif 'Cisco UCCX' in technologies_found:
            return 'Cisco UCCX'
        elif technologies_found:
            return next(iter(technologies_found), None)
        
        return None
        
    except Exception as e:
        logger.warning(f"Error determining technology for customer {customer}: {e}")
        return None

def _categorize_technology(product_name: str) -> str:
    """Categorize product name into technology groups"""
    product_lower = product_name.lower()
    
    if any(keyword in product_lower for keyword in ['webex meetings', 'meetings', 'meeting']):
        return 'Webex Meetings'
    elif any(keyword in product_lower for keyword in ['webex calling', 'calling', 'ucm']):
        return 'Webex Calling'
    # Specific contact center technology categorization
    elif any(keyword in product_lower for keyword in ['webex contact center enterprise', 'contact center enterprise']):
        return 'Webex Contact Center Enterprise'
    elif any(keyword in product_lower for keyword in ['webex contact center', 'wxcc', 'ccaas']) and 'enterprise' not in product_lower:
        return 'Webex Contact Center'
    elif any(keyword in product_lower for keyword in ['cisco ucce', 'ucce', 'unified contact center enterprise']):
        return 'Cisco UCCE'
    elif any(keyword in product_lower for keyword in ['cisco uccx', 'uccx', 'unified contact center express']):
        return 'Cisco UCCX'
    elif any(keyword in product_lower for keyword in ['contact center']):
        return 'All Contact Center'
    elif any(keyword in product_lower for keyword in ['messaging', 'teams']):
        return 'Messaging'
    elif any(keyword in product_lower for keyword in ['device', 'endpoint', 'desk', 'phone', 'deskpro', 'desk pro']):
        return 'Devices'
    elif any(keyword in product_lower for keyword in ['video', 'room kit', 'roomkit', 'board', 'codec']):
        return 'Video'
    else:
        return 'Other'

