                    logger.info(f"[EXEC-REPORT] CSOne columns: {list(csone_df.columns) if not csone_df.empty else 'EMPTY'}")
                    
                    logger.info(f"[EXEC-REPORT] Step 5/5: Calling create_executive_intelligence_report...")
