                            csconsole_customer_pulse=_r23_cp if _r23_cp is not None else pd.DataFrame(),  # Round 23 / R22-NEXT-001
                            csconsole_success_priorities=_r23_sp if _r23_sp is not None else pd.DataFrame(),  # Round 23 / R22-NEXT-001
