@app.route('/subscription_renewal_risk/<subscription_id>')
def subscription_renewal_risk(subscription_id):
    """Get renewal risk analysis for a subscription"""
    try:
        # Validate subscription ID format
        if not re.match(r'^[a-zA-Z0-9\-_]+$', subscription_id):
            return jsonify({'error': 'Invalid subscription ID format'}), 400
        
        days = request.args.get('days', 90, type=int)
        is_valid, error_msg = validate_days_input(days)
        if not is_valid:
            return jsonify({'error': error_msg}), 400
        
        # Get renewal risk analysis
        risk_analysis = get_subscription_renewal_risk(subscription_id, days)

        # Round 3 / Phase 5.3: when the subscription truly cannot be
        # scored (e.g. ID was not found), return a 404 envelope that
        # explicitly carries ``risk_score=null`` and ``state`` so the
        # client cannot quietly render "0" as a real risk reading.
        if 'error' in risk_analysis:
            return jsonify({
                'error': risk_analysis['error'],
                'risk_score': risk_analysis.get('risk_score'),
                'risk_level': risk_analysis.get('risk_level', 'UNKNOWN'),
                'state': risk_analysis.get('state', 'unavailable'),
            }), 404

        return jsonify({
            'success': True,
            'renewal_analysis': risk_analysis
        })
        
    except Exception as e:
        logger.error(f"Error getting subscription renewal risk: {e}")
        return jsonify({'error': 'Failed to retrieve renewal risk analysis'}), 500


@app.route('/start_subscription_analysis', methods=['POST'])
def start_subscription_analysis():
    """Start subscription-based analysis"""
    if app.config.get('WTF_CSRF_ENABLED', True):
        try:
            validate_csrf(request.headers.get('X-CSRFToken') or request.headers.get('X-CSRF-Token') or request.form.get('csrf_token'))
        except Exception:
            return jsonify({'ok': False, 'success': False, 'error': 'CSRF validation failed'}), 403  # Round 13 / Phase 4.3
    try:
        data = request.form
        subscription_id = data.get('subscription_id', '').strip()
        try:
            days = int(data.get('days', 90))
        except (ValueError, TypeError):
            days = 90
        report_type = data.get('report_type', 'comprehensive')
        
        if not subscription_id:
            return jsonify({'error': 'Subscription ID is required'}), 400
        
        # Validate subscription ID format (alphanumeric and hyphens only)
        if not re.match(r'^[a-zA-Z0-9\-_]+$', subscription_id):
            return jsonify({'error': 'Invalid subscription ID format'}), 400
        
        is_valid, error_msg = validate_days_input(days)
        if not is_valid:
            return jsonify({'error': error_msg}), 400
        
        # Generate unique analysis ID (sanitized)
        safe_subscription_id = re.sub(r'[^a-zA-Z0-9\-_]', '', subscription_id)
        analysis_id = f"sub_{safe_subscription_id}_{int(time.time())}"
        
        # Initialize analysis status
        with analysis_status_lock:
            analysis_status[analysis_id] = {
                'status': 'initializing',
                'progress': 0,
                'message': 'Initializing subscription analysis...',
                'subscription_id': subscription_id,
                'days': days,
                'report_type': report_type,
                'start_time': _now_utc_iso_z(),
                'current_step': 'Initialization',
                'step_start_time': _now_utc_iso_z()
            }
        
        # Start analysis in background thread
        thread = threading.Thread(
            target=run_subscription_analysis,
            args=(analysis_id,),
            daemon=True
        )
        thread.start()
        
        return jsonify({
            'success': True,
            'analysis_id': analysis_id,
            'message': 'Subscription analysis started'
        })
        
    except Exception as e:
        logger.error(f"Error starting subscription analysis: {e}")
        return jsonify({'error': 'Failed to start subscription analysis'}), 500


def run_subscription_analysis(analysis_id):
    """Run subscription-based analysis"""
    # Round 5 / Phase 6.14: bind the analysis ID for correlated logs.
    try:
        from structured_logging import bind_analysis_id as _bind_aid
        _bind_aid(analysis_id)
    except Exception:
        pass  # noqa: PIE790
    try:
        logger.info(f"[[START]] Starting subscription analysis: {analysis_id}")
        
        # Get analysis parameters
        with analysis_status_lock:
            status = analysis_status[analysis_id]
            subscription_id = status['subscription_id']
            days = status['days']
            report_type = status['report_type']
        
        with analysis_status_lock:
            status['status'] = 'running'
            status['completed_steps'] = []
            _update_progress(status, 10, 'Querying subscription details...', 'Data Retrieval')
        
        sub_data = fetch_subscription_data(subscription_id, days)
        
        if not sub_data['found']:
            with analysis_status_lock:
                status['status'] = 'error'
                status['message'] = f"Subscription not found: {sub_data.get('error', 'Unknown error')}"
            save_analysis_status()
            return
        
        with analysis_status_lock:
            _update_progress(status, 20, f'Loading customer context for {sub_data.get("customer_name", "")}...', 'Data Retrieval')
        
        ab_df = pd.DataFrame(sub_data['adoption_barriers']) if sub_data['adoption_barriers'] else pd.DataFrame()
        # Phase 1.1: validate the data sources required to author a
        # subscription analysis. We require the subscription record to
        # have been found above (already enforced) and at least one
        # piece of customer context to be populated.  Without this
        # check the report could ship as-zero on a Snowflake outage.
        try:
            _subscription_team_subs = pd.DataFrame([{
                'BU_NAME': sub_data.get('customer_name', ''),
                'ACCOUNT_ID_C': sub_data.get('account_id', ''),
                'SUBSCRIPTION_ID': subscription_id,
            }])
            raise_validation_error_if_invalid(
                report_type='subscription',
                snowflake_ctx=None,  # subscription path uses pre-fetched data
                team_subs_df=_subscription_team_subs,
                ab_data=ab_df,
                csone_data=pd.DataFrame(),
                required_sources=['team_subscriptions'],
            )
        except DataSourceValidationError as ve:
            logger.error(f"[[VALIDATION]] Subscription analysis validation failed: {ve}")
            with analysis_status_lock:
                status['status'] = 'error'
                status['error'] = 'Subscription analysis data validation failed'
                status['message'] = (
                    f"Subscription analysis cannot proceed: "
                    f"{', '.join(ve.missing_sources)} missing or empty."
                )
                status['completion_time'] = _now_utc_iso_z()
                save_analysis_status()
            return
        ap_df = pd.DataFrame(sub_data['action_plans']) if sub_data['action_plans'] else pd.DataFrame()
        cp_df = pd.DataFrame(sub_data['customer_pulse']) if sub_data['customer_pulse'] else pd.DataFrame()
        sp_df = pd.DataFrame(sub_data['success_priorities']) if sub_data['success_priorities'] else pd.DataFrame()
        
        with analysis_status_lock:
            _update_progress(status, 30, 'Analyzing adoption barriers and support cases...', 'Data Analysis')
        
        with analysis_status_lock:
            _update_progress(status, 40, 'Calculating renewal risk scores...', 'Risk Analysis')
        
        renewal_analysis = get_subscription_renewal_risk(subscription_id, days)
        
        with analysis_status_lock:
            _update_progress(status, 50, 'Preparing AI briefing book...', 'AI Analysis')
        
        try:
            briefing_parts = [f"## Subscription Briefing: {sub_data.get('customer_name', subscription_id)}"]
            briefing_parts.append(f"Subscription ID: {subscription_id}")
            briefing_parts.append(f"Analysis window: {days} days")
            # Round 4: surface the 50-item display cap so the LLM cannot
            # describe a 200-item section as "complete"; section header
            # already shows the true total ``len(items)``.
            _SUB_BRIEF_ITEM_LIMIT = 50
            # Round 5 / Phase 3.11: cap each per-field value to a
            # bounded length before joining.  A single rogue
            # description (e.g. a giant pasted email or stack trace
            # in adoption barrier notes) could otherwise push a single
            # subscription briefing past the LLM context budget,
            # forcing aggressive downstream truncation that drops
            # entirely unrelated sections.  Bound at 600 chars per
            # field; append a marker so the LLM knows the value was
            # clipped and not "the entire content".
            _SUB_BRIEF_FIELD_CAP = int(os.environ.get("ADOPTIQ_SUB_BRIEF_FIELD_CAP", "600"))

            def _cap_field(_v: Any) -> str:
                _s = '' if _v is None else str(_v)
                if len(_s) > _SUB_BRIEF_FIELD_CAP:
                    return _s[:_SUB_BRIEF_FIELD_CAP] + f"… (truncated, {len(_s)} chars total)"
                return _s

            for section_key in ('adoption_barriers', 'action_plans', 'customer_pulse', 'success_priorities'):
                items = sub_data.get(section_key, [])
                if items:
                    _shown = min(len(items), _SUB_BRIEF_ITEM_LIMIT)
                    _suffix = (
                        f" — showing sample of {_shown} of {len(items)} items"
                        if len(items) > _SUB_BRIEF_ITEM_LIMIT else ""
                    )
                    briefing_parts.append(
                        f"\n### {section_key.replace('_', ' ').title()} ({len(items)} items{_suffix})"
                    )
                    for item in items[:_SUB_BRIEF_ITEM_LIMIT]:
                        if isinstance(item, dict):
                            briefing_parts.append(
                                f"- {', '.join(f'{k}: {_cap_field(v)}' for k, v in item.items() if v)}"
                            )
                        else:
                            briefing_parts.append(f"- {_cap_field(item)}")
            briefing_book = "\n".join(briefing_parts)
            
            with analysis_status_lock:
                _update_progress(status, 55, '[AI] Sending to CircuIT (this may take up to 60 seconds)...', 'AI Analysis - CircuIT')
            
            sub_prompt = PROMPT_CUSTOMER_TEMPLATE.format(
                CUSTOMER_NAME=sub_data.get('customer_name', subscription_id),
                CSSM_NAME='',
                TECHNOLOGY='',
                MANAGER=''
            )
            ai_response = generate_llm_response(sub_prompt, briefing_book)
            
            with analysis_status_lock:
                _update_progress(status, 70, '[AI] Processing AI response...', 'AI Analysis - Processing')
        except Exception as e:
            logger.warning(f"AI analysis failed, using fallback: {e}")
            ai_response = f"Analysis completed for {sub_data['customer_name']} (Subscription: {subscription_id})"
        
        with analysis_status_lock:
            _update_progress(status, 75, 'Building Word report...', 'Report Generation')
        
        # Generate reports (canonical outputs when frozen)
        output_dir = _APP_SUPPORT / "outputs" if _frozen else Path("outputs")
        output_dir.mkdir(parents=True, exist_ok=True)
        
        # Round 12 / Phase 10.6: anchor artifact filename suffix on UTC and
        # tag with ``Z`` so subscription analysis filenames are deterministic
        # across host timezones.
        timestamp = datetime.now(timezone.utc).strftime("%Y%m%d_%H%M%SZ")
        safe_customer_name = "".join(c for c in (sub_data.get('customer_name') or 'Unknown') if c.isalnum() or c in (' ', '-', '_')).rstrip()
        safe_subscription_id = subscription_id.replace(':', '_').replace('/', '_')
        
        # Generate Word report
        word_filename = f"Subscription_Analysis_{safe_customer_name}_{safe_subscription_id}_{timestamp}.docx"
        word_path = output_dir / word_filename
        
        try:
            doc = Document()
            
            # Title page
            title = doc.add_heading(f'Subscription Analysis: {sub_data.get("customer_name") or "Unknown"}', 0)
            subtitle = doc.add_heading(f'Subscription ID: {subscription_id}', level=1)
            details = doc.add_paragraph()
            # Round 12 / Phase 10.6: anchor on UTC and tag the timezone so
            # subscription Word details show one consistent date across hosts.
            details.add_run(
                f'Analysis Date: {datetime.now(timezone.utc).strftime("%B %d, %Y")} UTC\n'
            ).bold = True
            details.add_run(f'Analysis Period: {days} days\n').bold = True
            details.add_run(f'Technology: {sub_data.get("technology", "N/A")} | Sub-Technology: {sub_data.get("sub_technology", "N/A")}\n').bold = True
            details.add_run(f'Status: {sub_data.get("status", "N/A")}\n').bold = True
            
            doc.add_page_break()
            
            # Executive Summary
            doc.add_heading('Executive Summary', level=1)
            summary_p = doc.add_paragraph()
            summary_p.add_run(f'Customer: {sub_data["customer_name"]}\n')
            summary_p.add_run(f'Subscription: {subscription_id}\n')
            summary_p.add_run(f'Renewal Risk Level: {renewal_analysis.get("risk_level", "Unknown")} ({renewal_analysis.get("overall_risk_score", renewal_analysis.get("risk_score", 0))}/10)\n')
            
            # Risk Analysis
            doc.add_heading('Renewal Risk Analysis', level=1)
            risk_p = doc.add_paragraph()
            risk_p.add_run(f'Overall Risk Score: {renewal_analysis.get("overall_risk_score", renewal_analysis.get("risk_score", 0))}/10\n').bold = True
            risk_p.add_run(f'Risk Level: {renewal_analysis.get("risk_level", "Unknown")}\n').bold = True
            
            # Risk Components
            doc.add_heading('Risk Components', level=2)
            risk_components = renewal_analysis.get('risk_components', {})
            if not isinstance(risk_components, dict):
                logger.warning("Subscription analysis risk_components has unexpected type; defaulting to empty set")
                risk_components = {}
            for component, data in risk_components.items():
                score_value = 0.0
                count_value = 0
                if isinstance(data, dict):
                    try:
                        score_value = float(data.get('score', 0) or 0)
                    except (TypeError, ValueError):
                        score_value = 0.0
                    raw_count = data.get('count', data.get('total', data.get('value', 0)))
                    try:
                        count_value = int(raw_count or 0)
                    except (TypeError, ValueError):
                        count_value = 0
                comp_p = doc.add_paragraph()
                comp_p.add_run(f'{component.replace("_", " ").title()}: ').bold = True
                comp_p.add_run(f'{score_value:.1f}/10 - Count: {count_value}')
            
            # Recommendations
            doc.add_heading('Recommendations', level=1)
            for i, rec in enumerate(renewal_analysis.get('recommendations', []), 1):
                rec_p = doc.add_paragraph()
                rec_p.add_run(f'{i}. {rec}')
            
            # Data Summary
            doc.add_heading('Data Summary', level=1)
            summary_table = doc.add_table(rows=1, cols=2)
            summary_table.style = 'Table Grid'
            
            # Header
            header_cells = summary_table.rows[0].cells
            header_cells[0].text = 'Data Type'
            header_cells[1].text = 'Count'
            
            # Add data
            for data_type, count in sub_data['summary'].items():
                row_cells = summary_table.add_row().cells
                row_cells[0].text = data_type.replace('_', ' ').title()
                row_cells[1].text = str(count)
            
            # Detailed Data Sections
            doc.add_heading('Detailed Data Analysis', level=1)
            
            # Adoption Barriers Section
            if not ab_df.empty:
                doc.add_heading('Adoption Barriers', level=2)
                ab_p = doc.add_paragraph()
                ab_p.add_run(f'Found {len(ab_df)} adoption barriers:')
                
                # Show critical/high severity barriers.  Round 4: route
                # severity classification through the canonical
                # ``normalize_severity_label`` so labels like
                # ``Severity 1 - Critical`` and ``S1 - Critical`` are
                # detected without false positives from substrings such
                # as ``Higher Priority`` (which the previous
                # ``str.contains('Critical|High', case=False)`` matched
                # by accident).  Same pattern Compact already uses.
                if 'SEVERITY_C' in ab_df.columns:
                    _sev_norm = ab_df['SEVERITY_C'].apply(normalize_severity_label)
                    critical_ab = ab_df[_sev_norm.isin(['Critical', 'High'])]
                else:
                    critical_ab = ab_df.iloc[0:0]
                if not critical_ab.empty:
                    ab_p.add_run(f' {len(critical_ab)} critical/high severity barriers requiring immediate attention.')
                
                # Show recent barriers — Round 3: use the run's analysis
                # window (``days``) so this sentence matches the report's
                # subtitle. The previous hardcoded 30 silently disagreed
                # with the rest of the document for any non-30-day run.
                # Round 11 / Phase 2.2: ``datetime.now()`` returns the
                # LOCAL clock, so the window cut-off drifted by the
                # operator's UTC offset (e.g. up to ~24h short for
                # west-coast US runs).  Switch to a UTC-anchored
                # cut-off so the count agrees with the
                # Snowflake-side ``_utc_window_start_iso`` predicate.
                # Also COALESCE OPEN_DATE_C → CREATED_DATE → CREATED_DATE_C
                # to match the canonical AB date expression used by
                # ``fetch_adoption_barriers`` (Round 11 / Phase 2.1).
                _ab_date_cols = [
                    c for c in ('OPEN_DATE_C', 'CREATED_DATE', 'CREATED_DATE_C')
                    if c in ab_df.columns
                ]
                if _ab_date_cols:
                    try:
                        try:
                            _recent_window = int(days)
                        except (TypeError, NameError, ValueError):
                            _recent_window = 30
                        # ``pd.Timestamp.now('UTC').tz_localize(None)`` aligns
                        # with the tz-stripped UTC values produced by
                        # ``parse_datetime_series`` elsewhere.
                        recent_cutoff = (
                            pd.Timestamp.now('UTC').tz_localize(None)
                            - pd.Timedelta(days=_recent_window)
                        )
                        _parsed_cols = []
                        for _c in _ab_date_cols:
                            _parsed = pd.to_datetime(
                                ab_df[_c], errors='coerce', utc=True
                            ).dt.tz_convert('UTC').dt.tz_localize(None)
                            _parsed_cols.append(_parsed)
                        # Coalesce: for each row pick the FIRST non-null
                        # parsed date in priority order.
                        _ab_canonical_date = _parsed_cols[0].copy()
                        for _p in _parsed_cols[1:]:
                            _ab_canonical_date = _ab_canonical_date.fillna(_p)
                        recent_ab = ab_df[_ab_canonical_date >= recent_cutoff]
                        if not recent_ab.empty:
                            ab_p.add_run(f' {len(recent_ab)} barriers created in the last {_recent_window} days.')
                    except Exception as _dt_err:
                        logger.debug(f"Subscription AB date parse error: {_dt_err}")
            else:
                doc.add_heading('Adoption Barriers', level=2)
                ab_p = doc.add_paragraph()
                ab_p.add_run('No adoption barriers found for this subscription.')
            
            # Action Plans Section
            if not ap_df.empty:
                doc.add_heading('Action Plans', level=2)
                ap_p = doc.add_paragraph()
                ap_p.add_run(f'Found {len(ap_df)} action plans:')
                
                # Show unresolved/completed plans.  Round 4: route status
                # classification through ``normalize_status_label`` so
                # variations ("In-Progress", "Completed - Cancelled",
                # mixed case, leading whitespace) are bucketed
                # consistently with the rest of the report.
                if 'STATUS_C' in ap_df.columns:
                    _status_norm = ap_df['STATUS_C'].apply(normalize_status_label)
                    unresolved_plans = ap_df[_status_norm.isin(['Open', 'New', 'In Progress'])]
                    completed_plans = ap_df[_status_norm.isin(['Completed', 'Closed'])]
                else:
                    unresolved_plans = ap_df.iloc[0:0]
                    completed_plans = ap_df.iloc[0:0]
                if not unresolved_plans.empty:
                    ap_p.add_run(f' {len(unresolved_plans)} unresolved action plans.')
                if not completed_plans.empty:
                    ap_p.add_run(f' {len(completed_plans)} completed action plans.')
            else:
                doc.add_heading('Action Plans', level=2)
                ap_p = doc.add_paragraph()
                ap_p.add_run('No action plans found for this subscription.')
            
            # Customer Pulse Section
            if not cp_df.empty:
                doc.add_heading('Customer Pulse', level=2)
                cp_p = doc.add_paragraph()
                cp_p.add_run(f'Found {len(cp_df)} customer pulse records:')
                
                # Show pulse ratings
                if 'PULSE_RATING__C' in cp_df.columns:
                    pulse_counts = cp_df['PULSE_RATING__C'].value_counts()
                    for rating, count in pulse_counts.items():
                        cp_p.add_run(f' {count} {rating} ratings.')
            else:
                doc.add_heading('Customer Pulse', level=2)
                cp_p = doc.add_paragraph()
                cp_p.add_run('No customer pulse records found for this subscription.')
            
            # Success Priorities Section
            if not sp_df.empty:
                doc.add_heading('Success Priorities', level=2)
                sp_p = doc.add_paragraph()
                sp_p.add_run(f'Found {len(sp_df)} success priorities:')
                
                # Show priority status
                if 'STATUS__C' in sp_df.columns:
                    status_counts = sp_df['STATUS__C'].value_counts()
                    for status, count in status_counts.items():
                        sp_p.add_run(f' {count} {status} priorities.')
            else:
                doc.add_heading('Success Priorities', level=2)
                sp_p = doc.add_paragraph()
                sp_p.add_run('No success priorities found for this subscription.')
            
            # AI Analysis
            if ai_response:
                doc.add_heading('AI Analysis', level=1)
                ai_p = doc.add_paragraph()
                ai_p.add_run(ai_response)
            
            with analysis_status_lock:
                _update_progress(status, 85, 'Saving Word document...', 'Report Generation')

            # Phase 1.1: Validate cross-source consistency for the subscription
            # report before persisting the docx. Subscription only has
            # adoption_barriers + customer_pulse for the single sub, so we feed
            # those through validate_report_consistency to catch obvious drift
            # (BEMS w/o cases, missing customer counts, etc).
            try:
                # Round 6 / Phase 5.8: thread ``strict_mode`` and any
                # available factual_claims (e.g. ai_response narrative
                # bullets) through the subscription path so the same
                # env toggle ADOPTIQ_NONSTRICT_CONSISTENCY governs
                # every report's strictness.
                _sub_strict = (
                    str(os.getenv("ADOPTIQ_NONSTRICT_CONSISTENCY", "0")).strip().lower()
                    not in {"1", "true", "yes", "on"}
                )
                _sub_factual_claims = []
                _sub_ai_resp = locals().get("ai_response")
                if isinstance(_sub_ai_resp, str) and _sub_ai_resp.strip():
                    _sub_factual_claims = [_sub_ai_resp.strip()]
                _sub_consistency = validate_report_consistency(
                    ab_df,
                    pd.DataFrame(),
                    customer_pulse_df=cp_df if isinstance(cp_df, pd.DataFrame) and not cp_df.empty else None,
                    strict_mode=_sub_strict,
                    factual_claims=_sub_factual_claims or None,
                )
                if not _sub_consistency.get('is_valid', True):
                    logger.error(
                        f"[[CONSISTENCY]] Subscription report errors: {_sub_consistency.get('errors')}"
                    )
                if _sub_consistency.get('warnings'):
                    logger.warning(
                        f"[[CONSISTENCY]] Subscription report warnings: {_sub_consistency.get('warnings')}"
                    )
            except Exception as _scerr:
                logger.warning(f"[[CONSISTENCY]] Subscription consistency check skipped: {_scerr}")

            doc.save(word_path)
            
        except Exception as e:
            logger.error(f"Error creating Word report: {e}")
            word_path = None
        
        with analysis_status_lock:
            _update_progress(status, 88, 'Generating Excel workbook...', 'Excel Report Generation')
        
        # Generate Excel report
        excel_filename = f"Subscription_Analysis_{safe_customer_name}_{safe_subscription_id}_{timestamp}.xlsx"
        excel_path = output_dir / excel_filename
        
        try:
            def _excel_safe_df(df: pd.DataFrame) -> pd.DataFrame:
                if df is None or df.empty:
                    return df
                safe_df = df.copy()
                for col in safe_df.columns:
                    series = safe_df[col]
                    try:
                        if pd.api.types.is_datetime64tz_dtype(series):
                            safe_df[col] = series.dt.tz_localize(None)
                            continue
                    except Exception:
                        # Round 4: non-fatal; suppressed silently in original code
                        pass  # noqa: PIE790
                    if series.dtype == object:
                        try:
                            safe_df[col] = series.apply(
                                lambda v: (
                                    v.tz_localize(None)
                                    if isinstance(v, pd.Timestamp) and v.tz is not None
                                    else (
                                        v.replace(tzinfo=None)
                                        if isinstance(v, datetime) and v.tzinfo is not None
                                        else v
                                    )
                                )
                            )
                        except Exception:
                            continue
                return safe_df

            # Excel engines do not support timezone-aware datetimes.
            ab_df = _excel_safe_df(ab_df)
            ap_df = _excel_safe_df(ap_df)
            cp_df = _excel_safe_df(cp_df)
            sp_df = _excel_safe_df(sp_df)

            with pd.ExcelWriter(excel_path, engine='xlsxwriter') as writer:
                workbook = writer.book
                
                # Create formats
                header_format = workbook.add_format({
                    'bold': True,
                    'text_wrap': True,
                    'valign': 'top',
                    'fg_color': '#D7E4BC',
                    'border': 1
                })
                
                title_format = workbook.add_format({
                    'bold': True,
                    'font_size': 14,
                    'fg_color': '#4F81BD',
                    'font_color': 'white',
                    'border': 1
                })
                
                # Summary sheet
                # Round 5 / Phase 1.12: normalize the Customer Name so the
                # subscription Summary sheet matches the canonical name used
                # by Leader / Renewal / Executive reports (avoids Cisco vs
                # Cisco Inc. drift surfaced by report_consistency).
                _raw_cust_name_summary = sub_data.get('customer_name') or 'Unknown'
                try:
                    _norm_cust_name_summary = normalize_customer_name(_raw_cust_name_summary) or _raw_cust_name_summary
                except Exception:
                    _norm_cust_name_summary = _raw_cust_name_summary
                summary_data = {
                    'Metric': ['Customer Name', 'Subscription ID', 'Technology', 'Sub-Technology', 'Status', 
                               'Analysis Period (Days)', 'Renewal Risk Score', 'Risk Level'],
                    'Value': [_norm_cust_name_summary, subscription_id, sub_data.get('technology', 'N/A'), 
                              sub_data.get('sub_technology', 'N/A'), sub_data.get('status', 'N/A'), days,
                              renewal_analysis.get('overall_risk_score', renewal_analysis.get('risk_score', 0)), renewal_analysis.get('risk_level', 'Unknown')]
                }
                summary_df = pd.DataFrame(summary_data)
                summary_df.to_excel(writer, sheet_name='Summary', index=False)
                
                # Risk Components sheet
                risk_data = []
                risk_components = renewal_analysis.get('risk_components', {})
                if not isinstance(risk_components, dict):
                    logger.warning("Subscription analysis risk_components has unexpected type; defaulting to empty set")
                    risk_components = {}
                for component, data in risk_components.items():
                    score_value = 0.0
                    count_value = 0
                    if isinstance(data, dict):
                        try:
                            score_value = float(data.get('score', 0) or 0)
                        except (TypeError, ValueError):
                            score_value = 0.0
                        raw_count = data.get('count', data.get('total', data.get('value', 0)))
                        try:
                            count_value = int(raw_count or 0)
                        except (TypeError, ValueError):
                            count_value = 0
                    risk_data.append({
                        'Component': component.replace('_', ' ').title(),
                        'Score': score_value,
                        'Count': count_value
                    })
                risk_df = pd.DataFrame(risk_data)
                # Round 5 / Phase 1.1: when no risk_components are returned
                # (e.g. risk scoring did not run because data was unavailable),
                # do not write a blank sheet - emit an explicit
                # ``Data_Unavailable`` row matching the renewal portfolio
                # honesty pattern at app_simple.py:8069-8080 / Round 4 1.6.
                if risk_df.empty:
                    risk_df = pd.DataFrame([{
                        'Component': 'Data_Unavailable',
                        'Score': 'n/a',
                        'Count': 'n/a',
                        'Reason': 'Risk components not returned by scoring pipeline (see Report_Info / partial_data_warnings).',
                    }])
                risk_df.to_excel(writer, sheet_name='Risk_Components', index=False)
                
                # Round 2 / Phase 2.6: derive empty-tab placeholder
                # columns from the live schema (the same df we would
                # have written if it had rows) so a "no data" tab and
                # a "data" tab share the same column shape.  When the
                # frame is empty AND has no schema (e.g. fetch failed
                # before columns were known), surface a
                # ``Data_Unavailable`` row that includes any
                # ``attrs['fetch_error']`` so the consumer can
                # distinguish "no rows in window" from "fetch failed
                # before schema known".
                def _write_empty_or_placeholder(empty_or_df, sheet, fallback_cols):
                    fetch_err = None
                    fetch_err_kind = None
                    try:
                        fetch_err = empty_or_df.attrs.get('fetch_error') if hasattr(empty_or_df, 'attrs') else None
                        fetch_err_kind = empty_or_df.attrs.get('fetch_error_kind') if hasattr(empty_or_df, 'attrs') else None
                    except Exception:
                        fetch_err = None
                    if fetch_err:
                        unavailable_df = pd.DataFrame([
                            {
                                'Status': 'Data Unavailable',
                                'Dataset': sheet,
                                'Reason': str(fetch_err_kind or 'fetch_error'),
                                'Detail': str(fetch_err)[:512],
                                'Generated_At': datetime.now(timezone.utc).strftime('%Y-%m-%d %H:%M:%S UTC'),
                            }
                        ])
                        unavailable_df.to_excel(writer, sheet_name=sheet, index=False)
                        return
                    # Round 6 / Phase 1.10: a header-only sheet still
                    # leaves the consumer guessing whether the window
                    # was empty or the call simply hadn't been wired.
                    # Mirror the Data_Unavailable shape with an
                    # explicit empty-window message so subscription
                    # workbooks never ship a silent-blank sheet.
                    cols = list(empty_or_df.columns) if hasattr(empty_or_df, 'columns') and len(empty_or_df.columns) > 0 else fallback_cols
                    pd.DataFrame(columns=cols).to_excel(writer, sheet_name=sheet, index=False)
                    try:
                        from report_utils import (
                            classify_data_state as _classify_state,
                            render_empty_state_message as _render_state,
                        )
                        _state = _classify_state(empty_or_df)
                        _msg = _render_state(_state, source_label=sheet.replace('_', ' '))
                    except Exception:
                        _state = 'empty'
                        _msg = 'No records in the analysis window'
                    try:
                        ws = writer.sheets[sheet]
                        # Write the empty-window message a few rows
                        # below the header so it is unmistakable in the
                        # rendered workbook.
                        ws.write(2, 0, f"{sheet.replace('_', ' ')} - {_state.upper()}")
                        ws.write(3, 0, _msg)
                        ws.write(
                            4, 0,
                            f"Generated: {datetime.now(timezone.utc).strftime('%Y-%m-%d %H:%M:%S UTC')}",
                        )
                    except Exception:
                        # Fall back silently; primary signal is the
                        # header-only frame already written above.
                        pass

                # Round 15 / Phase 1.4: subscription-renewal Excel writer
                # uses different sheet names from the manager-portfolio
                # writer (``Adoption_Barriers`` vs ``AB_Detail_All``) so
                # the curated allowlist does not apply, but the
                # denylist still strips SF plumbing (IS_DELETED, MAY_EDIT,
                # SYSTEM_MODSTAMP, _FIVETRAN_*) before write.
                def _r15_curate(_df, _sheet):
                    try:
                        return _r15_apply_export_schema(_df, sheet_name=_sheet)
                    except Exception as _e:
                        logger.debug("Round 15 export schema skipped for sheet '%s': %s", _sheet, _e)
                        return _df

                # Adoption Barriers
                if not ab_df.empty:
                    _r15_curate(ab_df, 'Adoption_Barriers').to_excel(writer, sheet_name='Adoption_Barriers', index=False)
                else:
                    _write_empty_or_placeholder(
                        ab_df, 'Adoption_Barriers',
                        ['ID', 'SUBJECT_C', 'SEVERITY_C', 'AB_STATUS_C', 'ASSIGNEE_C', 'CREATED_DATE', 'DESCRIPTION_C'],
                    )

                # Action Plans
                if not ap_df.empty:
                    _r15_curate(ap_df, 'Action_Plans').to_excel(writer, sheet_name='Action_Plans', index=False)
                else:
                    _write_empty_or_placeholder(
                        ap_df, 'Action_Plans',
                        ['ID', 'ACTION_PLAN_TITLE_C', 'STATUS_C', 'ASSIGNEE_C', 'CREATED_DATE', 'DESCRIPTION_C'],
                    )

                # Customer Pulse
                if not cp_df.empty:
                    _r15_curate(cp_df, 'Customer_Pulse').to_excel(writer, sheet_name='Customer_Pulse', index=False)
                else:
                    _write_empty_or_placeholder(
                        cp_df, 'Customer_Pulse',
                        ['ID', 'PULSE_RATING__C', 'COMMENTS__C', 'CREATEDDATE', 'ACCOUNT__C'],
                    )

                # Success Priorities
                if not sp_df.empty:
                    _r15_curate(sp_df, 'Success_Priorities').to_excel(writer, sheet_name='Success_Priorities', index=False)
                else:
                    _write_empty_or_placeholder(
                        sp_df, 'Success_Priorities',
                        ['ID', 'SUCCESS_PRIORITY_TITLE__C', 'STATUS__C', 'CREATEDDATE', 'RELATED_CUSTOMER__C'],
                    )
                
                # Format sheets
                for sheet_name in writer.sheets:
                    worksheet = writer.sheets[sheet_name]
                    worksheet.set_column('A:Z', 20)
                    
                    # Format headers for each sheet based on its actual data
                    if sheet_name == 'Summary':
                        # Format summary sheet headers
                        for col_num, value in enumerate(summary_df.columns.values):
                            worksheet.write(0, col_num, value, header_format)
                    elif sheet_name == 'Risk_Components':
                        # Round 5 / Phase 1.5: Risk_Components was previously
                        # left unformatted; format its headers (including the
                        # Data_Unavailable placeholder added in Phase 1.1).
                        try:
                            for col_num, value in enumerate(risk_df.columns.values):
                                worksheet.write(0, col_num, value, header_format)
                        except Exception:
                            pass  # noqa: PIE790
                        # Round 13 / Phase 9.9: previously the
                        # ``Risk_Components`` sheet shipped without
                        # band coloring on the ``Score`` column or
                        # consistent numeric formatting -- so the
                        # subscription renewal Excel disagreed with
                        # the matching Word body color cues (where
                        # CRITICAL/HIGH/MEDIUM/LOW are already mapped
                        # to ``RISK_BAND_COLORS``).  Apply
                        # conditional formatting from the canonical
                        # band thresholds + a numeric format to the
                        # ``Score`` column so the workbook renders
                        # the same risk gradient the chart uses.
                        try:
                            from canonical_metrics import (
                                RISK_BAND_COLORS as _R13_RBC,
                                RISK_BAND_THRESHOLDS as _R13_RBT,
                            )
                        except Exception:
                            _R13_RBC = {
                                'CRITICAL': '#d62728',
                                'HIGH': '#ff7f0e',
                                'MEDIUM': '#fdae61',
                                'LOW': '#2ca02c',
                                'HEALTHY': '#28B463',
                            }
                            _R13_RBT = None
                        try:
                            _r13_score_col = None
                            for _col_idx, _col_name in enumerate(list(risk_df.columns)):
                                if str(_col_name).strip().lower() == 'score':
                                    _r13_score_col = _col_idx
                                    break
                            if _r13_score_col is not None and len(risk_df) > 0:
                                _r13_book = writer.book
                                # Build per-band formats; tints lean
                                # slightly lighter than the chart hex
                                # so cell text stays readable on the
                                # background.
                                def _r13_fmt(hex_str: str):
                                    try:
                                        return _r13_book.add_format({'bg_color': hex_str, 'num_format': '0.0'})
                                    except Exception:
                                        return _r13_book.add_format({'num_format': '0.0'})
                                _r13_critical_fmt = _r13_fmt(_R13_RBC.get('CRITICAL', '#d62728'))
                                _r13_high_fmt = _r13_fmt(_R13_RBC.get('HIGH', '#ff7f0e'))
                                _r13_med_fmt = _r13_fmt(_R13_RBC.get('MEDIUM', '#fdae61'))
                                _r13_low_fmt = _r13_fmt(_R13_RBC.get('LOW', '#2ca02c'))
                                # Default thresholds align with
                                # ``cm.RISK_BAND_THRESHOLDS`` for the
                                # 0..10 scale: CRITICAL >= 8, HIGH >=
                                # 6, MEDIUM >= 4, LOW < 4.  Allow
                                # canonical override if available.
                                _r13_th_critical = 8.0
                                _r13_th_high = 6.0
                                _r13_th_medium = 4.0
                                try:
                                    if isinstance(_R13_RBT, dict):
                                        _r13_th_critical = float(_R13_RBT.get('CRITICAL', _r13_th_critical))
                                        _r13_th_high = float(_R13_RBT.get('HIGH', _r13_th_high))
                                        _r13_th_medium = float(_R13_RBT.get('MEDIUM', _r13_th_medium))
                                except Exception:
                                    pass
                                _r13_first_row = 1  # header is row 0
                                _r13_last_row = len(risk_df)
                                worksheet.conditional_format(
                                    _r13_first_row, _r13_score_col,
                                    _r13_last_row, _r13_score_col,
                                    {
                                        'type': 'cell',
                                        'criteria': '>=',
                                        'value': _r13_th_critical,
                                        'format': _r13_critical_fmt,
                                    },
                                )
                                worksheet.conditional_format(
                                    _r13_first_row, _r13_score_col,
                                    _r13_last_row, _r13_score_col,
                                    {
                                        'type': 'cell',
                                        'criteria': 'between',
                                        'minimum': _r13_th_high,
                                        'maximum': _r13_th_critical - 0.0001,
                                        'format': _r13_high_fmt,
                                    },
                                )
                                worksheet.conditional_format(
                                    _r13_first_row, _r13_score_col,
                                    _r13_last_row, _r13_score_col,
                                    {
                                        'type': 'cell',
                                        'criteria': 'between',
                                        'minimum': _r13_th_medium,
                                        'maximum': _r13_th_high - 0.0001,
                                        'format': _r13_med_fmt,
                                    },
                                )
                                worksheet.conditional_format(
                                    _r13_first_row, _r13_score_col,
                                    _r13_last_row, _r13_score_col,
                                    {
                                        'type': 'cell',
                                        'criteria': '<',
                                        'value': _r13_th_medium,
                                        'format': _r13_low_fmt,
                                    },
                                )
                        except Exception:
                            pass  # noqa: PIE790 - styling is best-effort
                    else:
                        # Format other sheets - check if they have data
                        if sheet_name in ['Adoption_Barriers', 'Action_Plans', 'Customer_Pulse', 'Success_Priorities']:
                            # These sheets have headers even when empty
                            if sheet_name == 'Adoption_Barriers' and not ab_df.empty:
                                for col_num, value in enumerate(ab_df.columns.values):
                                    worksheet.write(0, col_num, value, header_format)
                            elif sheet_name == 'Action_Plans' and not ap_df.empty:
                                for col_num, value in enumerate(ap_df.columns.values):
                                    worksheet.write(0, col_num, value, header_format)
                            elif sheet_name == 'Customer_Pulse' and not cp_df.empty:
                                for col_num, value in enumerate(cp_df.columns.values):
                                    worksheet.write(0, col_num, value, header_format)
                            elif sheet_name == 'Success_Priorities' and not sp_df.empty:
                                for col_num, value in enumerate(sp_df.columns.values):
                                    worksheet.write(0, col_num, value, header_format)
                            else:
                                # Empty sheets - format the empty DataFrame headers
                                empty_df = pd.DataFrame()
                                if sheet_name == 'Adoption_Barriers':
                                    empty_df = pd.DataFrame(columns=['ID', 'SUBJECT_C', 'SEVERITY_C', 'AB_STATUS_C', 'ASSIGNEE_C', 'CREATED_DATE', 'DESCRIPTION_C'])
                                elif sheet_name == 'Action_Plans':
                                    empty_df = pd.DataFrame(columns=['ID', 'ACTION_PLAN_TITLE_C', 'STATUS_C', 'ASSIGNEE_C', 'CREATED_DATE', 'DESCRIPTION_C'])
                                elif sheet_name == 'Customer_Pulse':
                                    empty_df = pd.DataFrame(columns=['ID', 'PULSE_RATING__C', 'COMMENTS__C', 'CREATEDDATE', 'ACCOUNT__C'])
                                elif sheet_name == 'Success_Priorities':
                                    empty_df = pd.DataFrame(columns=['ID', 'SUCCESS_PRIORITY_TITLE__C', 'STATUS__C', 'CREATEDDATE', 'RELATED_CUSTOMER__C'])
                                
                                for col_num, value in enumerate(empty_df.columns.values):
                                    worksheet.write(0, col_num, value, header_format)
            
        except Exception as e:
            logger.error(f"Error creating Excel report: {e}", exc_info=True)
            raise e
        
        with analysis_status_lock:
            _update_progress(status, 100, 'Subscription analysis completed successfully!', 'Completed')
            status['status'] = 'completed'
            status['word_file'] = word_filename if word_path else None
            status['excel_file'] = excel_filename
            status['word_report'] = str(word_path) if word_path else None
            status['excel_report'] = str(excel_path) if excel_path else None
            status['end_time'] = _now_utc_iso_z()
            status['completion_time'] = status['end_time']
            report_type = status.get('report_type', 'renewal')
            manager = status.get('manager', '')
            technology = status.get('technology', status.get('tech', ''))
            customer_name = status.get('customer_name', '')
            start_time = status.get('start_time', '')
            end_time = status['end_time']
            insights_payload = _build_insights_payload(status, 'Subscription analysis completed')

        # Persist outside lock to reduce lock contention during file I/O.
        save_analysis_status()

        auto_audit_report(analysis_id)
        # Round 3 / Phase 5.4: pass days, paths.
        record_report_completion(
            analysis_id, report_type, manager, technology, customer_name,
            'completed', start_time, end_time,
            days=status.get('days') if isinstance(status, dict) else None,
            word_path=str(word_path) if 'word_path' in locals() and word_path else '',
            excel_path=str(excel_path) if 'excel_path' in locals() and excel_path else '',
        )
        try:
            store_report_insights(
                analysis_id, report_type, manager, technology, customer_name, insights_payload
            )
        except Exception as _si_err:
            logger.warning(f"store_report_insights failed: {_si_err}")
        
        logger.info(f"[[OK]] Subscription analysis completed: {analysis_id}")
        
    except Exception as e:
        logger.error(f"[[ERROR]] Error in subscription analysis: {e}", exc_info=True)
        with analysis_status_lock:
            if analysis_id not in analysis_status:
                analysis_status[analysis_id] = {}
            analysis_status[analysis_id]['status'] = 'error'
            analysis_status[analysis_id]['message'] = 'Subscription analysis failed. Please check the Admin page for details.'
            analysis_status[analysis_id]['error'] = 'Subscription analysis failed. Please check the Admin page for details.'
            save_analysis_status()
    finally:
        with cancellation_flags_lock:
            cancellation_flags.pop(analysis_id, None)


@app.route('/download/<analysis_id>/<file_type>')
def download_result(analysis_id, file_type):
    """Download analysis results with enhanced error handling and logging"""
    from urllib.parse import unquote
    analysis_id = unquote(analysis_id)
    # Round 6 / Phase 6.7: do not log the raw ``analysis_id`` at INFO
    # -- it carries customer / manager / technology fragments and
    # ends up in shipped log files.  Surface a short SHA-256 prefix
    # at INFO and the verbatim id only at DEBUG.
    try:
        import hashlib as _h_p67
        _aid_digest = _h_p67.sha256(
            str(analysis_id).encode("utf-8", errors="replace")
        ).hexdigest()[:12]
    except Exception:
        _aid_digest = "unavailable"
    logger.info(
        "[[DOWNLOAD]] Download request: aid_digest=%s file_type=%s",
        _aid_digest, file_type,
    )
    logger.debug("[[DOWNLOAD]] Download request (verbose): %s/%s", analysis_id, file_type)

    # Validate file_type (whitelist)
    if file_type not in ('docx', 'xlsx'):
        return jsonify({'error': 'Invalid file type. Use docx or xlsx.', 'available_files': ['docx', 'xlsx']}), 404
    if not _is_valid_analysis_id(analysis_id):
        return jsonify({'error': 'Invalid analysis ID'}), 400
    
    with analysis_status_lock:
        status = analysis_status.get(analysis_id)
    if status is None:
        try:
            status_file_path = str(_APP_SUPPORT / STATUS_FILE) if not os.path.isabs(STATUS_FILE) else STATUS_FILE
            if os.path.exists(status_file_path):
                with open(status_file_path, 'r', encoding='utf-8') as f:
                    loaded_status = json.load(f)
                    if analysis_id in loaded_status:
                        loaded_entry = _hydrate_status_datetimes(loaded_status[analysis_id])
                        with analysis_status_lock:
                            analysis_status[analysis_id] = loaded_entry
                            status = analysis_status[analysis_id]
            if status is None:
                # Round 9 / Phase 1.3: previous error JSON echoed the raw
                # ``analysis_id`` route fragment (which embeds customer /
                # manager / technology slugs) back to the caller -- a
                # cross-tenant disclosure if a misrouted client happens
                # to surface the body.  Project to the same digest used
                # for INFO logging so the operator can correlate via the
                # log without exposing the embedded PII to the client.
                return jsonify({'error': 'Analysis not found', 'analysis_id_digest': _aid_digest}), 404
        except Exception as e:
            logger.error(f"[[ERROR]] Error loading analysis status from file: {e}", exc_info=True)
            return jsonify({'error': 'Analysis not found', 'analysis_id_digest': _aid_digest}), 404
    # Round 6 / Phase 6.7: keep state label only at INFO.  Do not
    # log the entire status dict or analysis id verbatim alongside.
    logger.info("[[DATA]] Analysis status: %s", status.get('status', 'unknown'))
    
    # Check if analysis is completed
    if status.get('status') != 'completed':
        logger.error(f"[[ERROR]] Analysis not completed: {status.get('status', 'unknown')}")
        # Round 9 / Phase 1.3: digest the analysis_id in the error body.
        return jsonify({
            'error': f'Analysis not completed. Current status: {status.get("status", "unknown")}',
            'analysis_id_digest': _aid_digest,
            'current_status': status.get('status', 'unknown')
        }), 400
    
    # Check if results exist - handle both formats (direct and nested in 'results')
    word_report = status.get('word_report')
    excel_report = status.get('excel_report')
    
    # For leader reports and some other report types, results are nested
    if not word_report and not excel_report:
        results = status.get('results', {})
        if isinstance(results, dict):
            word_report = results.get('word_report')
            excel_report = results.get('excel_report')
    
    if not word_report and not excel_report:
        logger.error(f"[[ERROR]] No reports available for analysis (digest=%s)", _aid_digest)
        # Round 13 / Phase 4.4: previously the client-visible JSON
        # echoed ``status.keys()`` (an internal step-name dictionary
        # such as ``current_step``, ``progress_internal``,
        # ``trace_id``, etc.).  That gave a remote caller a
        # fingerprint of our pipeline structure for free.  Keep the
        # diagnostic at server-side DEBUG only and ship a generic
        # public-facing error body.
        try:
            logger.debug("[[DATA]] Status structure (DEBUG only): %s", list(status.keys()))
        except Exception:
            pass
        return jsonify({
            'ok': False,
            'success': False,
            'error': 'No results available for this analysis',
            'analysis_id_digest': _aid_digest,
        }), 400
    
    # Round 6 / Phase 6.7: paths reveal customer / report names.
    # Keep them at DEBUG; surface a presence-only summary at INFO.
    logger.info(
        "[[FILE]] Available reports - Word: %s, Excel: %s",
        bool(word_report), bool(excel_report),
    )
    logger.debug(
        "[[FILE]] Available reports (verbose) - Word: %s, Excel: %s",
        word_report, excel_report,
    )
    
    # Canonical outputs dir (Application Support when frozen) so download works even if status stored wrong path
    _out_dir = _APP_SUPPORT / "outputs" if _frozen else Path(os.path.abspath("outputs"))

    def _resolve_safe_path(raw_path, out_dir):
        """Resolve file path and verify it's under the outputs directory."""
        out_abs = os.path.abspath(str(out_dir))
        prefix = out_abs + os.sep
        resolved = os.path.abspath(raw_path)
        if not os.path.exists(resolved):
            resolved = os.path.abspath(str(Path(out_dir) / os.path.basename(raw_path)))
        if not os.path.exists(resolved):
            return None
        if resolved == out_abs or resolved.startswith(prefix):
            return resolved
        return None

    try:
        if file_type == 'docx' and word_report:
            file_path = _resolve_safe_path(word_report, _out_dir)
            if not file_path:
                logger.error(f"[[ERROR]] Word file not found or outside outputs dir")
                return jsonify({'error': 'Word file not found'}), 404
            safe_name = secure_filename(analysis_id) or "report"
            try:
                return send_file(file_path, as_attachment=True, download_name=f"AdoptIQ_Report_{safe_name}.docx")
            except (FileNotFoundError, OSError):
                return jsonify({'error': 'Word file no longer available'}), 404

        elif file_type == 'xlsx' and excel_report:
            file_path = _resolve_safe_path(excel_report, _out_dir)
            if not file_path:
                logger.error(f"[[ERROR]] Excel file not found or outside outputs dir")
                return jsonify({'error': 'Excel file not found'}), 404
            safe_name = secure_filename(analysis_id) or "data"
            try:
                return send_file(file_path, as_attachment=True, download_name=f"AdoptIQ_Data_{safe_name}.xlsx")
            except (FileNotFoundError, OSError):
                return jsonify({'error': 'Excel file no longer available'}), 404
            
        else:
            available = []
            if word_report:
                available.append('docx')
            if excel_report:
                available.append('xlsx')
            if file_type == 'xlsx' and not excel_report:
                logger.warning(f"[[WARNING]] Excel file not generated for analysis: {analysis_id}")
                return jsonify({
                    'error': 'Excel file was not generated for this report. Only the Word document is available.',
                    'available_files': available
                }), 404
            logger.error(f"[[ERROR]] Invalid file type or file not found: {file_type}")
            return jsonify({
                'error': f'Invalid file type or file not found: {file_type}',
                'available_files': available
            }), 404
            
    except Exception as e:
        logger.error(f"[[ERROR]] Download error: {e}")
        return jsonify({'error': 'Download failed due to an internal error'}), 500


@app.route('/simple_test', methods=['POST'])
def simple_test():
    """Ultra-simple test endpoint"""
    # Round 8 / Phase 1.1: CSRF parity with other state-changing POST routes.
    # The endpoint is a no-op success acknowledgement, but accepting unauthenticated
    # cross-site POSTs makes it usable as an oracle / health probe for attackers
    # mapping the loopback surface area.  Validate via the same header/body
    # pattern used by ``start_subscription_analysis`` etc.
    if app.config.get('WTF_CSRF_ENABLED', True):
        try:
            validate_csrf(request.headers.get('X-CSRFToken') or request.headers.get('X-CSRF-Token') or request.form.get('csrf_token'))
        except Exception:
            return jsonify({'ok': False, 'success': False, 'error': 'CSRF validation failed'}), 403  # Round 13 / Phase 4.3
    try:
        logger.info(f"[[SEARCH]] Simple test endpoint called")
        return jsonify({'success': True, 'message': 'Simple test successful'})
    except Exception as e:
        logger.error(f"[[ERROR]] Simple test failed: {e}")
        return jsonify({'success': False, 'error': 'Test endpoint failed'}), 500

@app.route('/test_generate_report', methods=['POST'])
def test_generate_report():
    """Test endpoint that returns success immediately"""
    # Round 8 / Phase 1.1: CSRF parity.  This route writes into ``analysis_status``
    # and persists it -- a cross-site POST could populate the live status dict
    # with attacker-controlled manager/technology values.
    if app.config.get('WTF_CSRF_ENABLED', True):
        try:
            validate_csrf(request.headers.get('X-CSRFToken') or request.headers.get('X-CSRF-Token') or request.form.get('csrf_token'))
        except Exception:
            return jsonify({'ok': False, 'success': False, 'error': 'CSRF validation failed'}), 403  # Round 13 / Phase 4.3
    try:
        logger.info(f"[[SEARCH]] Test generate report endpoint called")

        # Handle both JSON and form data
        if request.is_json:
            data = request.get_json() or {}
            # Round 8 / Phase 1.7: do not echo the raw payload (manager,
            # technology, etc.) at INFO; summarise via the redactor so the
            # log line still proves receipt without exposing the values.
            logger.info("[[LIST]] JSON data received shape=%s", _redact_form_data(data))
        else:
            # Handle form data
            try:
                days_val = int(request.form.get('days', 30))
            except (ValueError, TypeError):
                days_val = 30
            data = {
                'manager': request.form.get('manager', 'Test Manager'),
                'technology': request.form.get('technology', 'Cisco UCCE'),
                'days': days_val
            }
            logger.info("[[LIST]] Form data received shape=%s", _redact_form_data(data))

        manager = data.get('manager', 'Test Manager')
        technology = data.get('technology', 'Cisco UCCE')
        days = data.get('days', 30)

        # Create a test analysis ID
        analysis_id = (
            f"Test_{_sanitize_analysis_id_part(manager)}_"
            f"{_sanitize_analysis_id_part(technology)}_{days}d_{int(time.time())}"
        )

        # Round 8 / Phase 1.7: digest at INFO; verbatim id only at DEBUG.
        logger.info("[[LIST]] Created analysis aid_digest=%s", _id_digest(analysis_id))
        logger.debug("[[LIST]] Created analysis verbatim id=%s", analysis_id)
        
        # Set up minimal status
        with analysis_status_lock:
            analysis_status[analysis_id] = {
                'status': 'completed',
                'progress': 100,
                'message': 'Test analysis completed successfully',
                'manager': manager,
                'technology': technology,
                'days': days,
                'start_time': _now_utc_iso_z(),
                'current_step': 'Test Complete',
                'report_type': 'compact'
            }
            save_analysis_status()
        
        # Round 8 / Phase 1.7: digest at INFO; verbatim id only at DEBUG.
        logger.info("[[OK]] Test analysis completed aid_digest=%s", _id_digest(analysis_id))
        logger.debug("[[OK]] Test analysis completed verbatim id=%s", analysis_id)
        
        return jsonify({
            'success': True,
            'analysis_id': analysis_id,
            'message': 'Test analysis completed successfully',
            'redirect_url': f'/progress/{analysis_id}'
        })
        
    except Exception as e:
        logger.error(f"[[ERROR]] Test analysis failed: {e}")
        return jsonify({'success': False, 'error': 'Test analysis failed'}), 500

@app.route('/clear_stuck_analyses', methods=['POST'])
def clear_stuck_analyses():
    """Clear any stuck analyses that might be blocking new ones"""
    # Round 8 / Phase 1.1: state-changing route was missing CSRF parity with
    # ``cancel_analysis`` / ``start_subscription_analysis``.  Without it any
    # cross-site POST that the browser sends with the session cookie can wipe
    # the in-flight analyses dict.
    if app.config.get('WTF_CSRF_ENABLED', True):
        try:
            validate_csrf(request.headers.get('X-CSRFToken') or request.headers.get('X-CSRF-Token') or request.form.get('csrf_token'))
        except Exception:
            return jsonify({'ok': False, 'success': False, 'error': 'CSRF validation failed'}), 403  # Round 13 / Phase 4.3
    try:
        with analysis_status_lock:
            cleared_count = 0
            # Round 8 / Phase 1.5: previously this fell back to a *naive*
            # local-clock ``datetime.now()`` when the persisted ``start_time``
            # didn't carry a tzinfo, then subtracted UTC-derived values from
            # local time -- on a non-UTC host the "stuck" cutoff drifted by
            # the local offset (PT analyses looked 7-8h newer than they were
            # and never tripped the 10-minute threshold).  Anchor on
            # ``datetime.now(timezone.utc)`` so every comparison is on the
            # same UTC clock as the persisted ISO ``Z`` ``start_time``.
            current_time = datetime.now(timezone.utc)

            for analysis_id, status in list(analysis_status.items()):
                # Clear analyses that have been running for more than 10 minutes
                if status.get('status') in ('running', 'starting', 'cancelling'):
                    start_value = status.get('start_time')
                    try:
                        if isinstance(start_value, datetime):
                            start_time = start_value
                        elif isinstance(start_value, str) and start_value:
                            start_time = datetime.fromisoformat(start_value.replace('Z', '+00:00'))
                        else:
                            start_time = None

                        if start_time is None:
                            status['status'] = 'cancelled'
                            status['message'] = 'Analysis cancelled - was stuck'
                            cleared_count += 1
                            continue

                        # Round 8 / Phase 1.5: if the parsed ``start_time``
                        # is naive, treat it as already-UTC (legacy rows) so
                        # both sides are tz-aware before subtraction.
                        if start_time.tzinfo is None:
                            start_time = start_time.replace(tzinfo=timezone.utc)
                        now_for_age = current_time
                        if (now_for_age - start_time).total_seconds() > 600:  # 10 minutes
                            status['status'] = 'cancelled'
                            status['message'] = 'Analysis cancelled - was stuck'
                            cleared_count += 1
                    except Exception:
                        # If we can't parse the time, clear it anyway
                        status['status'] = 'cancelled'
                        status['message'] = 'Analysis cancelled - was stuck'
                        cleared_count += 1
            
            if cleared_count > 0:
                save_analysis_status()
                logger.info(f"[[CLEAN]] Cleared {cleared_count} stuck analyses")
                return jsonify({'success': True, 'message': f'Cleared {cleared_count} stuck analyses'})
            else:
                return jsonify({'success': True, 'message': 'No stuck analyses found'})
                
    except Exception as e:
        logger.error(f"[[ERROR]] Error clearing stuck analyses: {e}")
        return jsonify({'success': False, 'error': 'Failed to clear stuck analyses'}), 500


